-- =============================================================================
-- 402 — LE CATALOGUE DES CONTRÔLES BLANCS : 3e (svt, technologie)
--
-- 162 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 402 --niveau 3e --matieres svt,technologie
--
--   svt.01a                      45 sujets · 15 fiches
--   svt.01r                      45 sujets · 15 fiches
--   svt.02                        3 sujets · 1 fiches
--   technologie.10a              24 sujets · 8 fiches
--   technologie.10r              45 sujets · 15 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 1, 'application', $exo${"titre":"Ranger le système solaire","consigne":"Réponds à chaque question en phrases courtes, avec le vocabulaire du cours.","enonce":"**Situation.** Pour un exposé, Maëlys doit présenter les planètes du système solaire et les mouvements de la Terre.\n\n1. Range les huit planètes suivantes en trois familles et nomme chaque famille : Jupiter, Mars, Neptune, Vénus, Saturne, Mercure, Uranus, la Terre.\n2. Donne un caractère commun aux planètes de la famille de la Terre.\n3. Recopie et complète le tableau :\n\n| Le mouvement de la Terre | Sa durée | Ce qu'il produit |\n|---|---|---|\n| La rotation | … | … |\n| La révolution | … | … |","bareme":[{"critere":"Les trois familles nommées et les huit planètes correctement classées","points":9},{"critere":"Un caractère exact des planètes telluriques (petites, rocheuses, denses ou proches du Soleil)","points":3},{"critere":"Tableau des mouvements juste : durées et effets de la rotation et de la révolution","points":8}],"dureeMin":6,"corrige":"1. **Planètes telluriques** : Mercure, Vénus, la Terre, Mars. **Géantes gazeuses** : Jupiter, Saturne. **Géantes glacées** : Uranus, Neptune.\n2. Les planètes telluriques sont **petites, rocheuses, denses** et **proches du Soleil** (un seul caractère suffit).\n3. \n| Le mouvement | Sa durée | Ce qu'il produit |\n|---|---|---|\n| La **rotation** de la Terre sur elle-même | **24 heures** | L'alternance **jour-nuit** |\n| La **révolution** autour du Soleil | **365,25 jours** | L'**année** |\n\nAccepter « environ 365 jours » pour la révolution."}$exo$::jsonb),
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 2, 'application', $exo${"titre":"Trois voisines, une seule habitable","consigne":"Exploite le document puis réponds en justifiant avec le cours.","enonce":"**Document – Trois planètes telluriques**\n\n| Planète | Distance moyenne au Soleil | Température moyenne en surface | Atmosphère |\n|---|---|---|---|\n| Vénus | 108 millions de km | environ 460 °C | très épaisse, riche en dioxyde de carbone |\n| La Terre | 150 millions de km | environ 15 °C | présente, avec une couche d'ozone |\n| Mars | 228 millions de km | environ −60 °C | presque inexistante |\n\n1. Sous quel état l'eau peut-elle se trouver à la surface de la Terre ? Quelle condition, lue dans le document, le permet ?\n2. Sans effet de serre naturel, quelle serait la température moyenne de la Terre ? Que montre la comparaison avec la valeur du document ?\n3. En t'appuyant sur le document et le cours, explique pourquoi Vénus est trop chaude et pourquoi Mars est trop froide pour être habitable.","bareme":[{"critere":"Eau liquide sur Terre reliée à sa distance au Soleil","points":5},{"critere":"−18 °C sans effet de serre, gain d'environ 33 °C grâce à l'effet de serre naturel","points":6},{"critere":"Vénus : emballement de l'effet de serre (atmosphère épaisse de CO₂)","points":5},{"critere":"Mars : atmosphère perdue, pas d'effet de serre pour la réchauffer","points":4}],"dureeMin":10,"corrige":"1. Sur Terre, l'eau peut être **liquide**. C'est permis par sa **distance au Soleil** (150 millions de km) : ni trop près comme Vénus, ni trop loin comme Mars.\n2. Sans effet de serre naturel, la température moyenne serait d'environ **−18 °C**. Avec lui, elle est d'environ **+15 °C** : l'effet de serre naturel réchauffe la Terre d'environ **33 °C** et la rend habitable. (Sa masse lui permet aussi de retenir son atmosphère.)\n3. **Vénus** est plus proche du Soleil et possède une atmosphère très épaisse, riche en CO₂ : son effet de serre s'est **emballé**, d'où environ 460 °C, beaucoup trop pour de l'eau liquide et la vie.\n**Mars** est plus loin du Soleil et a **perdu son atmosphère** : sans atmosphère, pas d'effet de serre pour la réchauffer, d'où environ −60 °C ; l'eau y serait gelée.\nConclusion : l'équilibre qui rend la Terre habitable est **étroit**."}$exo$::jsonb),
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 3, 'application', $exo${"titre":"Plus près du Soleil en hiver ?","consigne":"Analyse les documents et construis une réponse argumentée, en mobilisant plusieurs notions du chapitre.","enonce":"**Situation.** Léo affirme : « C'est l'été quand la Terre est plus proche du Soleil, et l'hiver quand elle en est plus loin. »\n\n**Document 1 – La distance Terre-Soleil au cours de l'année**\n\n| Date | Distance Terre-Soleil |\n|---|---|\n| Début janvier | environ 147 millions de km (la plus courte) |\n| Début juillet | environ 152 millions de km (la plus longue) |\n\n**Document 2 – Deux villes le 1er janvier**\n\n> À Paris (hémisphère Nord), c'est l'hiver. Au même moment, à Sydney (hémisphère Sud), c'est l'été.\n\n**Document 3 – Le temps long**\n\n> La Terre est âgée de 4,54 milliards d'années. *Homo sapiens* est apparu il y a environ 300 000 ans.\n\n1. Montre, à l'aide des documents 1 et 2, que l'explication de Léo est fausse (deux arguments).\n2. Explique la véritable cause des saisons et pourquoi l'hémisphère en été chauffe davantage.\n3. Si toute l'histoire de la Terre tenait dans une année de 365 jours, combien de minutes avant minuit le 31 décembre *Homo sapiens* apparaîtrait-il ? Détaille le calcul (1 an = 525 600 minutes) et commente le résultat.","bareme":[{"critere":"Deux arguments tirés des documents qui réfutent l'explication par la distance","points":6},{"critere":"Inclinaison de l'axe de 23,5° citée comme cause des saisons","points":4},{"critere":"Rayons plus verticaux et journées plus longues dans l'hémisphère en été","points":4},{"critere":"Calcul posé et résultat d'environ 35 minutes, avec commentaire sur le temps long","points":6}],"dureeMin":16,"corrige":"1. Premier argument (doc. 1) : début janvier, la Terre est au plus **près** du Soleil, et pourtant c'est l'**hiver** en France. Deuxième argument (doc. 2) : le **même jour**, il est l'hiver à Paris et l'été à Sydney ; or les deux villes sont à la même distance du Soleil. La distance ne peut donc pas expliquer les saisons. (De plus, l'écart de distance, environ 5 millions de km, est faible.)\n2. Les saisons s'expliquent par l'**inclinaison de l'axe de rotation de la Terre (23,5°)**, qui garde la même direction pendant la révolution. L'hémisphère penché vers le Soleil reçoit les rayons **plus à la verticale** (l'énergie se concentre sur une petite surface) et **plus longtemps** (journées longues) : il chauffe davantage, c'est l'été. Pendant ce temps, l'autre hémisphère est en hiver.\n3. Part de l'histoire de la Terre : 300 000 ÷ 4 540 000 000 ≈ 0,000066.\nEn minutes : 0,000066 × 525 600 ≈ **35 minutes**.\n*Homo sapiens* apparaîtrait vers **23 h 25 le 31 décembre**, dans les dernières minutes de l'année. Commentaire : l'espèce humaine est extrêmement récente à l'échelle des temps géologiques ; la Terre a existé des milliards d'années sans nous. (Accepter 34 à 35 minutes.)"}$exo$::jsonb),
  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 1, 'application', $exo${"titre":"Les mots de la tectonique","consigne":"Réponds en utilisant le vocabulaire précis du cours.","enonce":"**Situation.** Sacha révise la tectonique des plaques avec des fiches.\n\n1. Qu'est-ce que la lithosphère ? Sur quelle couche se déplace-t-elle, et à quelle vitesse ?\n2. Associe chaque frontière de plaques à ce qui s'y passe :\n   - a. frontière divergente\n   - b. subduction\n   - c. collision\n   - d. frontière coulissante\n\n   Ce qui s'y passe : (1) une plaque océanique plonge sous une autre ; (2) deux plaques glissent l'une contre l'autre ; (3) les plaques s'écartent et de la lithosphère neuve se forme ; (4) deux plaques continentales se heurtent.\n3. Donne un exemple de chaîne de montagnes formée par collision.","bareme":[{"critere":"Lithosphère définie (croûte et manteau supérieur rigide), asthénosphère et quelques cm par an","points":7},{"critere":"Les quatre associations justes","points":10},{"critere":"Exemple correct : Himalaya ou Alpes","points":3}],"dureeMin":6,"corrige":"1. La **lithosphère** est la couche rigide formée de la **croûte** et de la **partie supérieure du manteau**. Elle est découpée en une douzaine de plaques qui se déplacent sur l'**asthénosphère**, plus ductile, à une vitesse de **quelques centimètres par an**.\n2. a → (3) : aux **dorsales**, les plaques s'écartent et du magma crée de la lithosphère neuve.\nb → (1) : en **subduction**, une plaque océanique plonge (fosse océanique).\nc → (4) : en **collision**, deux plaques continentales se heurtent.\nd → (2) : à une frontière **coulissante**, les plaques glissent le long d'une faille transformante.\n3. L'**Himalaya** (ou les **Alpes**)."}$exo$::jsonb),
  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 2, 'application', $exo${"titre":"L'Atlantique Sud s'élargit","consigne":"Exploite le document, pose tes calculs et justifie avec le cours.","enonce":"**Document – L'océan Atlantique Sud**\n\n> Entre l'Afrique et l'Amérique du Sud, l'océan Atlantique mesure environ 5 000 km de large. Au milieu de l'océan court une dorsale. De part et d'autre, les roches du fond océanique sont de plus en plus âgées à mesure qu'on s'éloigne de la dorsale. L'Afrique et l'Amérique du Sud s'écartent l'une de l'autre d'environ 4 cm par an.\n\n1. Quel type de frontière de plaques se trouve au milieu de l'Atlantique ? Explique ce qui s'y passe.\n2. Pourquoi les roches sont-elles de plus en plus âgées quand on s'éloigne de la dorsale ?\n3. En supposant que la vitesse est restée constante, calcule depuis combien de temps l'Afrique et l'Amérique du Sud ont commencé à s'écarter (1 km = 100 000 cm). Compare avec l'âge de la Pangée.","bareme":[{"critere":"Frontière divergente : écartement, remontée de magma, lithosphère neuve","points":6},{"critere":"Âge croissant expliqué par l'expansion océanique (le fond se crée à la dorsale puis s'éloigne)","points":5},{"critere":"Conversion et calcul justes : environ 125 millions d'années","points":6},{"critere":"Comparaison cohérente avec la Pangée (environ 250 millions d'années)","points":3}],"dureeMin":11,"corrige":"1. C'est une **frontière divergente** : au niveau de la **dorsale**, les deux plaques **s'écartent**, du **magma remonte** et forme de la **lithosphère neuve** (volcanisme effusif, séismes superficiels).\n2. Le fond océanique se **forme à la dorsale**, puis il est **écarté** de part et d'autre à mesure que de la lithosphère neuve se crée : plus une roche est loin de la dorsale, plus elle s'est formée il y a longtemps. C'est l'**expansion océanique**.\n3. 5 000 km = 5 000 × 100 000 = **500 000 000 cm**.\nDurée = 500 000 000 ÷ 4 = **125 000 000 ans**, soit environ **125 millions d'années**.\nC'est **plus récent** que la Pangée (environ 250 millions d'années) : l'ouverture de l'Atlantique Sud a commencé **après** que la Pangée s'est formée, quand elle s'est fragmentée. C'est cohérent avec le déplacement des continents."}$exo$::jsonb),
  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 3, 'application', $exo${"titre":"Quatre régions, quatre frontières","consigne":"Analyse les documents, identifie chaque frontière en justifiant, puis explique le moteur et le recyclage de la surface.","enonce":"**Document – Observations dans quatre régions**\n\n| Région | Observations |\n|---|---|\n| Islande | coulées de lave fluide, séismes peu profonds, le pays s'élargit de quelques cm par an |\n| Japon | fosse océanique au large, séismes jusqu'à plusieurs centaines de km de profondeur, volcans aux éruptions explosives |\n| Himalaya | très hautes montagnes, deux continents face à face, séismes |\n| Californie (faille de San Andreas) | séismes fréquents, aucun volcan, deux blocs qui glissent horizontalement l'un contre l'autre |\n\n1. Pour chaque région, nomme le type de frontière de plaques et justifie avec au moins une observation.\n2. Quel est le moteur du déplacement des plaques ? Cite ses trois éléments.\n3. Explique la phrase : « la surface de la Terre se recycle », en t'appuyant sur deux des régions du document.\n4. Wegener avait proposé la dérive des continents en 1912 ; pourquoi son idée a-t-elle d'abord été rejetée, et qu'est-ce qui l'a confirmée dans les années 1960 ?","bareme":[{"critere":"Les quatre frontières identifiées et justifiées par une observation du document","points":8},{"critere":"Moteur : chaleur interne, convection du manteau, traction de la plaque plongeante","points":4},{"critere":"Recyclage : création aux dorsales (Islande) et disparition en subduction (Japon)","points":4},{"critere":"Rejet faute de moteur ; confirmation par fonds océaniques, sismologie, anomalies magnétiques","points":4}],"dureeMin":18,"corrige":"1. **Islande** : frontière **divergente** (dorsale) – lave fluide (volcanisme effusif), séismes superficiels, écartement.\n**Japon** : frontière convergente en **subduction** – fosse océanique, séismes profonds, volcanisme explosif.\n**Himalaya** : frontière convergente en **collision** – deux continents qui se heurtent, chaîne de montagnes.\n**Californie** : frontière **coulissante** – glissement horizontal le long d'une faille transformante, séismes sans volcanisme.\n2. Le moteur est la **chaleur interne** de la Terre (radioactivité et formation de la planète), qui entretient la **convection du manteau**, laquelle entraîne les plaques ; la **traction de la plaque plongeante** en subduction y contribue fortement.\n3. De la lithosphère **neuve se forme aux dorsales** (Islande) et de la lithosphère océanique **disparaît en plongeant** dans le manteau aux zones de subduction (Japon). Ce qui naît d'un côté disparaît de l'autre : la surface ne grandit pas, elle **se renouvelle**.\n4. L'idée de Wegener (forme des côtes, fossiles identiques, chaînes continues, traces glaciaires) a été rejetée car il ne pouvait pas **expliquer le moteur** du déplacement. Elle a été confirmée dans les années 1960 par la **cartographie des fonds océaniques**, la **sismologie** et les **anomalies magnétiques symétriques** de part et d'autre des dorsales, qui prouvent l'**expansion océanique**."}$exo$::jsonb),
  ('f8a8c587-11c9-50d2-9266-7705de781e3d'::uuid, 1, 'application', $exo${"titre":"Du foyer à l'épicentre","consigne":"Réponds aux questions en utilisant le vocabulaire du cours.","enonce":"**Situation.** Un séisme s'est produit dans les Pyrénées. Le journal écrit : « Le foyer était situé à 10 km de profondeur ; l'épicentre se trouvait près d'un village. La secousse a été ressentie fortement dans ce village, faiblement à Toulouse. »\n\n1. Définis le foyer et l'épicentre d'un séisme.\n2. Remets dans l'ordre les étapes d'un séisme : (a) les roches cassent ; (b) les mouvements de plaques déforment les roches ; (c) l'énergie part en ondes sismiques ; (d) les roches accumulent de l'énergie élastique.\n3. Ce séisme aura-t-il une seule magnitude ou plusieurs ? Et une seule intensité ou plusieurs ? Justifie avec le texte.","bareme":[{"critere":"Foyer (point de rupture en profondeur) et épicentre (à sa verticale en surface) bien définis","points":6},{"critere":"Ordre des étapes juste : b, d, a, c","points":6},{"critere":"Une seule magnitude (énergie libérée), plusieurs intensités (effets selon le lieu), justifié","points":8}],"dureeMin":6,"corrige":"1. Le **foyer** (ou hypocentre) est le **point de rupture des roches, en profondeur** (ici à 10 km). L'**épicentre** est le point de la surface situé **à la verticale du foyer** ; les dégâts y sont en général les plus forts.\n2. Ordre : **(b)** les mouvements de plaques déforment les roches → **(d)** elles accumulent de l'énergie élastique → **(a)** la contrainte dépasse leur résistance, elles cassent le long d'une faille → **(c)** l'énergie est libérée en ondes sismiques.\n3. Le séisme a **une seule magnitude**, car la magnitude mesure l'**énergie libérée**, qui est unique. Il a **plusieurs intensités** : l'intensité mesure les **effets ressentis et observés en un lieu** ; le texte montre qu'elle est forte au village près de l'épicentre et faible à Toulouse."}$exo$::jsonb),
  ('f8a8c587-11c9-50d2-9266-7705de781e3d'::uuid, 2, 'application', $exo${"titre":"Deux séismes de 2010","consigne":"Exploite le document et explique le paradoxe à l'aide des notions d'aléa, de vulnérabilité et de risque.","enonce":"**Document – Deux séismes de l'année 2010**\n\n| | Haïti (janvier 2010) | Chili (février 2010) |\n|---|---|---|\n| Magnitude | 7,0 | 8,8 |\n| Victimes | plus de 200 000 | environ 500 |\n| Constructions | nombreux bâtiments fragiles, peu de normes appliquées | normes parasismiques appliquées depuis des décennies |\n| Population | capitale très densément peuplée, près de l'épicentre | |\n\n1. Lequel de ces deux séismes a libéré le plus d'énergie ? Justifie.\n2. Définis l'aléa, la vulnérabilité et le risque sismique.\n3. Explique pourquoi le séisme le moins puissant a fait beaucoup plus de victimes.\n4. Sur lequel des deux termes, aléa ou vulnérabilité, peut-on agir ? Donne deux moyens.","bareme":[{"critere":"Chili : magnitude plus forte donc plus d'énergie libérée (échelle logarithmique)","points":4},{"critere":"Aléa, vulnérabilité et risque correctement définis","points":6},{"critere":"Paradoxe expliqué par la vulnérabilité : constructions fragiles, forte densité","points":6},{"critere":"Action sur la vulnérabilité seulement, avec deux moyens du cours","points":4}],"dureeMin":11,"corrige":"1. Le séisme du **Chili** (magnitude 8,8) a libéré beaucoup plus d'énergie que celui d'Haïti (7,0) : la magnitude mesure l'énergie libérée et l'échelle est **logarithmique** (+1 = environ 30 fois plus d'énergie).\n2. L'**aléa** est la probabilité qu'un séisme se produise ; la **vulnérabilité** désigne les personnes, bâtiments et activités exposés ; le **risque** est le **croisement de l'aléa et de la vulnérabilité**.\n3. En Haïti, la **vulnérabilité** était très forte : bâtiments fragiles, normes peu appliquées, population très dense près de l'épicentre. Au Chili, les **normes parasismiques** protégeaient la population. Un séisme modéré peut donc faire plus de victimes qu'un séisme puissant si les constructions sont fragiles et la population dense.\n4. On ne peut **pas agir sur l'aléa** (on ne sait ni empêcher ni prédire la date d'un séisme). On agit sur la **vulnérabilité** : **normes parasismiques** de construction, **cartographie des zones sismiques**, **éducation** aux bons réflexes et organisation des **secours**, surveillance par des sismographes (deux moyens attendus)."}$exo$::jsonb),
  ('f8a8c587-11c9-50d2-9266-7705de781e3d'::uuid, 3, 'application', $exo${"titre":"Un plan séisme pour Pointe-à-Pitre","consigne":"Analyse la situation et les documents, puis rédige des réponses argumentées qui mobilisent tout le chapitre.","enonce":"**Situation.** Le conseil municipal d'une ville de Guadeloupe prépare un plan contre le risque sismique. Un élu propose : « Achetons un appareil qui prédira la date du prochain séisme, et nous évacuerons la veille. »\n\n**Document 1 – Deux séismes comparés**\n\n> Séisme A : magnitude 6. Séisme B : magnitude 8.\n\n**Document 2 – Les Antilles**\n\n> Les Antilles ont une sismicité forte : les normes parasismiques y sont obligatoires. Les villes sont en bord de mer.\n\n1. Explique, depuis le déplacement des plaques jusqu'aux secousses, comment se produit un séisme.\n2. Combien de fois plus d'énergie le séisme B libère-t-il que le séisme A ? Détaille le calcul.\n3. Que penses-tu de la proposition de l'élu ? Justifie.\n4. Propose au conseil trois mesures efficaces, en expliquant pour chacune ce qu'elle apporte. L'une doit tenir compte de la position des villes en bord de mer.","bareme":[{"critere":"Mécanisme complet : déformation, énergie élastique, rupture le long d'une faille, ondes","points":5},{"critere":"Calcul juste : 30 × 30 = environ 900 fois plus d'énergie","points":4},{"critere":"Proposition réfutée : on ne sait pas prédire la date d'un séisme","points":4},{"critere":"Trois mesures pertinentes expliquées, dont l'alerte tsunami","points":5},{"critere":"Réponses rédigées et argumentées avec le vocabulaire (aléa, vulnérabilité)","points":2}],"dureeMin":18,"corrige":"1. Les mouvements des plaques **déforment les roches**, qui **accumulent de l'énergie élastique**. Quand la contrainte dépasse leur résistance, les roches **cassent brutalement le long d'une faille**, au **foyer**. L'énergie est libérée d'un coup sous forme d'**ondes sismiques** qui font vibrer le sol, surtout à l'**épicentre** ; des répliques suivent souvent.\n2. B a une magnitude supérieure de 2. Chaque degré = environ **30 fois** plus d'énergie, donc 30 × 30 = **environ 900 fois** plus d'énergie.\n3. La proposition est **irréalisable** : on **ne sait pas prédire la date** d'un séisme. L'aléa ne peut pas être supprimé ni annoncé : il faut agir **en permanence** sur la **vulnérabilité**.\n4. Mesures attendues (trois, expliquées) :\n- appliquer strictement les **normes parasismiques** : des bâtiments qui tiennent pendant la secousse ;\n- **cartographier les zones sismiques** pour savoir où le risque est le plus fort et y adapter les constructions ;\n- un réseau de **sismographes** pour une surveillance continue ;\n- l'**éducation** aux bons réflexes et la préparation des **secours** ;\n- une **alerte tsunami**, indispensable pour des villes en bord de mer : un séisme sous-marin peut déplacer la colonne d'eau et provoquer un tsunami ; l'alerte permet d'évacuer les côtes.\nConclusion : le risque = aléa × vulnérabilité ; ne pouvant agir sur l'aléa, on réduit la vulnérabilité."}$exo$::jsonb),
  ('b8f98dd3-2843-5f84-82b9-88c2d7212717'::uuid, 1, 'application', $exo${"titre":"Effusif ou explosif ?","consigne":"Complète et réponds avec le vocabulaire du cours.","enonce":"**Situation.** Ilyès compare deux volcans pour un exposé.\n\n1. Nomme, dans l'ordre, les trois parties d'un volcan par lesquelles passe le magma, de la profondeur à la surface.\n2. Recopie et complète le tableau :\n\n| | Éruption effusive | Éruption explosive |\n|---|---|---|\n| Le magma | … | … |\n| Les gaz | … | … |\n| Ce qui sort | … | … |\n| Un exemple | … | … |\n\n3. Quel type d'éruption est le plus dangereux pour les habitants ? Pourquoi ?","bareme":[{"critere":"Réservoir, cheminée, cratère dans l'ordre","points":4},{"critere":"Tableau complet et juste (magma, gaz, produits, exemples)","points":10},{"critere":"Explosive plus dangereuse : nuées ardentes impossibles à fuir","points":6}],"dureeMin":7,"corrige":"1. Le magma s'accumule dans un **réservoir**, remonte par la **cheminée** et sort par le **cratère**.\n2. \n| | Effusive | Explosive |\n|---|---|---|\n| Le magma | **Fluide**, pauvre en silice | **Visqueux**, riche en silice |\n| Les gaz | S'échappent **facilement** | **Retenus** jusqu'à la rupture |\n| Ce qui sort | **Coulées de lave**, fontaines | **Cendres**, blocs, **nuées ardentes** |\n| Exemple | Piton de la Fournaise, Hawaï, Islande | Montagne Pelée, Vésuve, Merapi |\n3. L'éruption **explosive** est la plus dangereuse : ses **nuées ardentes** dévalent les pentes à plusieurs centaines de km/h, on **ne peut pas les fuir**, alors qu'une coulée de lave est lente et peut souvent être fuie."}$exo$::jsonb),
  ('b8f98dd3-2843-5f84-82b9-88c2d7212717'::uuid, 2, 'application', $exo${"titre":"La Réunion et la Martinique","consigne":"Exploite les deux documents et justifie chaque réponse.","enonce":"**Document 1 – Le Piton de la Fournaise (La Réunion)**\n\n> Il entre en éruption presque chaque année. La lave, très fluide, s'écoule en coulées sur ses flancs, parfois jusqu'à la mer. Les routes sont coupées, mais il y a très rarement des victimes. Il se situe loin de toute frontière de plaques.\n\n**Document 2 – La Montagne Pelée (Martinique), 8 mai 1902**\n\n> Après des semaines de grondements, une nuée ardente dévale le volcan et détruit en quelques minutes la ville de Saint-Pierre : environ 28 000 morts. Le volcan se situe dans une zone de subduction.\n\n1. Identifie le type d'éruption de chaque volcan en justifiant avec le document.\n2. Explique ce qui, dans le magma, détermine le type d'éruption.\n3. Relie chaque volcan à son contexte géologique.\n4. Explique pourquoi l'une des éruptions a fait tant de victimes et l'autre presque aucune.","bareme":[{"critere":"Fournaise effusive et Pelée explosive, justifiées par le document","points":5},{"critere":"Viscosité (silice) et teneur en gaz du magma expliquées","points":5},{"critere":"Fournaise : point chaud ; Pelée : zone de subduction","points":4},{"critere":"Différence de danger : coulée lente fuyable, nuée ardente rapide et mortelle","points":6}],"dureeMin":11,"corrige":"1. Le **Piton de la Fournaise** a des éruptions **effusives** : lave très fluide, coulées. La **Montagne Pelée** a eu une éruption **explosive** : nuée ardente.\n2. Le type d'éruption dépend de la **viscosité du magma** et de sa **teneur en gaz**. Un magma **fluide**, pauvre en silice, laisse les gaz s'échapper facilement : la lave s'écoule. Un magma **visqueux**, riche en silice, **retient les gaz** jusqu'à la rupture : l'éruption explose (cendres, blocs, nuées ardentes).\n3. La Fournaise est un volcan de **point chaud**, loin de toute frontière de plaques (comme Hawaï). La Montagne Pelée est dans une **zone de subduction**, où le volcanisme est **explosif** (comme la ceinture de feu du Pacifique).\n4. Les coulées de lave de la Fournaise sont **lentes** : elles détruisent routes et maisons, mais les habitants ont le temps de s'écarter. La **nuée ardente** de 1902, mélange brûlant de gaz et de particules, a dévalé la pente à **plusieurs centaines de km/h** : impossible de la fuir, la ville a été détruite en quelques minutes."}$exo$::jsonb),
  ('b8f98dd3-2843-5f84-82b9-88c2d7212717'::uuid, 3, 'application', $exo${"titre":"Faut-il évacuer ?","consigne":"Tu es au conseil scientifique d'un observatoire volcanologique. Analyse les données et argumente ta décision.","enonce":"**Situation.** Un volcan situé au-dessus d'une zone de subduction domine une vallée de 40 000 habitants. Il n'est pas entré en éruption depuis 300 ans.\n\n**Document – Relevés de l'observatoire**\n\n| Semaine | Petits séismes par jour | Gonflement du sommet (GPS) | Gaz émis au sommet | Température du sol au sommet |\n|---|---|---|---|---|\n| 1 | 3 | 0 cm | stables | 20 °C |\n| 2 | 15 | +2 cm | composition modifiée | 35 °C |\n| 3 | 80 | +9 cm | forte hausse du dioxyde de soufre | 70 °C |\n\n1. Pour chaque type de mesure, nomme l'instrument utilisé et dis ce que l'évolution suggère.\n2. Quel type d'éruption faut-il redouter ici ? Justifie avec le contexte géologique et le magma attendu.\n3. Cite trois dangers qui menacent la vallée et précise le plus mortel.\n4. Proposes-tu d'évacuer ? Argumente, en montrant pourquoi c'est possible pour un volcan alors que ce ne l'est pas pour un séisme, et appuie-toi sur un exemple historique.","bareme":[{"critere":"Quatre signes précurseurs reliés à leur instrument, évolution interprétée (remontée du magma)","points":6},{"critere":"Éruption explosive attendue : subduction, magma visqueux riche en gaz","points":4},{"critere":"Trois dangers corrects, nuées ardentes désignées comme les plus mortelles","points":4},{"critere":"Décision argumentée : signes précurseurs, niveaux d'alerte, exemple du Pinatubo 1991","points":6}],"dureeMin":18,"corrige":"1. Les **petits séismes** sont enregistrés par les **sismographes** : de 3 à 80 par jour, la roche se fracture sous la poussée du magma. Le **gonflement** est mesuré par **GPS et inclinomètres** : +9 cm, l'édifice gonfle car le réservoir se remplit. Les **gaz** sont suivis par des **analyseurs** : leur composition change, du magma frais dégaze près de la surface. La **température** est suivie par des **capteurs** et l'imagerie : elle monte de 20 à 70 °C. Tous les signes indiquent une **remontée de magma** : une éruption se prépare.\n2. Le volcan est dans une **zone de subduction** : on redoute une éruption **explosive**, avec un magma **visqueux**, riche en silice, qui **retient ses gaz** jusqu'à la rupture. Un long repos (300 ans) n'est pas rassurant.\n3. Dangers : **nuées ardentes**, retombées de **cendres** (toits effondrés, trafic aérien interrompu), **lahars** (coulées de boue), **gaz toxiques**, effondrement de l'édifice. Les plus mortelles sont les **nuées ardentes**, immédiates et impossibles à fuir.\n4. Oui, il faut **préparer puis déclencher l'évacuation**, en relevant le **niveau d'alerte**. Contrairement aux séismes, dont on ne sait pas prédire la date, une éruption est souvent **précédée de signes détectables**. L'observatoire surveille en continu, définit des niveaux d'alerte et prépare l'évacuation : c'est ce qui a sauvé **des dizaines de milliers de vies au Pinatubo, en 1991**. Mieux vaut évacuer à temps, même si l'éruption tarde, que d'exposer 40 000 personnes à une nuée ardente."}$exo$::jsonb),
  ('e846375f-64f9-5a0f-b33c-845aac278e36'::uuid, 1, 'application', $exo${"titre":"Le Soleil, moteur de l'atmosphère","consigne":"Réponds en phrases complètes avec le vocabulaire du cours.","enonce":"**Situation.** Nour se demande pourquoi il fait plus chaud à l'équateur qu'aux pôles, et d'où vient le vent.\n\n1. Explique pourquoi l'équateur reçoit plus d'énergie solaire que les pôles.\n2. Recopie et complète :\n   - L'air chaud est moins … : il … et crée une zone de … pression appelée … .\n   - L'air froid est plus … : il … et crée une zone de … pression appelée … .\n3. Dans quel sens souffle le vent ? Quelle force dévie sa trajectoire ?","bareme":[{"critere":"Angle des rayons : verticaux à l'équateur, inclinés et étalés aux pôles","points":6},{"critere":"Phrases complétées justes (dense, s'élève, basse, dépression ; dense, descend, haute, anticyclone)","points":8},{"critere":"Vent de la haute vers la basse pression, dévié par la force de Coriolis","points":6}],"dureeMin":6,"corrige":"1. À l'**équateur**, les rayons du Soleil arrivent **presque à la verticale** : l'énergie se concentre sur une petite surface (bilan excédentaire). Aux **pôles**, les rayons sont **très inclinés** : la même énergie s'étale sur une grande surface et traverse plus d'atmosphère (bilan déficitaire).\n2. L'air chaud est moins **dense** : il **s'élève** et crée une zone de **basse** pression appelée **dépression**.\nL'air froid est plus **dense** : il **descend** et crée une zone de **haute** pression appelée **anticyclone**.\n3. Le vent va de la **haute pression vers la basse pression**. La rotation de la Terre le dévie : c'est la **force de Coriolis**."}$exo$::jsonb),
  ('e846375f-64f9-5a0f-b33c-845aac278e36'::uuid, 2, 'application', $exo${"titre":"Une semaine froide, et alors ?","consigne":"Exploite le document et justifie chacune de tes réponses avec le cours.","enonce":"**Document – La situation météo d'un jour de janvier**\n\n> Au-dessus des Açores, un anticyclone : 1 035 hPa. Au sud de l'Islande, une dépression : 985 hPa. Entre les deux, sur l'Atlantique, souffle un vent d'ouest. Un front arrive sur la Bretagne avec des pluies.\n\n**Une affirmation.** Après une semaine très froide, Mathis déclare : « Cette semaine prouve que le climat ne se réchauffe pas. »\n\n1. Où l'air s'élève-t-il et où descend-il ? Justifie.\n2. Explique pourquoi un vent souffle entre les Açores et l'Islande.\n3. Qu'est-ce qu'un front, et pourquoi apporte-t-il de la pluie ? Relie ta réponse au cycle de l'eau.\n4. Réponds à Mathis en distinguant météo et climat.","bareme":[{"critere":"Air qui s'élève dans la dépression, qui descend dans l'anticyclone","points":4},{"critere":"Vent expliqué par la différence de pression (haute vers basse), dévié par Coriolis","points":5},{"critere":"Front : rencontre de masses d'air ; condensation en nuages puis précipitations","points":5},{"critere":"Météo (quelques jours) opposée au climat (moyennes sur au moins 30 ans)","points":6}],"dureeMin":11,"corrige":"1. L'air **s'élève** au sud de l'Islande, dans la **dépression** (basse pression, air chaud et léger qui monte). Il **descend** au-dessus des Açores, dans l'**anticyclone** (haute pression, air plus dense).\n2. L'air se déplace de la **haute pression** (Açores, 1 035 hPa) vers la **basse pression** (Islande, 985 hPa) : c'est le vent. La **force de Coriolis**, due à la rotation de la Terre, le dévie : on obtient ici un vent d'ouest.\n3. Un **front** est la **rencontre de deux masses d'air différentes**. L'air qui s'élève se refroidit, la vapeur d'eau se **condense en nuages**, puis retombe en **précipitations** : ce sont des étapes du cycle de l'eau (évaporation, condensation, précipitations).\n4. Mathis confond **météo** et **climat**. La météo décrit le temps sur **quelques jours** ; le climat décrit les **moyennes et la variabilité sur au moins trente ans**. Une semaine froide est un événement météo : elle ne dit rien de l'évolution du climat, qui se juge sur des décennies."}$exo$::jsonb),
  ('e846375f-64f9-5a0f-b33c-845aac278e36'::uuid, 3, 'application', $exo${"titre":"Brest et Saint-Jean de Terre-Neuve","consigne":"Analyse les documents et rédige une explication argumentée qui relie plusieurs notions du chapitre.","enonce":"**Document 1 – Deux villes à la même latitude**\n\n| Ville | Latitude | Température moyenne de janvier |\n|---|---|---|\n| Brest (France) | 48° N | environ 7 °C |\n| Saint-Jean de Terre-Neuve (Canada) | 48° N | environ −4 °C |\n\n**Document 2 – L'océan Atlantique Nord**\n\n> Le Gulf Stream, courant chaud, part du golfe du Mexique et traverse l'Atlantique vers l'Europe de l'Ouest. Au large de Terre-Neuve passe au contraire un courant froid venu de l'Arctique. Plus au nord, près du Groenland, l'eau de surface, froide et salée, plonge en profondeur.\n\n**Document 3 – Un bulletin**\n\n> « Nos modèles numériques prévoient le temps à Brest de façon fiable pour la semaine à venir. Nous ne publierons pas de prévision détaillée pour le mois prochain. »\n\n1. Les deux villes reçoivent-elles la même énergie solaire ? Justifie.\n2. Explique l'écart de température entre elles grâce au document 2, en précisant le moteur du Gulf Stream.\n3. Qu'est-ce que la circulation thermohaline ? Relie-la au document 2. En quoi les courants participent-ils à l'équilibre énergétique de la planète ?\n4. Explique le choix des prévisionnistes du document 3, et cite les sources de données de leurs modèles.","bareme":[{"critere":"Même latitude donc même angle des rayons et même énergie reçue","points":3},{"critere":"Écart expliqué par le Gulf Stream chaud (moteur : les vents) et le courant froid","points":5},{"critere":"Circulation thermohaline (température et salinité, en profondeur) et redistribution de la chaleur","points":6},{"critere":"Atmosphère chaotique, limite d'environ deux semaines, sources de données citées","points":6}],"dureeMin":18,"corrige":"1. Oui : à la **même latitude**, les rayons du Soleil arrivent avec le **même angle**, et les deux villes reçoivent la même énergie solaire. L'écart de 11 °C a donc une autre cause.\n2. Brest est baignée par les eaux du **Gulf Stream**, un **courant chaud de surface** venu du golfe du Mexique, **entraîné par les vents** : il apporte de la chaleur et **adoucit le climat de l'Europe de l'Ouest**. Saint-Jean est longée par un **courant froid** venu de l'Arctique : ses hivers sont bien plus rigoureux.\n3. La **circulation thermohaline** est une circulation **profonde**, due aux différences de **température** et de **salinité** : près du Groenland, l'eau froide et salée, plus dense, **plonge**, ce qui entretient un « tapis roulant » océanique de mille ans. Le Soleil chauffe inégalement la Terre (excédent à l'équateur, déficit aux pôles) : les courants océaniques, comme les vents, **redistribuent la chaleur** des basses vers les hautes latitudes.\n4. L'atmosphère est un système **chaotique** : de petites incertitudes grandissent, et **au-delà d'environ deux semaines** la prévision détaillée devient impossible. Une prévision à une semaine est fiable, pas à un mois. Les modèles numériques sont alimentés par les données des **satellites**, des **stations au sol**, des **ballons-sondes** et des **bouées**."}$exo$::jsonb),
  ('f71c298c-e57f-5655-9a07-0da534baede9'::uuid, 1, 'application', $exo${"titre":"L'effet de serre, naturel puis renforcé","consigne":"Réponds en phrases complètes, avec le vocabulaire du cours.","enonce":"**Situation.** Dans un débat en classe, Zoé affirme : « L'effet de serre, c'est forcément mauvais. »\n\n1. Explique le fonctionnement de l'effet de serre : que laissent passer les gaz à effet de serre, et que retiennent-ils ?\n2. Montre que Zoé se trompe en distinguant l'effet de serre naturel et l'effet de serre renforcé.\n3. Recopie et complète le tableau :\n\n| Le gaz | Une source liée aux activités humaines |\n|---|---|\n| Dioxyde de carbone | … |\n| Méthane | … |\n| Protoxyde d'azote | … |","bareme":[{"critere":"Rayonnement solaire transmis, infrarouge renvoyé par le sol en partie retenu","points":6},{"critere":"Effet naturel utile (habitabilité) opposé à l'effet renforcé qui déséquilibre le bilan","points":7},{"critere":"Une source juste pour chacun des trois gaz","points":7}],"dureeMin":7,"corrige":"1. Les gaz à effet de serre **laissent passer le rayonnement solaire**, qui chauffe le sol. Le sol renvoie de l'énergie sous forme d'**infrarouge** ; les gaz à effet de serre **en retiennent une partie**, ce qui réchauffe l'atmosphère.\n2. L'effet de serre **naturel** est indispensable : il **rend la Terre habitable** (environ +15 °C en moyenne au lieu de −18 °C). C'est l'effet de serre **renforcé** par les activités humaines qui pose problème : il **déséquilibre le bilan énergétique** de la planète et provoque le réchauffement.\n3. **Dioxyde de carbone** : combustibles fossiles, déforestation ou ciment. **Méthane** : élevage, rizières ou fuites de gaz. **Protoxyde d'azote** : engrais."}$exo$::jsonb),
  ('f71c298c-e57f-5655-9a07-0da534baede9'::uuid, 2, 'application', $exo${"titre":"Ce que racontent les bulles de glace","consigne":"Exploite le document, pose ton calcul, puis justifie avec le cours.","enonce":"**Document – La teneur de l'atmosphère en CO₂ (en ppm : parties par million)**\n\n| Période | Teneur en CO₂ | Comment on la connaît |\n|---|---|---|\n| Depuis 800 000 ans, avant 1850 | entre 180 et 300 ppm | ? |\n| 1850 | 280 ppm | mesures anciennes et glace |\n| 2023 | environ 420 ppm | mesures directes |\n\n1. Comment connaît-on la teneur en CO₂ de l'atmosphère il y a 800 000 ans ? Complète la case « ? ».\n2. Calcule l'augmentation de la teneur en CO₂ entre 1850 et 2023, en ppm puis en pourcentage.\n3. Compare la valeur actuelle aux valeurs des 800 000 dernières années. Quelle est la cause principale de cette augmentation ?\n4. De combien la température moyenne mondiale a-t-elle augmenté depuis l'ère industrielle ? Qu'est-ce qui rend ce réchauffement différent des variations naturelles passées ?","bareme":[{"critere":"Bulles d'air piégées dans les carottes de glace du Groenland et de l'Antarctique","points":4},{"critere":"Calcul juste : +140 ppm, soit une hausse de 50 %","points":5},{"critere":"Valeur actuelle jamais atteinte en 800 000 ans, émissions humaines de GES","points":5},{"critere":"Environ 1,1 à 1,2 °C ; vitesse sans équivalent et cause humaine","points":6}],"dureeMin":11,"corrige":"1. Grâce aux **carottes de glace** du **Groenland** et de l'**Antarctique** : la glace contient des **bulles d'air** vieilles jusqu'à **800 000 ans**, dont on mesure la teneur en CO₂.\n2. Augmentation : 420 − 280 = **140 ppm**. En pourcentage : 140 ÷ 280 × 100 = **50 %**.\n3. La teneur actuelle (420 ppm) **dépasse largement** toutes les valeurs des 800 000 dernières années (jamais plus de 300 ppm). Cette hausse est due aux **émissions de gaz à effet de serre d'origine humaine** depuis l'ère industrielle : combustion des combustibles fossiles, déforestation, ciment.\n4. La température moyenne mondiale a augmenté d'environ **1,1 à 1,2 °C**. Le climat a toujours varié (paramètres de Milankovitch, volcanisme), mais sur des milliers d'années. Aujourd'hui, la **vitesse** du réchauffement est **sans équivalent connu**, et sa **cause est humaine**."}$exo$::jsonb),
  ('f71c298c-e57f-5655-9a07-0da534baede9'::uuid, 3, 'application', $exo${"titre":"Une ville du littoral face au climat","consigne":"Analyse la situation et construis une réponse argumentée qui mobilise plusieurs parties du chapitre.","enonce":"**Situation.** Une ville du littoral atlantique prépare son plan climat. Le document de travail contient ces propositions :\n\n- A. Construire une digue plus haute le long du front de mer.\n- B. Isoler les bâtiments publics pour réduire le chauffage au fioul.\n- C. Créer un système d'alerte aux canicules pour les personnes âgées.\n- D. Remplacer les bus diesel par des bus électriques alimentés par de l'énergie décarbonée.\n- E. Replanter une forêt sur les terrains communaux.\n- F. Interdire de construire dans les zones inondables.\n\nUn habitant déclare : « Si on arrêtait toutes les émissions demain, le climat redeviendrait tout de suite comme avant. »\n\n1. Explique les deux mécanismes qui font monter le niveau des mers. Cite deux autres conséquences du réchauffement qui menacent cette ville.\n2. Classe les propositions A à F en mesures d'atténuation et mesures d'adaptation, en définissant ces deux mots.\n3. Réponds à l'habitant.\n4. Quel objectif fixe l'accord de Paris ? Montre que la ville a besoin des deux types de mesures.","bareme":[{"critere":"Dilatation de l'eau et fonte des glaciers et calottes ; deux autres conséquences pertinentes","points":5},{"critere":"Atténuation et adaptation définies, six propositions bien classées","points":7},{"critere":"Réchauffement déjà engagé par les émissions passées : le climat ne réagit pas instantanément","points":4},{"critere":"Accord de Paris (2015, nettement sous 2 °C) et complémentarité des deux types de mesures","points":4}],"dureeMin":18,"corrige":"1. Le niveau des mers monte par **dilatation de l'eau** qui se réchauffe et par **fonte des glaciers et des calottes** (la fonte de la banquise flottante, elle, ne fait presque pas monter la mer). Autres conséquences : **événements extrêmes** (canicules, sécheresses, pluies diluviennes, tempêtes et cyclones plus intenses), **acidification des océans** (dissolution du CO₂), déplacement des espèces, pertes de récoltes (deux attendues).\n2. L'**atténuation** consiste à **réduire les émissions** de gaz à effet de serre ; l'**adaptation** à **réduire la vulnérabilité** aux effets du changement.\nAtténuation : **B** (isolation), **D** (bus décarbonés), **E** (reforestation, qui stocke du carbone).\nAdaptation : **A** (digue), **C** (alerte canicule), **F** (urbanisme).\n3. L'habitant se trompe : le climat **ne réagit pas instantanément**. Une partie du réchauffement à venir est **déjà engagée** par les émissions passées ; même en arrêtant d'émettre, le réchauffement et la hausse des mers continueraient un moment.\n4. L'**accord de Paris** (2015) vise à contenir le réchauffement **nettement en dessous de 2 °C**. La ville a besoin des deux : l'**atténuation** limite l'ampleur du réchauffement futur, mais le réchauffement déjà engagé impose de **s'adapter** (digue, alerte, urbanisme) pour protéger dès maintenant les habitants."}$exo$::jsonb),
  ('82e1f2db-4624-5bb5-af30-d8f85e544293'::uuid, 1, 'application', $exo${"titre":"Abondante et pourtant rare","consigne":"Réponds en phrases complètes, avec le vocabulaire du cours.","enonce":"**Situation.** Lina s'étonne : « L'eau couvre 70 % de la Terre, alors pourquoi dit-on qu'elle est rare ? »\n\n1. Réponds à Lina en donnant la part d'eau salée, d'eau douce et d'eau douce accessible sur la planète.\n2. Où se trouve l'essentiel de l'eau douce ?\n3. Remets dans l'ordre les étapes du cycle de l'eau : précipitations, évaporation, infiltration et ruissellement, condensation.\n4. Qu'est-ce qu'une nappe phréatique ?","bareme":[{"critere":"97,5 % salée, 2,5 % douce, moins de 1 % douce accessible","points":7},{"critere":"Eau douce surtout immobilisée dans les glaces et les nappes profondes","points":3},{"critere":"Ordre du cycle juste : évaporation, condensation, précipitations, ruissellement et infiltration","points":6},{"critere":"Nappe phréatique : réserve souterraine alimentée par l'infiltration","points":4}],"dureeMin":6,"corrige":"1. L'eau est abondante, mais **97,5 %** est **salée**. Il ne reste que **2,5 %** d'eau douce, et l'eau douce **accessible** représente **moins de 1 %** du total : c'est pour cela qu'elle est rare.\n2. L'essentiel de l'eau douce est **immobilisé dans les glaces** et dans les **nappes profondes**.\n3. **Évaporation** (le Soleil vaporise l'eau des océans et des sols) → **condensation** (la vapeur forme des nuages) → **précipitations** (l'eau retombe) → **ruissellement** vers les rivières et **infiltration** dans le sol.\n4. Une **nappe phréatique** est une **réserve d'eau souterraine**, alimentée par l'**infiltration** de l'eau de pluie."}$exo$::jsonb),
  ('82e1f2db-4624-5bb5-af30-d8f85e544293'::uuid, 2, 'application', $exo${"titre":"L'eau d'une famille, visible et invisible","consigne":"Pose tes calculs et justifie chaque réponse avec le cours.","enonce":"**Situation.** La famille de Karim compte 4 personnes. Chacune utilise environ 150 litres d'eau par jour à la maison.\n\n**Document – L'eau virtuelle**\n\n> Il faut environ 15 000 litres d'eau pour produire 1 kg de bœuf et environ 2 700 litres pour fabriquer un tee-shirt en coton.\n\n1. Calcule la consommation d'eau domestique de la famille en une année (365 jours), en litres puis en m³ (1 m³ = 1 000 L).\n2. Qu'est-ce que l'eau virtuelle ? Calcule l'eau virtuelle d'un repas de 4 steaks de 150 g chacun, et d'un achat de 3 tee-shirts.\n3. Compare les résultats de la question 2 avec la consommation domestique d'une journée pour toute la famille. Que peut-on en conclure ?\n4. Quel secteur consomme le plus d'eau dans le monde ? Quelle technique permet de l'économiser ?","bareme":[{"critere":"Calcul juste : 219 000 L, soit 219 m³ par an","points":5},{"critere":"Eau virtuelle définie ; 9 000 L pour la viande et 8 100 L pour les tee-shirts","points":6},{"critere":"Comparaison avec 600 L par jour et conclusion sur le poids de l'eau virtuelle","points":4},{"critere":"Agriculture (environ 70 %) et irrigation au goutte-à-goutte","points":5}],"dureeMin":11,"corrige":"1. Par jour : 4 × 150 = **600 L**. Par an : 600 × 365 = **219 000 L**, soit 219 000 ÷ 1 000 = **219 m³**.\n2. L'**eau virtuelle** est l'eau qu'il a fallu pour **produire un bien**. Viande : 4 × 150 g = 600 g = 0,6 kg ; 0,6 × 15 000 = **9 000 L**. Tee-shirts : 3 × 2 700 = **8 100 L**.\n3. Un seul repas de bœuf représente 9 000 ÷ 600 = **15 jours** de consommation domestique de toute la famille ; trois tee-shirts, 8 100 ÷ 600 = 13,5 jours. L'eau que nous consommons **indirectement** par notre alimentation et nos achats dépasse de loin l'eau du robinet : réduire sa consommation, c'est aussi choisir ce qu'on mange et ce qu'on achète.\n4. L'**agriculture**, par l'irrigation, avec environ **70 %** des prélèvements mondiaux (industrie 20 %, domestique 10 %). L'irrigation au **goutte-à-goutte** permet d'économiser l'eau."}$exo$::jsonb),
  ('82e1f2db-4624-5bb5-af30-d8f85e544293'::uuid, 3, 'application', $exo${"titre":"Une nappe côtière en danger","consigne":"Analyse les documents, pose les calculs utiles et rédige des réponses argumentées.","enonce":"**Situation.** Une commune littorale tire toute son eau potable d'une nappe phréatique proche de la mer. Depuis dix ans, l'eau des forages devient légèrement salée.\n\n**Document 1 – Le bilan de la nappe**\n\n| | Volume par an |\n|---|---|\n| Recharge naturelle par l'infiltration | 12 millions de m³ |\n| Prélèvements : agriculture | 9 millions de m³ |\n| Prélèvements : eau potable, dont 25 % de fuites dans le réseau | 4 millions de m³ |\n| Prélèvements : campings et piscines en été | 2 millions de m³ |\n\n**Document 2 – L'usine de potabilisation (étapes dans le désordre)**\n\n> Filtration sur charbon actif · Dégrillage · Désinfection · Floculation-décantation · Filtration sur sable\n\n1. Calcule le bilan annuel de la nappe. Comment appelle-t-on cette situation ?\n2. Explique pourquoi l'eau des forages devient salée.\n3. Propose trois mesures pour rétablir l'équilibre, en chiffrant au moins l'une d'elles, et nomme le conflit que la commune doit arbitrer.\n4. Remets dans l'ordre les étapes de potabilisation et donne le rôle de chacune. Que devient l'eau après usage ?","bareme":[{"critere":"Bilan juste : 15 − 12 = déficit de 3 millions de m³ par an, surexploitation","points":4},{"critere":"Salinisation expliquée par le pompage littoral trop fort","points":3},{"critere":"Trois mesures pertinentes, une chiffrée (fuites : 1 million de m³), conflit d'usage","points":6},{"critere":"Ordre et rôle des cinq étapes justes ; station d'épuration après usage","points":7}],"dureeMin":19,"corrige":"1. Prélèvements : 9 + 4 + 2 = **15 millions de m³**. Bilan : 12 − 15 = **−3 millions de m³ par an**. On prélève plus vite que la recharge naturelle : c'est une **surexploitation** de la nappe.\n2. La nappe baisse ; près du littoral, l'eau de mer prend la place de l'eau douce pompée : c'est la **salinisation** des nappes côtières, due à un **pompage littoral** trop fort.\n3. Mesures possibles : **réparer les fuites** du réseau (25 % de 4 millions = **1 million de m³** économisés par an) ; passer l'agriculture au **goutte-à-goutte** ; **limiter le pompage littoral** et les usages de loisir en été ; **réduire les prélèvements** ; protéger les zones de captage. Il faut réduire les prélèvements d'au moins 3 millions de m³. La commune doit arbitrer un **conflit d'usage** entre agriculture, tourisme et particuliers.\n4. **Dégrillage** (retirer les gros débris) → **floculation-décantation** (agglomérer puis faire tomber les particules) → **filtration sur sable** (retenir les fines) → **filtration sur charbon actif** (retenir les molécules dissoutes) → **désinfection** au chlore ou à l'ozone. Après usage, les eaux usées sont traitées dans une **station d'épuration**, par voie mécanique puis biologique, avant d'être rendues au milieu."}$exo$::jsonb),
  ('df030cf8-5fb9-5bd7-a2ed-14a4a6ec9474'::uuid, 1, 'application', $exo${"titre":"Comment naît un gisement de pétrole","consigne":"Réponds avec le vocabulaire précis du cours.","enonce":"**Situation.** Élise prépare une fiche sur le pétrole.\n\n1. De quoi provient le pétrole ?\n2. Associe chaque roche à son rôle :\n   - a. roche mère ; b. roche réservoir ; c. roche couverture\n   - (1) imperméable, elle piège les hydrocarbures ; (2) riche en matière organique, c'est là que se forme le pétrole ; (3) poreuse, les hydrocarbures y migrent et s'y accumulent.\n3. Pourquoi dit-on que le pétrole est une énergie non renouvelable ?","bareme":[{"critere":"Transformation de matière organique marine sur des millions d'années, avec enfouissement","points":6},{"critere":"Les trois associations justes","points":8},{"critere":"Non renouvelable : formation en millions d'années, consommation en quelques décennies","points":6}],"dureeMin":6,"corrige":"1. Le pétrole provient de la **transformation**, sur des **millions d'années**, de **matière organique accumulée au fond des mers**, enfouie sous des sédiments où la **température** et la **pression** augmentent.\n2. a → (2) : la **roche mère**, riche en matière organique, déposée en milieu pauvre en oxygène.\nb → (3) : la **roche réservoir**, poreuse, où les hydrocarbures migrent.\nc → (1) : la **roche couverture**, imperméable, qui les **piège**. Sans piège, pas de gisement exploitable.\n3. Le pétrole met des **millions d'années** à se former, et l'humanité le consomme en **quelques décennies** : à l'échelle humaine, il ne se renouvelle pas. Les réserves sont **finies**."}$exo$::jsonb),
  ('df030cf8-5fb9-5bd7-a2ed-14a4a6ec9474'::uuid, 2, 'application', $exo${"titre":"Où forer ?","consigne":"Exploite la coupe géologique décrite et justifie chaque choix avec le cours.","enonce":"**Document – Coupe géologique d'une région (de haut en bas)**\n\n> Les couches sont bombées vers le haut, en forme de dôme.\n> - Couche 1 : sable et graviers, perméables, en surface.\n> - Couche 2 : sel, imperméable, épais de 300 m.\n> - Couche 3 : grès, roche poreuse. Au sommet du dôme, ses pores contiennent du gaz, puis du pétrole, puis de l'eau salée.\n> - Couche 4 : argile noire riche en matière organique, entre 3 000 et 3 500 m de profondeur.\n>\n> Les géologues ont repéré ce dôme en envoyant des ondes dans le sous-sol et en enregistrant leurs échos.\n\n1. Identifie la roche mère, la roche réservoir et la roche couverture. Justifie.\n2. Explique le trajet des hydrocarbures depuis leur formation jusqu'à leur accumulation.\n3. Où faut-il placer le forage ? Justifie.\n4. Nomme la méthode de prospection utilisée et le procédé qui séparera ensuite le pétrole brut en produits utilisables.","bareme":[{"critere":"Argile noire = roche mère, grès = réservoir, sel = couverture, chacune justifiée","points":6},{"critere":"Formation par enfouissement, migration vers le haut, piégeage sous le sel","points":5},{"critere":"Forage au sommet du dôme, jusqu'à la couche de grès sous le sel","points":4},{"critere":"Sismique réflexion et distillation fractionnée","points":5}],"dureeMin":11,"corrige":"1. **Roche mère** : l'**argile noire** (couche 4), riche en matière organique. **Roche réservoir** : le **grès** (couche 3), poreux, dont les pores contiennent les hydrocarbures. **Roche couverture** : le **sel** (couche 2), **imperméable**, qui les empêche de remonter.\n2. Avec l'**enfouissement** (3 000 m), la température et la pression augmentent : la matière organique de l'argile se transforme en hydrocarbures. Plus légers, ils **migrent vers le haut** à travers le grès poreux, puis s'accumulent **sous le sel**, au **sommet du dôme** où ils sont **piégés** (gaz en haut, pétrole, puis eau salée plus dense).\n3. Il faut forer **au sommet du dôme**, traverser le sel et atteindre le grès à l'endroit où il contient du **pétrole** : c'est là que le piège concentre les hydrocarbures.\n4. La prospection a utilisé la **sismique réflexion** (ondes envoyées dans le sous-sol et leurs échos). Le pétrole brut sera séparé par **raffinage**, grâce à la **distillation fractionnée**, selon les températures d'ébullition (gaz, essences, kérosène, gazole, fiouls, bitumes)."}$exo$::jsonb),
  ('df030cf8-5fb9-5bd7-a2ed-14a4a6ec9474'::uuid, 3, 'application', $exo${"titre":"Sortir du pétrole, c'est juste changer de voiture ?","consigne":"Rédige une réponse argumentée et organisée, en t'appuyant sur les documents et sur tout le chapitre.","enonce":"**Situation.** Au conseil de la vie collégienne, Hugo affirme : « Pour sortir du pétrole, il suffit que tout le monde roule en voiture électrique. »\n\n**Document 1 – Ce que contient la trousse d'Hugo**\n\n> Stylos en plastique, gomme synthétique, trousse en polyester, feutres aux encres issues de la pétrochimie.\n\n**Document 2 – Quelques faits**\n\n> Les réserves de pétrole sont concentrées dans quelques régions du monde. Les prix du baril varient fortement d'une année à l'autre. Des marées noires ont souillé des centaines de kilomètres de côtes.\n\n1. Montre, avec le document 1 et le cours, que le pétrole ne sert pas qu'aux carburants. Cite les trois grands débouchés.\n2. Présente les quatre grands problèmes posés par l'exploitation du pétrole, en t'appuyant sur le document 2.\n3. Réponds à Hugo : sa solution suffit-elle ? Propose une stratégie en citant au moins quatre alternatives et explique pourquoi il faut les combiner.","bareme":[{"critere":"Carburants, chauffage et pétrochimie, avec des produits pétrochimiques du document 1","points":5},{"critere":"Épuisement, climat (CO₂), pollutions, géopolitique, appuyés sur le document 2","points":6},{"critere":"Réponse à Hugo nuancée : insuffisante, car le pétrole sert aussi à la pétrochimie","points":4},{"critere":"Au moins quatre alternatives citées et nécessité de les combiner","points":5}],"dureeMin":17,"corrige":"1. La trousse d'Hugo contient de nombreux objets issus de la **pétrochimie** : plastiques, gomme synthétique, polyester, encres. Le pétrole a trois grands débouchés : les **carburants** (routier, aérien, maritime), le **chauffage** (fioul domestique) et la **pétrochimie** (plastiques, textiles synthétiques, engrais, médicaments, cosmétiques, peintures).\n2. **Épuisement** : les réserves sont **finies** et **inégalement réparties** (doc. 2). **Climat** : la combustion libère du **CO₂**, gaz à effet de serre. **Pollutions** : marées noires (doc. 2), dégazages, fuites, torchage, particules et oxydes d'azote. **Géopolitique** : dépendance des pays importateurs, **volatilité des prix** (doc. 2), conflits.\n3. La solution d'Hugo ne suffit pas : la voiture électrique réduit la consommation de **carburants**, mais pas celle du chauffage au fioul ni de la **pétrochimie** ; sortir du pétrole ne concerne donc pas que les voitures. Stratégie : développer les **énergies renouvelables** (solaire, éolien, hydraulique, biomasse, géothermie), le **nucléaire**, la **sobriété** et l'**efficacité énergétique**, le **recyclage des plastiques**, les **transports collectifs**. Aucune alternative ne remplace le pétrole à elle seule : c'est leur **combinaison** qui compte."}$exo$::jsonb),
  ('7368682b-0167-5612-8ba8-311a33f65605'::uuid, 1, 'application', $exo${"titre":"Le vivant face au réchauffement","consigne":"Réponds en phrases complètes, avec le vocabulaire du cours.","enonce":"**Situation.** Dans une réserve naturelle des Alpes, un garde observe que certaines plantes poussent désormais 200 m plus haut qu'il y a cinquante ans.\n\n1. Définis un écosystème.\n2. Comment appelle-t-on la zone où vit une espèce ? Dans quel sens se déplace-t-elle avec le réchauffement, dans l'hémisphère nord ?\n3. Cite les trois réponses possibles d'une espèce au changement climatique.\n4. Pourquoi les espèces de haute montagne sont-elles particulièrement menacées ?","bareme":[{"critere":"Écosystème : un milieu et ses êtres vivants avec leurs relations","points":5},{"critere":"Aire de répartition, déplacée vers le nord et vers l'altitude","points":5},{"critere":"Se déplacer, s'adapter, disparaître localement","points":6},{"critere":"Espèces de haute montagne : plus d'altitude où monter","points":4}],"dureeMin":6,"corrige":"1. Un **écosystème** est l'ensemble formé par un **milieu** et par les **êtres vivants qui l'occupent**, avec toutes leurs **relations**.\n2. C'est l'**aire de répartition**. Avec le réchauffement, elle se déplace **vers le nord** et, en montagne, **vers l'altitude** : c'est ce qu'observe le garde.\n3. Une espèce peut **se déplacer** (si un milieu favorable est accessible), **s'adapter** (par sélection naturelle, sur plusieurs générations) ou **disparaître localement** quand aucune des deux n'est possible.\n4. Les espèces de haute montagne vivent déjà au sommet : **elles n'ont plus où monter**. Quand leur milieu se réchauffe, elles ne peuvent pas fuir vers le froid."}$exo$::jsonb),
  ('7368682b-0167-5612-8ba8-311a33f65605'::uuid, 2, 'application', $exo${"titre":"Les mésanges et les chenilles","consigne":"Exploite le document et justifie chaque réponse avec le cours.","enonce":"**Document – Dans une forêt suivie depuis 40 ans**\n\n| | Il y a 40 ans | Aujourd'hui |\n|---|---|---|\n| Date du pic d'abondance des chenilles | 25 mai | 10 mai |\n| Date d'éclosion des œufs de mésange | 20 mai | 17 mai |\n| Nombre moyen de jeunes envolés par nid | 7 | 4 |\n\n> Les jeunes mésanges sont nourries presque uniquement de chenilles pendant leurs deux premières semaines.\n\n1. Décris l'évolution des dates de chaque espèce et calcule le décalage dans les deux cas.\n2. Comment s'appelle le changement des dates des événements du cycle de vie ? Et le décalage entre deux espèces dépendantes ?\n3. Explique la baisse du nombre de jeunes envolés.\n4. Quelles espèces s'en tirent mieux face à un changement aussi rapide ? La mésange en fait-elle partie ?","bareme":[{"critere":"Chenilles avancées de 15 jours, mésanges de 3 jours seulement","points":5},{"critere":"Phénologie et désynchronisation nommées","points":4},{"critere":"Baisse expliquée : éclosion après le pic, manque de nourriture des nichées","points":6},{"critere":"Espèces à génération courte et forte descendance ; vitesse du changement","points":5}],"dureeMin":11,"corrige":"1. Le pic des chenilles a **avancé de 15 jours** (du 25 au 10 mai). L'éclosion des mésanges n'a avancé que de **3 jours** (du 20 au 17 mai). Il y a 40 ans, les oisillons naissaient 5 jours **avant** le pic ; aujourd'hui, ils naissent 7 jours **après**.\n2. Le changement des dates du cycle de vie est un changement de **phénologie**. Le décalage entre deux espèces qui dépendent l'une de l'autre est une **désynchronisation**.\n3. Les jeunes mésanges ont besoin de beaucoup de chenilles dans leurs premières semaines. Comme elles éclosent **après** le pic, les chenilles sont déjà moins abondantes : les **nichées manquent de nourriture**, moins de jeunes survivent (7 → 4 par nid).\n4. Les espèces à **génération courte** et à **forte descendance** s'adaptent mieux (la sélection naturelle agit plus vite). La mésange, qui a peu de jeunes et une génération par an, en fait moins partie : le problème n'est pas seulement l'ampleur du réchauffement, c'est sa **vitesse**."}$exo$::jsonb),
  ('7368682b-0167-5612-8ba8-311a33f65605'::uuid, 3, 'application', $exo${"titre":"Récifs, permafrost et services rendus","consigne":"Analyse les documents et rédige une réponse argumentée qui relie plusieurs notions du chapitre.","enonce":"**Document 1 – Un récif corallien**\n\n> Lors d'un épisode de chaleur marine, l'eau a dépassé de 2 °C les valeurs habituelles pendant six semaines. Les coraux sont devenus blancs, puis beaucoup sont morts. Les poissons qui y vivaient ont disparu. Sur la côte voisine, les vagues de tempête atteignent désormais les maisons.\n\n**Document 2 – Le sol gelé de Sibérie**\n\n> Le permafrost contient d'énormes quantités de matière organique gelée. En dégelant, il libère du méthane.\n\n1. Explique le blanchissement des coraux et un autre effet du changement climatique sur les récifs.\n2. Montre, avec le document 1, comment la disparition d'une espèce peut en entraîner d'autres.\n3. Explique, avec le document 2, ce qu'est une rétroaction positive.\n4. Qu'appelle-t-on services écosystémiques ? Cite celui que rendait le récif d'après le document 1, et deux autres rendus par d'autres écosystèmes.\n5. Propose deux mesures pour aider les écosystèmes à faire face au climat.","bareme":[{"critere":"Blanchissement (expulsion des algues symbiotiques) et acidification qui fragilise les squelettes","points":5},{"critere":"Effet en chaîne expliqué : espèce clé de voûte, poissons disparus","points":3},{"critere":"Rétroaction positive : dégel, méthane, réchauffement renforcé","points":4},{"critere":"Services définis ; protection des côtes et deux autres services exacts","points":5},{"critere":"Deux mesures pertinentes : aires protégées, corridors, restauration, moins de pressions","points":3}],"dureeMin":19,"corrige":"1. Au-delà d'un **seuil de température**, les coraux **expulsent leurs algues symbiotiques** qui les nourrissent et leur donnent leur couleur : ils blanchissent, puis meurent si la chaleur dure. Autre effet : l'**acidification des océans** (dissolution du CO₂) **fragilise leurs squelettes calcaires**.\n2. Le corail est une espèce **clé de voûte** : il construit l'habitat de nombreuses espèces. Sa mort entraîne la **disparition des poissons** qui en dépendaient : les effets se propagent **en chaîne**.\n3. Le réchauffement fait **dégeler le permafrost**, qui libère du **méthane**, un gaz à effet de serre ; le méthane **renforce le réchauffement**, qui fait dégeler davantage de permafrost. C'est une **rétroaction positive** : un effet qui **amplifie sa propre cause**.\n4. Les **services écosystémiques** sont les **bénéfices que les écosystèmes apportent aux sociétés humaines**. Le récif **protégeait les côtes** des vagues (doc. 1), et nourrissait les pêcheurs. Autres : **pollinisation** des cultures, **épuration de l'eau** par les zones humides, **stockage de carbone** par les forêts et océans, **fertilité des sols**, ressources médicinales (deux attendus).\n5. Mesures : **aires protégées** ; **corridors écologiques** pour permettre les déplacements ; **restauration** des zones humides et des forêts ; **réduire les autres pressions** (pollution, surexploitation), ce qui laisse aux écosystèmes une chance de s'adapter."}$exo$::jsonb),
  ('af044f4f-758e-573f-adc4-5261889bd42f'::uuid, 1, 'application', $exo${"titre":"Les cinq grandes pressions","consigne":"Réponds en phrases complètes avec le vocabulaire du cours.","enonce":"**Situation.** Pour un exposé sur l'Anthropocène, Yanis doit présenter les pressions que l'humanité exerce sur la planète.\n\n1. Que désigne le mot Anthropocène ?\n2. Recopie et complète le tableau avec les cinq grandes pressions et un exemple pour chacune :\n\n| La pression | Un exemple |\n|---|---|\n| … | … |\n\n3. Quel est le taux d'extinction actuel comparé au taux naturel ? Quel nom donne-t-on à cette crise ?","bareme":[{"critere":"Anthropocène : époque marquée par l'action humaine sur la planète","points":4},{"critere":"Les cinq pressions nommées avec un exemple juste chacune","points":10},{"critere":"100 à 1 000 fois le taux naturel, sixième extinction de masse","points":6}],"dureeMin":7,"corrige":"1. L'**Anthropocène** désigne une époque où l'humanité modifie la planète à une échelle telle qu'elle en devient une force géologique : l'époque de l'**action humaine sur la planète**.\n2. \n| La pression | Un exemple |\n|---|---|\n| Le **changement climatique** | Émissions de gaz à effet de serre |\n| La **destruction des habitats** | Déforestation, urbanisation, drainage |\n| La **surexploitation** | Surpêche, coupes forestières |\n| Les **pollutions** | Plastiques, pesticides, nitrates, lumière, bruit |\n| Les **espèces invasives** | Transportées par le commerce mondial |\n\nCes pressions agissent **ensemble** et leurs effets se cumulent.\n3. Le taux d'extinction actuel est **100 à 1 000 fois** supérieur au taux naturel : on parle de **sixième extinction de masse**."}$exo$::jsonb),
  ('af044f4f-758e-573f-adc4-5261889bd42f'::uuid, 2, 'application', $exo${"titre":"Le jour du dépassement","consigne":"Exploite le document, pose tes calculs et justifie avec le cours.","enonce":"**Document – Le jour du dépassement mondial**\n\n| Année | Date du jour du dépassement |\n|---|---|\n| 1970 | 29 décembre |\n| 2000 | fin septembre |\n| 2024 | 1er août |\n\n1. Qu'est-ce que le jour du dépassement ? Décris son évolution.\n2. En 2024, pendant combien de jours l'humanité a-t-elle vécu « à crédit » ? (le 1er août est le 214e jour d'une année de 366 jours)\n3. Définis l'empreinte écologique et l'empreinte carbone.\n4. Propose trois actions, en précisant chacune à quel pilier du développement durable elle se rattache principalement et en citant au moins une action d'économie circulaire.","bareme":[{"critere":"Définition juste et évolution décrite (date de plus en plus précoce)","points":5},{"critere":"Calcul juste : 366 − 214 = 152 jours","points":4},{"critere":"Empreinte écologique et empreinte carbone définies","points":5},{"critere":"Trois actions pertinentes reliées aux piliers, dont une d'économie circulaire","points":6}],"dureeMin":11,"corrige":"1. Le **jour du dépassement** est la date à laquelle l'humanité a **consommé ce que la planète peut renouveler en un an**. Il tombe **chaque année plus tôt** : fin décembre en 1970, fin septembre en 2000, 1er août en 2024.\n2. 366 − 214 = **152 jours** : pendant environ 5 mois, l'humanité a puisé dans les réserves (surpêche, déforestation, CO₂ accumulé).\n3. L'**empreinte écologique** est la **surface nécessaire pour produire ce qu'on consomme et absorber ses déchets**. L'**empreinte carbone** mesure les **émissions** de gaz à effet de serre liées à un mode de vie.\n4. Exemples : **réparer, réutiliser, recycler** plutôt que jeter (**économie circulaire**, pilier environnemental et économique) ; développer les **transports collectifs** et les **énergies renouvelables** (environnemental) ; l'**agroécologie** qui rémunère les agriculteurs tout en préservant les sols (économique et environnemental) ; des logements isolés qui baissent les factures des ménages modestes (social). Le développement durable repose sur trois piliers : **économique**, **social**, **environnemental**."}$exo$::jsonb),
  ('af044f4f-758e-573f-adc4-5261889bd42f'::uuid, 3, 'application', $exo${"titre":"Un marais contre un centre commercial","consigne":"Analyse les documents et rédige un avis argumenté qui mobilise plusieurs notions du chapitre.","enonce":"**Situation.** Une commune veut drainer un marais de 40 hectares pour construire un centre commercial et son parking.\n\n**Document 1 – Le marais aujourd'hui**\n\n> Il abrite une libellule qu'on ne trouve nulle part ailleurs dans la région, des oiseaux migrateurs et des grenouilles. Il retient l'eau lors des crues et l'épure avant qu'elle rejoigne la nappe.\n\n**Document 2 – Le projet**\n\n> Il créerait 150 emplois. Les eaux de pluie du parking seraient rejetées dans la rivière. Des lampadaires éclaireraient le site toute la nuit.\n\n**Document 3 – Un succès passé**\n\n> En 1987, le protocole de Montréal a interdit les gaz qui détruisaient la couche d'ozone. Celle-ci se reconstitue aujourd'hui.\n\n1. Identifie, dans le projet, au moins trois des grandes pressions sur la biodiversité.\n2. Explique pourquoi la disparition de la libellule serait plus grave qu'une pollution de la rivière. À quels niveaux la biodiversité serait-elle touchée ?\n3. Analyse le projet selon les trois piliers du développement durable.\n4. Que montre le document 3 ? Propose une solution qui concilie les trois piliers.","bareme":[{"critere":"Trois pressions identifiées : destruction d'habitat, pollution de l'eau, pollution lumineuse","points":4},{"critere":"Perte irréversible d'une espèce ; niveaux écosystème, espèces et gènes","points":5},{"critere":"Analyse selon les piliers économique, social et environnemental","points":5},{"critere":"Montréal : les décisions collectives ont des effets mesurables ; solution conciliatrice","points":4},{"critere":"Argumentation organisée qui s'appuie sur les documents","points":2}],"dureeMin":19,"corrige":"1. Pressions : **destruction de l'habitat** (drainage, artificialisation du marais) ; **pollution** de l'eau (eaux du parking rejetées dans la rivière) ; **pollution lumineuse** (lampadaires toute la nuit) ; on peut ajouter la perte des services (crues, épuration). Ces pressions **se cumulent**.\n2. Une espèce disparue **ne revient pas** : la perte est **irréversible**, alors qu'une pollution peut être traitée (des rivières dépolluées ont retrouvé leurs poissons). La biodiversité serait touchée à trois niveaux : l'**écosystème** (le marais entier disparaît), les **espèces** (libellule, grenouilles, haltes des migrateurs) et les **gènes** (diversité qui conditionne la capacité future à s'adapter).\n3. **Économique** : 150 emplois, une activité viable. **Social** : des emplois, mais aussi un risque accru d'inondations pour les habitants et la perte d'un lieu de nature. **Environnemental** : le projet détruit le milieu, supprime l'épuration de l'eau et la rétention des crues. Le projet ne satisfait pas les trois piliers.\n4. Le protocole de Montréal montre que les **décisions collectives produisent des effets mesurables** : on peut inverser une dégradation. Solution : construire le centre sur un terrain déjà artificialisé (friche), **protéger le marais** en aire protégée, voire le **restaurer** et y créer un sentier pédagogique : on garde les emplois, les services rendus et la biodiversité."}$exo$::jsonb),
  ('67dde86d-d904-57e0-bd47-e4848cef0261'::uuid, 1, 'application', $exo${"titre":"Ce que réclame chaque cellule","consigne":"Réponds avec le vocabulaire du cours.","enonce":"**Situation.** Adam se demande pourquoi il faut manger et respirer, même quand on ne bouge pas.\n\n1. Cite quatre besoins fondamentaux de toute cellule et le rôle de deux d'entre eux.\n2. Écris le bilan de la respiration cellulaire.\n3. Range du plus simple au plus complexe : organe, organisme, cellule, appareil, tissu. Définis le tissu.","bareme":[{"critere":"Quatre besoins cités (dioxygène, glucose, acides aminés, eau…) et deux rôles justes","points":7},{"critere":"Bilan juste : glucose + dioxygène donne dioxyde de carbone + eau + énergie","points":6},{"critere":"Ordre juste et définition du tissu","points":7}],"dureeMin":6,"corrige":"1. Besoins : le **dioxygène** (pour la respiration cellulaire), le **glucose** (source d'énergie), les **acides aminés** (pour fabriquer les protéines), les **acides gras** (membranes, réserve d'énergie), l'**eau**, les **sels minéraux** et les **vitamines** (fonctionnement général). Quatre besoins et deux rôles attendus.\n2. **glucose + dioxygène → dioxyde de carbone + eau + énergie**.\nMême au repos, les cellules respirent en permanence : il faut donc toujours les approvisionner.\n3. **Cellule → tissu → organe → appareil → organisme**. Un **tissu** est un ensemble de **cellules de même type**."}$exo$::jsonb),
  ('67dde86d-d904-57e0-bd47-e4848cef0261'::uuid, 2, 'application', $exo${"titre":"Un muscle au repos et en course","consigne":"Exploite le document, pose tes calculs et justifie avec le cours.","enonce":"**Document – Mesures chez une élève de 3e**\n\n| | Au repos | Pendant une course |\n|---|---|---|\n| Dioxygène consommé par un muscle de la cuisse | 0,3 L par heure | 3,6 L par heure |\n| Glucose consommé par ce muscle | 1 g par heure | 11 g par heure |\n\n> Le cerveau représente environ 2 % de la masse du corps, mais consomme environ 20 % du glucose de l'organisme, jour et nuit.\n\n1. Par combien la consommation de dioxygène du muscle est-elle multipliée pendant la course ? Pourquoi ?\n2. Quels sont les appareils qui fournissent le dioxygène et le glucose au muscle ? Précise le rôle de chacun.\n3. Calcule combien de fois la part de glucose consommée par le cerveau est supérieure à sa part de la masse du corps. Pourquoi l'approvisionnement du cerveau ne doit-il jamais s'interrompre ?","bareme":[{"critere":"Calcul juste (× 12) et explication : plus de respiration cellulaire pour plus d'énergie","points":6},{"critere":"Appareils digestif, respiratoire et circulatoire avec leur rôle","points":8},{"critere":"Calcul juste (20 ÷ 2 = 10) et besoin continu du cerveau","points":6}],"dureeMin":10,"corrige":"1. 3,6 ÷ 0,3 = **12** : la consommation de dioxygène est multipliée par 12. Pendant l'effort, le muscle a besoin de beaucoup plus d'**énergie** ; il l'obtient par la **respiration cellulaire**, qui consomme **glucose et dioxygène** (le glucose est d'ailleurs multiplié par 11).\n2. L'appareil **digestif** fournit les **nutriments**, dont le glucose, en simplifiant les aliments. L'appareil **respiratoire** fournit le **dioxygène** et évacue le CO₂. L'appareil **circulatoire** **transporte** l'un et l'autre jusqu'à chaque cellule du muscle. Aucun ne se suffit à lui-même : c'est leur **coordination** qui maintient l'organisme en vie.\n3. 20 ÷ 2 = **10** : le cerveau consomme 10 fois plus de glucose que sa part de la masse. Ses besoins sont **constants**, de jour comme de nuit, et son approvisionnement **ne peut pas être interrompu** : ses cellules ont besoin en permanence de glucose et de dioxygène pour fonctionner."}$exo$::jsonb),
  ('67dde86d-d904-57e0-bd47-e4848cef0261'::uuid, 3, 'application', $exo${"titre":"Un court de tennis dans la poitrine","consigne":"Analyse les documents et rédige une explication argumentée qui relie plusieurs notions du chapitre.","enonce":"**Document 1 – Trois surfaces d'échange**\n\n| La surface d'échange | Son étendue | Son épaisseur |\n|---|---|---|\n| Les alvéoles pulmonaires | environ 100 m² | paroi très fine |\n| Les villosités intestinales | environ 200 m² | paroi très fine |\n| Les capillaires sanguins | des milliers de km de vaisseaux | paroi d'une seule cellule |\n\n> Un court de tennis mesure environ 260 m².\n\n**Document 2 – Le trajet d'une molécule**\n\n> Une molécule de glucose issue d'un morceau de pain arrive dans une cellule d'un muscle de la jambe, où elle est utilisée.\n\n1. Quelles caractéristiques communes présentent les surfaces d'échange du document 1 ? Explique en quoi elles facilitent les échanges.\n2. Calcule la surface totale des alvéoles et des villosités et compare-la au court de tennis. Quelle « solution » la nature répète-t-elle ?\n3. Décris le trajet de la molécule de glucose du document 2, de l'intestin jusqu'à la cellule musculaire, en nommant les appareils et la surface d'échange traversés.\n4. Que devient ce glucose dans la cellule musculaire ? Quels déchets produit-il et comment sont-ils évacués ?","bareme":[{"critere":"Surface étendue, paroi fine, forte vascularisation, reliées à l'efficacité des échanges","points":5},{"critere":"Calcul juste (300 m², plus qu'un court de tennis) ; maximiser la surface dans un petit volume","points":4},{"critere":"Trajet complet : intestin grêle, sang, capillaire, cellule, appareils nommés","points":6},{"critere":"Respiration cellulaire avec dioxygène ; CO₂ évacué par le sang et les poumons","points":5}],"dureeMin":18,"corrige":"1. Ces surfaces sont **très étendues**, séparées du sang par une **paroi très fine**, et **très vascularisées** (une circulation abondante de l'autre côté). Plus la surface est grande et la paroi fine, plus les échanges sont **rapides et nombreux**.\n2. 100 + 200 = **300 m²**, soit **plus qu'un court de tennis** (260 m²), logés dans le thorax et l'abdomen. La nature répète la même solution : **maximiser la surface dans un volume réduit**.\n3. Le pain est digéré par l'**appareil digestif** : l'amidon est simplifié en glucose. Au niveau des **villosités de l'intestin grêle**, le glucose traverse la paroi fine et passe dans le **sang**. L'**appareil circulatoire** le transporte jusqu'au muscle de la jambe. Là, il traverse la paroi des **capillaires** (une seule cellule d'épaisseur) et entre dans la cellule musculaire.\n4. Dans la cellule, le glucose est utilisé par la **respiration cellulaire** avec le **dioxygène** apporté par l'appareil respiratoire : glucose + dioxygène → dioxyde de carbone + eau + **énergie**, utilisée pour la contraction. Le **dioxyde de carbone** passe dans le sang, qui l'amène aux **poumons**, d'où il est rejeté dans l'air expiré. Les appareils digestif, respiratoire, circulatoire et excréteur travaillent ensemble."}$exo$::jsonb),
  ('21686aa4-644e-585c-b9c0-2ef925d2aeab'::uuid, 1, 'application', $exo${"titre":"Le trajet de l'air","consigne":"Réponds avec le vocabulaire du cours.","enonce":"**Situation.** En cours de natation, Jade apprend à contrôler sa respiration.\n\n1. Remets dans l'ordre les organes traversés par l'air : bronches, alvéoles pulmonaires, fosses nasales, trachée, bronchioles, larynx.\n2. Explique ce qui se passe lors de l'inspiration.\n3. Dans l'alvéole, dans quel sens passent le dioxygène et le dioxyde de carbone ? Comment s'appelle ce mode de passage ?","bareme":[{"critere":"Ordre juste des six organes","points":6},{"critere":"Inspiration : diaphragme qui s'abaisse, côtes qui se soulèvent, volume qui augmente","points":7},{"critere":"O₂ de l'air vers le sang, CO₂ du sang vers l'air, par diffusion","points":7}],"dureeMin":6,"corrige":"1. **Fosses nasales → larynx → trachée → bronches → bronchioles → alvéoles pulmonaires** (le pharynx se place entre les fosses nasales et le larynx).\n2. Lors de l'**inspiration**, le **diaphragme s'abaisse** et les **côtes se soulèvent** : le volume de la cage thoracique **augmente**, et l'air **entre** dans les poumons. À l'expiration, le mouvement s'inverse.\n3. Le **dioxygène** passe **de l'air alvéolaire vers le sang** ; le **dioxyde de carbone** passe **du sang vers l'air**. Les gaz traversent une paroi très fine par **diffusion**, du plus concentré vers le moins concentré."}$exo$::jsonb),
  ('21686aa4-644e-585c-b9c0-2ef925d2aeab'::uuid, 2, 'application', $exo${"titre":"L'air que l'on rejette","consigne":"Exploite le document et justifie chaque réponse avec le cours.","enonce":"**Document 1 – Composition de l'air (en % du volume)**\n\n| Gaz | Air inspiré | Air expiré |\n|---|---|---|\n| Dioxygène | 21 % | 16 % |\n| Dioxyde de carbone | 0,04 % | 4 % |\n| Diazote | 78 % | 78 % |\n\n**Document 2 – Un fait divers**\n\n> En hiver, une famille a été intoxiquée par un chauffage mal réglé qui dégageait du monoxyde de carbone. Les médecins ont constaté que leur sang transportait très mal le dioxygène.\n\n1. Décris l'évolution de chaque gaz entre l'air inspiré et l'air expiré.\n2. Explique ces différences en précisant où et comment se font les échanges.\n3. Comment le dioxygène est-il ensuite transporté dans le sang ?\n4. Explique le constat des médecins du document 2.","bareme":[{"critere":"Description chiffrée : O₂ diminue, CO₂ augmente, diazote inchangé","points":4},{"critere":"Échanges par diffusion dans les alvéoles, paroi fine, grande surface","points":6},{"critere":"Transport par l'hémoglobine des globules rouges","points":4},{"critere":"Le monoxyde de carbone prend la place du dioxygène sur l'hémoglobine","points":6}],"dureeMin":10,"corrige":"1. Le **dioxygène** diminue (21 % → 16 %), le **dioxyde de carbone** augmente fortement (0,04 % → 4 %, soit 100 fois plus), le **diazote** ne change pas (78 %).\n2. Les échanges ont lieu dans les **alvéoles pulmonaires** (environ 300 millions, 100 m²). Les gaz traversent leur **paroi très fine** par **diffusion**, du plus concentré vers le moins concentré : le dioxygène passe **de l'air vers le sang**, qui en est pauvre ; le dioxyde de carbone, produit par les cellules, passe **du sang vers l'air**. Le diazote n'est pas utilisé.\n3. Le dioxygène est **fixé par l'hémoglobine** des **globules rouges**.\n4. Le **monoxyde de carbone** **prend la place du dioxygène sur l'hémoglobine** : le sang ne peut plus transporter assez de dioxygène jusqu'aux cellules, d'où l'intoxication."}$exo$::jsonb),
  ('21686aa4-644e-585c-b9c0-2ef925d2aeab'::uuid, 3, 'application', $exo${"titre":"Du croissant au muscle","consigne":"Analyse la situation et construis une explication complète qui relie les deux appareils du chapitre.","enonce":"**Situation.** Au petit-déjeuner, Rayan mange un croissant riche en amidon et en graisses, puis court au collège.\n\n**Document – Un malade de l'intestin**\n\n> Après l'ablation d'une grande partie de son intestin grêle, un patient mange normalement, mais il maigrit et présente des carences en fer et en vitamines.\n\n1. Décris les deux types d'actions que subit le croissant dans l'appareil digestif, en donnant des exemples.\n2. Où se fait l'absorption ? Quelles structures lui donnent sa surface de 200 m² ?\n3. Le sang venu de l'intestin passe d'abord par un organe. Lequel, et quels sont ses trois rôles ?\n4. Compare les stratégies des appareils respiratoire et digestif pour faire entrer une substance dans le sang.\n5. Explique la situation du patient du document.","bareme":[{"critere":"Actions mécanique (mastication, brassage, péristaltisme) et chimique (enzymes)","points":4},{"critere":"Intestin grêle : replis, villosités et microvillosités","points":4},{"critere":"Foie : trier, stocker le glucose en glycogène, neutraliser des substances","points":4},{"critere":"Même stratégie : paroi fine, très grande surface, circulation abondante","points":4},{"critere":"Surface d'absorption réduite, donc carences","points":4}],"dureeMin":17,"corrige":"1. Action **mécanique** : **mastication** dans la bouche, **brassage** de l'estomac, **péristaltisme** qui fait avancer le bol. Action **chimique** : les **enzymes** de la salive, de l'estomac, du pancréas et de l'intestin coupent les grosses molécules (amidon, graisses) en **molécules simples** (glucose, acides gras).\n2. L'absorption se fait dans l'**intestin grêle**. Ses **replis**, ses **villosités** et ses **microvillosités** portent sa surface à environ **200 m²**, richement irriguée.\n3. Le sang passe d'abord par le **foie**, qui **trie** les nutriments, **stocke le glucose sous forme de glycogène** et **neutralise certaines substances**.\n4. Deux appareils, deux milieux (l'air, les aliments), mais **une même stratégie** : une **paroi fine**, une **très grande surface** (100 m² d'alvéoles, 200 m² de villosités) et une **circulation sanguine abondante** de l'autre côté. Le dioxygène passe dans le sang par diffusion à travers les alvéoles, les nutriments à travers les villosités.\n5. Sans une grande partie de l'intestin grêle, la **surface d'absorption diminue** : même si le patient mange normalement, les nutriments, le fer et les vitamines ne passent plus assez dans le sang. Il maigrit et présente des **carences**."}$exo$::jsonb),
  ('44352350-4004-564c-86ff-58abb222770d'::uuid, 1, 'application', $exo${"titre":"Une double pompe","consigne":"Réponds avec le vocabulaire du cours.","enonce":"**Situation.** En observant un cœur de porc en TP, Gabriel compte ses cavités.\n\n1. Combien de cavités compte le cœur ? Quel est le rôle des valves ?\n2. Recopie et complète :\n\n| La circulation | Elle part du… | Elle va vers… |\n|---|---|---|\n| Pulmonaire | … | … |\n| Générale | … | … |\n\n3. Associe chaque vaisseau à sa caractéristique : artère, veine, capillaire — (1) paroi d'une seule cellule, lieu des échanges ; (2) part du cœur, paroi épaisse et élastique ; (3) revient au cœur, paroi fine, souvent à valvules.","bareme":[{"critere":"Quatre cavités, valves qui imposent un sens unique au sang","points":5},{"critere":"Tableau juste : ventricule droit vers les poumons, ventricule gauche vers les organes","points":8},{"critere":"Les trois associations justes","points":7}],"dureeMin":7,"corrige":"1. Le cœur compte **quatre cavités** (deux oreillettes, deux ventricules), séparées par une cloison étanche. Les **valves** imposent un **sens unique** au sang.\n2. \n| Circulation | Départ | Destination |\n|---|---|---|\n| **Pulmonaire** (petite) | **Ventricule droit** | Les **poumons**, retour à l'oreillette gauche |\n| **Générale** (grande) | **Ventricule gauche**, le plus musclé | **Tous les organes**, retour à l'oreillette droite |\n3. **Artère** → (2) ; **veine** → (3) ; **capillaire** → (1). Les capillaires sont le lieu **exclusif** des échanges entre le sang et les cellules."}$exo$::jsonb),
  ('44352350-4004-564c-86ff-58abb222770d'::uuid, 2, 'application', $exo${"titre":"Le voyage d'un comprimé","consigne":"Réponds en décrivant précisément les trajets, avec le vocabulaire du cours.","enonce":"**Situation.** Chloé avale un comprimé contre le mal de tête. Le médicament passe dans le sang au niveau de l'intestin. Quelques minutes plus tard, il agit dans son cerveau… mais la notice précise qu'il se retrouve aussi dans tout l'organisme.\n\n1. Donne les constituants du sang et le rôle de chacun. Dans lequel le médicament est-il transporté ?\n2. Décris le trajet d'une molécule de dioxygène depuis une alvéole pulmonaire jusqu'à une cellule du cerveau, en nommant les cavités du cœur et les vaisseaux traversés.\n3. Explique pourquoi le médicament se retrouve dans tout l'organisme.\n4. Comment les déchets de l'organisme sont-ils éliminés ? Cite trois organes et ce qu'ils éliminent.","bareme":[{"critere":"Plasma, globules rouges, globules blancs, plaquettes et leurs rôles ; médicament dans le plasma","points":5},{"critere":"Trajet juste : oreillette gauche, ventricule gauche, artère, capillaire du cerveau","points":6},{"critere":"Toute substance absorbée passe par le sang, qui irrigue tout l'organisme","points":4},{"critere":"Trois organes justes : reins (urée), poumons (CO₂), foie, peau","points":5}],"dureeMin":12,"corrige":"1. Le **plasma** (55 %, surtout de l'eau) transporte nutriments, hormones et déchets ; les **globules rouges** transportent le dioxygène grâce à l'hémoglobine ; les **globules blancs** assurent la défense ; les **plaquettes** la coagulation. Le médicament est transporté **dissous dans le plasma**.\n2. Le dioxygène passe de l'alvéole dans un capillaire pulmonaire, puis rejoint le cœur par les veines pulmonaires jusqu'à l'**oreillette gauche**, passe dans le **ventricule gauche**, qui l'envoie dans la **circulation générale** par une **artère** (l'aorte), puis par les artères jusqu'au cerveau. Il sort du sang au niveau d'un **capillaire** du cerveau pour entrer dans la cellule.\n3. Toute substance absorbée **passe par le sang**, et le sang **irrigue l'organisme entier** : un médicament, une drogue ou un polluant atteint donc tous les organes, pas seulement celui qu'on veut soigner.\n4. Les **reins** éliminent l'**urée**, l'excès d'eau et de sels dans l'**urine** ; les **poumons** rejettent le **dioxyde de carbone** ; le **foie** transforme les déchets azotés et neutralise des toxiques ; la **peau** élimine un peu d'eau et de sels par la sueur."}$exo$::jsonb),
  ('44352350-4004-564c-86ff-58abb222770d'::uuid, 3, 'application', $exo${"titre":"Une chute sur le gravier","consigne":"Analyse la situation et rédige une explication argumentée qui relie plusieurs parties du chapitre.","enonce":"**Situation.** Tom tombe à vélo et s'écorche le genou sur du gravier. La plaie saigne un peu, puis le saignement s'arrête. Son ami Enzo s'inquiète : « Il y a des microbes partout sur ce gravier, tu vas forcément tomber malade ! »\n\n**Document – Quelques chiffres**\n\n> Notre intestin abrite des milliards de bactéries. La très grande majorité des micro-organismes qui nous entourent sont inoffensifs.\n\n1. Quel constituant du sang a permis d'arrêter le saignement ? Quel autre constituant intervient contre les microbes ?\n2. Quelle barrière naturelle a été franchie ici ? Cite trois autres barrières naturelles et leur action.\n3. Distingue contamination et infection, et dis ce qui s'est produit à coup sûr pour Tom.\n4. Réponds à Enzo en t'appuyant sur le document et sur le rôle du microbiote.","bareme":[{"critere":"Plaquettes (coagulation) et globules blancs (défense)","points":4},{"critere":"Peau franchie ; trois autres barrières et leur action","points":5},{"critere":"Contamination (entrée) et infection (multiplication) distinguées, appliquées à Tom","points":5},{"critere":"Réponse nuancée : minorité de pathogènes, microbiote utile","points":4},{"critere":"Argumentation claire qui utilise le vocabulaire du chapitre","points":2}],"dureeMin":16,"corrige":"1. Les **plaquettes** ont permis la **coagulation** et arrêté le saignement. Les **globules blancs** assurent la **défense** contre les micro-organismes.\n2. La **peau intacte**, frontière physique, a été franchie. Autres barrières : les **muqueuses** et le **mucus** qui piègent ; les **cils** des voies respiratoires qui évacuent ; l'**acidité de l'estomac** qui détruit ; le **microbiote** qui occupe la place (trois attendues).\n3. La **contamination** est l'**entrée** d'un micro-organisme dans l'organisme ; l'**infection** est sa **multiplication** dans l'organisme. Pour Tom, il y a eu **contamination** : des micro-organismes ont pu entrer par la plaie. Il n'y aura **infection** que s'ils se multiplient, ce qui n'est pas certain.\n4. Enzo exagère : la **plupart des micro-organismes sont inoffensifs**, seule une **minorité est pathogène**. Beaucoup sont même **utiles** : le **microbiote** intestinal, cutané et respiratoire aide à la digestion, fabrique des vitamines, éduque le système immunitaire et occupe la place des pathogènes. Tom n'est pas « forcément » malade ; il doit simplement nettoyer la plaie et la surveiller."}$exo$::jsonb),
  ('89b43e59-d3af-5dae-abfc-0aa845a6884b'::uuid, 1, 'application', $exo${"titre":"Fabriquer sa matière avec de la lumière","consigne":"Réponds avec le vocabulaire du cours.","enonce":"**Situation.** Sofia fait pousser des tomates sur son balcon. Elle se demande de quoi la plante se nourrit.\n\n1. Que signifie « autotrophe » ?\n2. Écris le bilan de la photosynthèse et indique dans quel organite elle se déroule.\n3. Recopie et complète :\n\n| L'organe | Ce qu'il prélève | Son dispositif |\n|---|---|---|\n| Les racines | … | … |\n| Les feuilles | … | … |","bareme":[{"critere":"Autotrophe : fabrique sa matière organique à partir de matière minérale et de lumière","points":5},{"critere":"Bilan de la photosynthèse juste et chloroplaste","points":8},{"critere":"Tableau juste : eau et sels minéraux par les poils absorbants, CO₂ par les stomates","points":7}],"dureeMin":6,"corrige":"1. Une plante **autotrophe** **fabrique sa propre matière organique** à partir de **matière minérale** et d'**énergie lumineuse**.\n2. **dioxyde de carbone + eau + énergie lumineuse → glucose + dioxygène**. Elle se déroule dans les **chloroplastes** des feuilles, où la **chlorophylle** capte l'énergie lumineuse.\n3. \n| Organe | Prélève | Dispositif |\n|---|---|---|\n| **Racines** | L'**eau** et les **sels minéraux** | Les **poils absorbants**, qui multiplient la surface |\n| **Feuilles** | Le **dioxyde de carbone** | Les **stomates**, qui règlent aussi les pertes d'eau |"}$exo$::jsonb),
  ('89b43e59-d3af-5dae-abfc-0aa845a6884b'::uuid, 2, 'application', $exo${"titre":"Deux plantes sous cloche","consigne":"Exploite l'expérience et justifie chaque réponse avec le cours.","enonce":"**Document – Une expérience**\n\n> On place deux plantes identiques sous deux cloches fermées. La cloche A est éclairée, la cloche B est placée dans l'obscurité. On mesure la teneur en dioxygène de l'air pendant 2 heures.\n\n| | Au départ | Après 2 heures |\n|---|---|---|\n| Cloche A (lumière) | 21 % | 23 % |\n| Cloche B (obscurité) | 21 % | 20 % |\n\n1. Décris les résultats de chaque cloche.\n2. Quel phénomène explique le résultat de la cloche A ? Écris son bilan.\n3. Quel phénomène explique le résultat de la cloche B ?\n4. Anaïs en conclut : « Les plantes respirent seulement la nuit. » Corrige-la en exploitant les deux cloches.","bareme":[{"critere":"Description : O₂ augmente à la lumière, diminue à l'obscurité","points":4},{"critere":"Photosynthèse identifiée à la lumière, avec son bilan juste","points":6},{"critere":"Respiration à l'obscurité : consommation de dioxygène","points":4},{"critere":"Correction : respiration jour et nuit, masquée le jour par la photosynthèse plus forte","points":6}],"dureeMin":10,"corrige":"1. Dans la cloche A (lumière), la teneur en dioxygène **augmente** de 21 % à 23 %. Dans la cloche B (obscurité), elle **diminue** de 21 % à 20 %.\n2. À la lumière, la plante réalise la **photosynthèse**, qui **rejette du dioxygène** : dioxyde de carbone + eau + énergie lumineuse → glucose + dioxygène.\n3. À l'obscurité, pas de photosynthèse : seule la **respiration** a lieu, qui **consomme du dioxygène**.\n4. Anaïs se trompe : la plante **respire jour et nuit**. Dans la cloche A, elle respire aussi, mais la **photosynthèse l'emporte largement** : elle produit plus de dioxygène que la respiration n'en consomme, et le bilan est positif. La cloche B montre la respiration seule, qui existe aussi le jour."}$exo$::jsonb),
  ('89b43e59-d3af-5dae-abfc-0aa845a6884b'::uuid, 3, 'application', $exo${"titre":"L'arbre dont on a retiré l'écorce","consigne":"Analyse les documents et construis une explication argumentée qui mobilise tout le chapitre.","enonce":"**Document 1 – Une observation dans un verger**\n\n> Un jardinier retire un anneau d'écorce de 5 cm tout autour du tronc d'un pommier. Sous l'écorce se trouve le phloème ; le bois, plus profond, contient le xylème. Dans les semaines suivantes, les feuilles restent vertes et fraîches, mais le tronc gonfle juste au-dessus de l'anneau. Au bout d'un ou deux ans, les racines meurent, puis l'arbre entier.\n\n**Document 2 – Une journée chaude**\n\n> Par forte chaleur, beaucoup de plantes ferment leurs stomates en milieu de journée.\n\n**Document 3 – Les racines du pommier**\n\n> Elles sont entourées de filaments de champignons, qui aident l'arbre à prélever eau et sels minéraux.\n\n1. Distingue la sève brute et la sève élaborée : contenu, vaisseau, sens et moteur.\n2. Explique chaque observation du document 1 (feuilles vertes, gonflement, mort des racines).\n3. Explique l'intérêt de la fermeture des stomates (doc. 2) et son inconvénient pour la photosynthèse.\n4. Comment s'appelle l'association du document 3 ? Montre qu'une plante fixée répond aux contraintes par des relations avec d'autres êtres vivants.","bareme":[{"critere":"Sèves brute et élaborée distinguées : contenu, xylème/phloème, sens, moteur","points":6},{"critere":"Observations expliquées : xylème intact, sucres bloqués au-dessus, racines privées de sucres","points":6},{"critere":"Stomates : moins de pertes d'eau, mais moins de CO₂ entrant","points":4},{"critere":"Mycorhize nommée et autres relations (nodosités, pollinisation)","points":4}],"dureeMin":18,"corrige":"1. La **sève brute** contient de l'**eau et des sels minéraux** ; elle circule dans le **xylème**, des **racines vers les feuilles**, grâce à la **transpiration** des stomates. La **sève élaborée**, **riche en sucres**, circule dans le **phloème**, des **feuilles vers tous les organes**, grâce à la pression osmotique.\n2. **Feuilles vertes** : le **xylème**, dans le bois, est intact ; la sève brute monte encore jusqu'aux feuilles. **Gonflement au-dessus de l'anneau** : le **phloème** est coupé ; la sève élaborée qui descend des feuilles est **bloquée** et les sucres s'accumulent. **Mort des racines** : elles ne reçoivent plus de **sucres** fabriqués par les feuilles et meurent de faim ; sans racines, l'arbre n'est plus approvisionné en eau et meurt.\n3. Fermer les stomates **limite les pertes d'eau** par transpiration quand il fait très chaud. Mais c'est aussi par les stomates qu'entre le **dioxyde de carbone** : fermés, ils **freinent la photosynthèse**.\n4. C'est une **mycorhize**, association entre les racines d'une plante et un champignon. Une plante ne peut pas fuir : elle répond aux contraintes par la **croissance orientée**, des défenses (épines, toxines), et par des **relations** : **mycorhizes**, **nodosités** à bactéries fixatrices d'azote, **pollinisation** par les insectes."}$exo$::jsonb),
  ('2a266763-10dd-519c-8992-78160571c31d'::uuid, 1, 'application', $exo${"titre":"Deux gamètes, une cellule œuf","consigne":"Réponds avec le vocabulaire du cours.","enonce":"**Situation.** Au bord d'une mare, Camille observe des œufs de grenouille par centaines, alors qu'une chatte n'a que quelques petits par portée.\n\n1. Définis la fécondation et la cellule œuf. Quelle information génétique contient la cellule œuf ?\n2. Recopie et complète :\n\n| | Fécondation externe | Fécondation interne |\n|---|---|---|\n| Où ? | … | … |\n| Nombre de gamètes ou de descendants | … | … |\n| Exemples | … | … |\n\n3. Un individu issu de reproduction sexuée est-il identique à l'un de ses parents ? Justifie.","bareme":[{"critere":"Fécondation et cellule œuf définies, moitié de l'information de chaque parent","points":6},{"critere":"Tableau juste (lieu, nombre, exemples)","points":8},{"critere":"Non : combinaison nouvelle due au brassage","points":6}],"dureeMin":7,"corrige":"1. La **fécondation** est la **fusion d'un gamète mâle et d'un gamète femelle**. Elle forme une **cellule œuf**, qui contient **la moitié de l'information génétique de chaque parent**. Elle se divise ensuite et se différencie : c'est le développement.\n2. \n| | Externe | Interne |\n|---|---|---|\n| Où ? | Dans l'**eau** | Dans les **voies femelles** |\n| Nombre | **Énormément** de gamètes, car la rencontre est peu probable | Descendance **moins nombreuse, mieux protégée** |\n| Exemples | Poissons, amphibiens (grenouille), oursins | Mammifères (chatte), oiseaux, reptiles, insectes |\n3. Non : l'individu n'est **identique à aucun de ses deux parents**. Le **brassage** crée à chaque fois une **combinaison nouvelle** de l'information des deux parents."}$exo$::jsonb),
  ('2a266763-10dd-519c-8992-78160571c31d'::uuid, 2, 'application', $exo${"titre":"Des millions d'œufs ou un seul petit","consigne":"Exploite le document et justifie avec le cours.","enonce":"**Document – Le nombre de descendants par an chez quatre espèces**\n\n| Espèce | Fécondation | Nombre d'œufs ou de petits par an | Soins aux jeunes |\n|---|---|---|---|\n| Morue | externe | plusieurs millions d'œufs | aucun |\n| Grenouille rousse | externe | 1 000 à 2 000 œufs | aucun |\n| Mésange | interne | 8 à 10 œufs | nourrit ses petits plusieurs semaines |\n| Éléphant d'Afrique | interne | 1 petit tous les 4 à 5 ans | allaite et protège son petit plusieurs années |\n\n1. Mets en relation le type de fécondation et le nombre de descendants. Explique cette relation.\n2. Nomme les deux stratégies de reproduction illustrées par le document et classe les quatre espèces.\n3. Explique pourquoi la morue et l'éléphant parviennent tous deux à maintenir leur population.\n4. La surpêche prélève surtout les grosses morues adultes. Pourquoi est-ce particulièrement dangereux pour la population ?","bareme":[{"critere":"Fécondation externe liée à un très grand nombre de gamètes, rencontre peu probable","points":5},{"critere":"Les deux stratégies nommées et les espèces classées","points":5},{"critere":"Maintien expliqué : miser sur le nombre ou miser sur la survie","points":5},{"critere":"Surpêche des reproducteurs : natalité qui chute, effectif qui baisse","points":5}],"dureeMin":11,"corrige":"1. Les espèces à **fécondation externe** (morue, grenouille) produisent **beaucoup plus** d'œufs que les espèces à fécondation interne. Dans l'eau, les chances de **rencontre** des gamètes sont faibles et les œufs sont exposés : il en faut énormément. La fécondation **interne** a un bien meilleur rendement : la descendance est moins nombreuse, mais mieux protégée.\n2. Stratégie « **beaucoup de descendants peu protégés** » (miser sur le nombre) : morue, grenouille rousse. Stratégie « **peu de descendants longuement pris en charge** » (miser sur la survie) : mésange, éléphant.\n3. La morue produit des millions d'œufs : même si presque tous meurent, quelques-uns atteignent l'âge adulte. L'éléphant a très peu de petits, mais les soins font que la plupart survivent. Les deux stratégies peuvent équilibrer natalité et mortalité.\n4. La surpêche retire les **adultes reproducteurs** : la **natalité** chute, et moins de jeunes remplacent ceux qui meurent. L'effectif de la population dépend de la natalité, de la mortalité, de l'immigration et de l'émigration : s'il y a moins de naissances et plus de morts, il **diminue**."}$exo$::jsonb),
  ('2a266763-10dd-519c-8992-78160571c31d'::uuid, 3, 'application', $exo${"titre":"Les tortues de la plage","consigne":"Analyse les documents, pose ton calcul et rédige des réponses argumentées.","enonce":"**Document 1 – Une population de tortues marines**\n\n> Au 1er janvier, 200 tortues adultes fréquentent une plage de ponte. Pendant l'année : 30 jeunes atteignent l'âge adulte et rejoignent la population, 45 adultes meurent (dont 20 pris accidentellement dans des filets), 5 tortues arrivent d'une autre plage et 10 partent définitivement.\n\n**Document 2 – Le sexe des bébés tortues**\n\n> Chez ces tortues, le sexe des petits dépend de la température du sable pendant l'incubation : au-dessus d'environ 29 °C, il naît surtout des femelles ; en dessous, surtout des mâles.\n\n**Document 3 – La plage**\n\n> Des hôtels ont été construits en haut de la plage et l'éclairent toute la nuit. Les bébés tortues, qui se guident vers la mer grâce à la lumière de l'horizon, partent vers l'intérieur des terres.\n\n1. Calcule l'effectif au 31 décembre, en nommant les quatre termes qui font varier une population.\n2. D'après le document 2, que risque-t-il de se passer si les plages se réchauffent ? Quelle conséquence pour la reproduction ?\n3. Identifie, dans les documents, deux activités humaines qui font chuter le succès reproducteur.\n4. Propose trois mesures de protection et explique ce que chacune apporte.","bareme":[{"critere":"Calcul juste (180) avec natalité, mortalité, immigration et émigration nommées","points":5},{"critere":"Réchauffement : surtout des femelles, manque de partenaires mâles","points":5},{"critere":"Deux activités identifiées : pollution lumineuse, prises accidentelles","points":4},{"critere":"Trois mesures pertinentes et justifiées","points":6}],"dureeMin":18,"corrige":"1. Effectif = 200 + **natalité** (30) − **mortalité** (45) + **immigration** (5) − **émigration** (10) = **180 tortues**. La population diminue de 20 individus.\n2. Si le sable dépasse 29 °C plus souvent, il naîtra **surtout des femelles**. Avec trop peu de **mâles**, la présence de **partenaires** devient un facteur limitant : moins de fécondations, donc une natalité qui baisse. La **température**, facteur du milieu, influence ici directement la reproduction.\n3. La **pollution lumineuse** des hôtels désoriente les nouveau-nés, qui meurent sans atteindre la mer ; les **prises accidentelles dans les filets** (20 adultes, soit près de la moitié des morts) retirent des reproducteurs. On peut aussi citer la **destruction des sites de ponte** par les constructions.\n4. Exemples : **éteindre ou orienter les éclairages** la nuit pendant la saison des éclosions (**calendrier de protection**) ; mettre la plage **en réserve** ou protéger les sites de ponte ; adapter les filets de pêche ou interdire la pêche près de la plage en saison de ponte ; **ombrager** certains nids pour limiter la température du sable. Chaque mesure réduit la mortalité ou augmente le succès reproducteur."}$exo$::jsonb),
  ('caa117e9-f719-59eb-8cd5-e0a811f78b11'::uuid, 1, 'application', $exo${"titre":"Des clones dans la nature","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Définis la **reproduction asexuée**. Pourquoi dit-on que les descendants sont des **clones** ?\n2. Associe chaque être vivant à sa forme de reproduction asexuée : **hydre**, **fraisier**, **étoile de mer**, **pomme de terre**, **puceron en été**.\n   - formes possibles : bourgeonnement, stolons, fragmentation et régénération, tubercules, parthénogenèse.\n3. Qu'est-ce que la **parthénogenèse** ?","bareme":[{"critere":"Définition juste : un seul parent, sans gamète ni fécondation, descendants génétiquement identiques","points":7},{"critere":"Les cinq associations correctes","points":8},{"critere":"Parthénogenèse : un ovule qui se développe sans être fécondé","points":5}],"dureeMin":7,"corrige":"1. La reproduction asexuée produit de nouveaux individus à partir d'**un seul parent**, **sans gamète ni fécondation**. Les descendants reçoivent exactement la même information génétique que leur parent : ils lui sont **génétiquement identiques**, ce sont des **clones**.\n\n2. Associations :\n- hydre → **bourgeonnement** ;\n- fraisier → **stolons** ;\n- étoile de mer → **fragmentation et régénération** ;\n- pomme de terre → **tubercules** ;\n- puceron en été → **parthénogenèse**.\n\n3. La parthénogenèse est le développement d'un **ovule sans fécondation** : un nouvel individu naît d'un ovule qui n'a pas rencontré de spermatozoïde (pucerons en été, certains lézards, mâles des abeilles)."}$exo$::jsonb),
  ('caa117e9-f719-59eb-8cd5-e0a811f78b11'::uuid, 2, 'application', $exo${"titre":"Le carré de fraisiers de Malik","consigne":"Lis la situation, puis réponds en justifiant tes calculs et tes explications.","enonce":"**Situation.** Malik plante **un seul** pied de fraisier dans son jardin. Chaque année, chaque pied produit **5 stolons**, et chaque stolon donne un nouveau pied qui s'enracine et produit à son tour 5 stolons l'année suivante. On suppose qu'aucun pied ne meurt.\n\n1. Quel mode de reproduction utilise ici le fraisier ? Est-il sexué ou asexué ?\n2. Calcule le nombre de pieds de fraisier au bout de **1 an**, puis de **2 ans**.\n3. Quel avantage de ce mode de reproduction ton calcul met-il en évidence ?\n4. Une maladie qui attaque ce fraisier arrive dans le jardin. Que risque-t-il de se passer pour tous les pieds ? Explique.","bareme":[{"critere":"Stolons identifiés comme reproduction asexuée","points":4},{"critere":"Calcul juste : 6 pieds au bout d'un an, 36 au bout de deux ans, avec démarche","points":6},{"critere":"Avantage : rapidité de colonisation sans partenaire","points":4},{"critere":"Inconvénient : tous clones, même sensibilité à la maladie, absence de diversité","points":6}],"dureeMin":10,"corrige":"1. Le fraisier se multiplie par **stolons** : c'est une **reproduction asexuée** (un seul parent, pas de fécondation).\n\n2. Au départ : 1 pied.\n- Au bout d'1 an : 1 pied + 5 nouveaux = **6 pieds**.\n- Au bout de 2 ans : chacun des 6 pieds produit 5 stolons, soit 6 × 5 = 30 nouveaux pieds ; total 6 + 30 = **36 pieds**.\n\n3. Le calcul montre la **rapidité** : sans chercher de partenaire, un seul pied peut **coloniser** tout un espace en très peu de temps.\n\n4. Tous les pieds sont des **clones** du premier : ils ont la même information génétique, donc **aucune diversité génétique**. Ils réagissent tous de la même façon à la maladie : si le premier pied y est sensible, **tous** le sont, et tout le carré peut être détruit d'un coup (comme la famine irlandaise de la pomme de terre au XIXe siècle)."}$exo$::jsonb),
  ('caa117e9-f719-59eb-8cd5-e0a811f78b11'::uuid, 3, 'application', $exo${"titre":"Le puceron, champion des deux stratégies","consigne":"Exploite le document et tes connaissances pour répondre. Justifie chaque réponse.","enonce":"**Document – La vie d'une colonie de pucerons sur un rosier**\n\n> Au printemps et en été, il n'y a que des **femelles**. Chacune donne naissance, sans aucun mâle, à plusieurs petites femelles par jour, qui se reproduisent de la même façon quelques jours plus tard. En quelques semaines, le rosier est couvert de milliers de pucerons.\n>\n> À l'automne, quand les jours raccourcissent et que la plante s'appauvrit, des **mâles** apparaissent. Les pucerons se reproduisent alors **sexuellement** et pondent des **œufs résistants**, qui passent l'hiver et éclosent au printemps.\n\n1. Nomme le mode de reproduction du printemps et de l'été. Justifie à partir du document.\n2. Quel est l'avantage de ce mode de reproduction pour le puceron quand les conditions sont bonnes ?\n3. Quel est son principal inconvénient ? Pourquoi est-il dangereux face à l'imprévu ?\n4. Explique pourquoi le passage à la reproduction sexuée à l'automne est utile pour l'avenir de l'espèce.\n5. Le cours conclut que c'est « un arbitrage entre la vitesse et l'avenir ». Explique cette phrase à partir de l'exemple du puceron.","bareme":[{"critere":"Parthénogenèse nommée et justifiée (femelles seules, pas de mâle, pas de fécondation)","points":4},{"critere":"Avantage : rapidité, occupation du rosier sans partenaire","points":3},{"critere":"Inconvénient : clones sans diversité, même réaction à une maladie ou un changement","points":4},{"critere":"Intérêt de la reproduction sexuée : diversité, œufs résistants pour passer l'hiver","points":5},{"critere":"Arbitrage vitesse / avenir expliqué avec les coûts de chaque reproduction","points":4}],"dureeMin":16,"corrige":"1. Au printemps et en été, c'est la **parthénogenèse** : il n'y a que des femelles, qui donnent des descendants **sans mâle**, donc sans fécondation. C'est une reproduction **asexuée**.\n\n2. Avantage : la **rapidité**. Pas besoin de chercher de partenaire, chaque femelle se reproduit : en quelques semaines, des milliers de pucerons **colonisent** le rosier tant que la nourriture est abondante.\n\n3. Inconvénient : les descendants sont des **clones**, sans **diversité génétique**. Face à un imprévu (maladie, prédateur, froid), ils réagissent **tous de la même façon** : si l'un est sensible, tous le sont. On note aussi la **compétition** entre individus identiques.\n\n4. La reproduction **sexuée** produit de la **diversité** : chaque œuf porte une combinaison nouvelle, et certains descendants pourront mieux résister aux conditions de l'année suivante. Elle fabrique aussi des **œufs résistants** qui passent l'hiver, alors que les femelles de l'été ne survivraient pas.\n\n5. La reproduction asexuée coûte **peu** et va **vite** : elle sert à **occuper le terrain** quand tout va bien. La reproduction sexuée coûte **cher** (partenaire, temps, énergie) mais fabrique de la **diversité**, donc prépare **l'avenir** et l'imprévu. Le puceron utilise l'une puis l'autre selon la saison : la vitesse l'été, l'avenir à l'automne."}$exo$::jsonb),
  ('d033635e-c4fd-53df-a141-cdd215086783'::uuid, 1, 'application', $exo${"titre":"Chromosomes et divisions","consigne":"Réponds à chaque question par une phrase complète.","enonce":"**Questions de cours.**\n\n1. Combien de chromosomes contient une cellule du corps humain ? Combien de paires ? D'où vient chaque chromosome d'une paire ?\n2. Quelle paire détermine le sexe ? Donne la formule d'une femme et celle d'un homme.\n3. Recopie et complète le tableau :\n\n| La division | Ce qu'elle produit | Nombre de chromosomes |\n|---|---|---|\n| Mitose | … | 46 → … |\n| Méiose | … | 46 → … |","bareme":[{"critere":"46 chromosomes, 23 paires, un chromosome du père et un de la mère","points":6},{"critere":"23e paire, XX pour la femme, XY pour l'homme","points":5},{"critere":"Tableau complet : mitose deux cellules identiques 46, méiose gamètes 23","points":9}],"dureeMin":6,"corrige":"1. Une cellule humaine contient **46 chromosomes**, soit **23 paires**. Dans chaque paire, un chromosome vient du **père**, l'autre de la **mère**.\n\n2. C'est la **23e paire** : **XX** chez la femme, **XY** chez l'homme.\n\n3. Tableau :\n\n| La division | Ce qu'elle produit | Nombre de chromosomes |\n|---|---|---|\n| Mitose | **Deux cellules identiques** (croissance, réparation) | 46 → **46** |\n| Méiose | Les **gamètes** (un chromosome de chaque paire) | 46 → **23** |"}$exo$::jsonb),
  ('d033635e-c4fd-53df-a141-cdd215086783'::uuid, 2, 'application', $exo${"titre":"Lire un caryotype","consigne":"Lis la description du document et réponds en justifiant.","enonce":"**Document – Le caryotype d'un bébé**\n\n> Le médecin a fait réaliser le **caryotype** d'un nouveau-né. On compte **47 chromosomes**. Les paires 1 à 20 et la paire 22 sont normales. On observe **trois chromosomes n° 21**. La dernière paire est formée d'un chromosome **X** et d'un chromosome **Y**.\n\n1. Qu'est-ce qu'un caryotype ?\n2. Ce bébé est-il une fille ou un garçon ? Justifie.\n3. Quelle anomalie présente-t-il ? Nomme-la.\n4. Explique comment cette anomalie a pu apparaître au moment de la formation des gamètes d'un des parents.","bareme":[{"critere":"Caryotype défini : photographie ordonnée des chromosomes","points":3},{"critere":"Garçon, justifié par la paire XY","points":4},{"critere":"Trisomie 21 nommée, trois chromosomes 21 et 47 au total","points":5},{"critere":"Mauvaise répartition à la méiose : gamète à 24 chromosomes, dont deux 21, fécondé par un gamète normal","points":8}],"dureeMin":10,"corrige":"1. Un caryotype est une **photographie ordonnée des chromosomes** d'une cellule, rangés par paires.\n\n2. C'est un **garçon** : sa 23e paire est formée d'un chromosome **X** et d'un chromosome **Y** (XY).\n\n3. Il présente **trois exemplaires du chromosome 21** au lieu de deux : c'est la **trisomie 21**. Il a donc 47 chromosomes au lieu de 46.\n\n4. Normalement, la **méiose** répartit un seul chromosome de chaque paire dans chaque gamète, qui en contient **23**. Ici, lors de la méiose chez l'un des parents, les deux chromosomes 21 ont été **mal répartis** et sont partis dans le même gamète : ce gamète avait **24 chromosomes**, dont **deux 21**. À la fécondation, il a rencontré un gamète normal à 23 chromosomes (un seul 21) : la cellule œuf a obtenu 24 + 23 = **47 chromosomes**, dont **trois 21**."}$exo$::jsonb),
  ('d033635e-c4fd-53df-a141-cdd215086783'::uuid, 3, 'application', $exo${"titre":"Frères et sœurs : pareils et différents","consigne":"Réponds en construisant un raisonnement appuyé sur les notions du cours.","enonce":"**Situation.** Dans la famille de Yanis, le père est un grand sportif très musclé, qui a beaucoup bronzé cet été. Yanis a une sœur, Léna, et deux petits frères, Adam et Noé, qui sont de **vrais jumeaux**.\n\n1. Imagine qu'il n'existe pas de méiose : les gamètes contiendraient 46 chromosomes. Calcule le nombre de chromosomes de la cellule œuf, puis celui de la génération suivante. Conclus sur le rôle de la méiose et de la fécondation.\n2. Yanis et Léna ont les mêmes parents mais ne sont pas identiques. Explique les deux mécanismes responsables.\n3. Adam et Noé ont-ils la même information génétique ? Justifie.\n4. Yanis espère avoir hérité des muscles et du bronzage de son père. A-t-il raison ? Justifie.","bareme":[{"critere":"Calcul 92 puis 184, et conclusion : méiose divise, fécondation rétablit, nombre constant","points":6},{"critere":"Brassage : répartition au hasard à la méiose et fécondation aléatoire","points":6},{"critere":"Vrais jumeaux issus d'une même cellule œuf, même information génétique","points":3},{"critere":"Caractères acquis non transmis : ils ne modifient pas les gamètes","points":5}],"dureeMin":15,"corrige":"1. Sans méiose, chaque gamète aurait 46 chromosomes : la cellule œuf en aurait 46 + 46 = **92**, et la génération suivante 92 + 92 = **184**. Le nombre doublerait à chaque génération. La **méiose** réduit le nombre de 46 à **23** dans les gamètes, et la **fécondation** le rétablit à **46** : le nombre de chromosomes reste **constant** d'une génération à l'autre.\n\n2. Deux mécanismes créent le **brassage** :\n- lors de la **méiose**, les chromosomes de chaque paire sont répartis **au hasard** dans les gamètes : plus de **8 millions** de combinaisons par parent ;\n- la **fécondation** réunit un spermatozoïde et un ovule **tirés au hasard** parmi des millions.\nYanis et Léna ont donc reçu des combinaisons de chromosomes différentes : ils se ressemblent sans être identiques.\n\n3. Oui. Les vrais jumeaux sont issus d'**une même cellule œuf** qui s'est séparée : ils ont la **même information génétique**.\n\n4. Non. La musculature et le bronzage sont des **caractères acquis** : ils résultent de l'entraînement et du soleil, et ne modifient pas l'information génétique des **cellules reproductrices**. Seule une modification des gamètes est transmise ; ces caractères ne le sont pas."}$exo$::jsonb),
  ('cafdc8e2-62f4-54b5-80b1-29080e47b0b0'::uuid, 1, 'application', $exo${"titre":"Homologie ou convergence ?","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Sur quoi repose la classification actuelle des êtres vivants ?\n2. Définis une **homologie** et une **convergence**.\n3. Classe chaque couple : aile d'oiseau et aile d'insecte ; bras humain et aile de chauve-souris ; patte avant du chat et nageoire de la baleine.\n4. Dans un arbre phylogénétique, que représente un **nœud** ?","bareme":[{"critere":"Classification fondée sur les liens de parenté et les caractères partagés","points":4},{"critere":"Définitions justes de l'homologie (héritée d'un ancêtre commun) et de la convergence (même mode de vie)","points":6},{"critere":"Les trois couples correctement classés","points":6},{"critere":"Nœud : ancêtre commun hypothétique","points":4}],"dureeMin":7,"corrige":"1. Elle repose sur les **liens de parenté** : on regroupe les êtres vivants selon les **caractères qu'ils partagent**.\n\n2. Une **homologie** est une ressemblance de plan d'organisation **héritée d'un ancêtre commun**. Une **convergence** est une ressemblance due à un **mode de vie commun**, sans parenté proche.\n\n3. Aile d'oiseau / aile d'insecte : **convergence**. Bras humain / aile de chauve-souris : **homologie**. Patte avant du chat / nageoire de la baleine : **homologie** (même plan : un os, puis deux, puis les doigts).\n\n4. Un nœud représente un **ancêtre commun hypothétique** des lignées qui en partent."}$exo$::jsonb),
  ('cafdc8e2-62f4-54b5-80b1-29080e47b0b0'::uuid, 2, 'application', $exo${"titre":"Qui est le plus proche parent de l'humain ?","consigne":"Exploite le tableau et réponds en justifiant avec les caractères partagés.","enonce":"**Document – Quelques caractères de cinq animaux** (+ = présent, − = absent)\n\n| Caractère | Truite | Grenouille | Lézard | Chat | Humain |\n|---|---|---|---|---|---|\n| Colonne vertébrale | + | + | + | + | + |\n| Quatre membres | − | + | + | + | + |\n| Poils | − | − | − | + | + |\n| Mamelles | − | − | − | + | + |\n\n1. Quel caractère est partagé par tous ? À quel groupe appartiennent-ils tous ?\n2. Quel animal du tableau est le plus proche parent de l'humain ? Justifie.\n3. La truite est-elle plus proche du lézard ou de l'humain ? Justifie.\n4. Complète la phrase avec les groupes emboîtés : « L'humain est un primate, qui est un …, qui est un …, qui est un eucaryote. »","bareme":[{"critere":"Colonne vertébrale : tous des vertébrés","points":4},{"critere":"Le chat, car il partage le plus de caractères avec l'humain (poils, mamelles)","points":6},{"critere":"La truite est à égale distance : elle ne partage que la colonne vertébrale avec les deux","points":5},{"critere":"Groupes emboîtés : mammifère, vertébré","points":5}],"dureeMin":10,"corrige":"1. Tous possèdent une **colonne vertébrale** : ce sont tous des **vertébrés**.\n\n2. Le **chat** : il partage avec l'humain **tous** les caractères du tableau (colonne vertébrale, quatre membres, poils, mamelles). Plus deux espèces partagent de caractères, plus leur **ancêtre commun est récent** : le chat et l'humain ont un ancêtre commun plus récent que celui qu'ils partagent avec les autres.\n\n3. La truite ne partage qu'**un seul** caractère avec le lézard (la colonne vertébrale) et ce même seul caractère avec l'humain. Elle n'est donc **pas plus proche** de l'un que de l'autre : lézard et humain ont entre eux un ancêtre commun plus récent (quatre membres) que celui qu'ils partagent avec la truite.\n\n4. « L'humain est un primate, qui est un **mammifère**, qui est un **vertébré**, qui est un eucaryote. »"}$exo$::jsonb),
  ('cafdc8e2-62f4-54b5-80b1-29080e47b0b0'::uuid, 3, 'application', $exo${"titre":"Un seul arbre pour tout le vivant","consigne":"Exploite les documents et construis des réponses argumentées.","enonce":"**Document 1 – Quelques dates de l'histoire de la vie**\n\n| Événement | Date |\n|---|---|\n| Apparition de la vie, unicellulaire | environ 3,8 milliards d'années |\n| Explosion du Cambrien | − 540 millions d'années |\n| Sortie des eaux | − 400 millions d'années |\n| Fin des dinosaures non aviens | − 66 millions d'années |\n| Apparition d'*Homo sapiens* | environ 300 000 ans |\n\n**Document 2** : tous les êtres vivants, de la bactérie à l'humain, utilisent l'**ADN** et le **même code génétique**.\n\n1. Cite trois indices, autres que les fossiles, qui permettent d'établir la parenté des êtres vivants.\n2. Quel argument le document 2 apporte-t-il ? Que suggère-t-il sur l'origine de tous les êtres vivants ?\n3. Calcule combien de temps s'est écoulé entre la disparition des dinosaures non aviens et l'apparition d'*Homo sapiens*. Les humains ont-ils côtoyé ces dinosaures ?\n4. Explique comment une extinction de masse peut être un « moteur de renouvellement », avec l'exemple des mammifères.","bareme":[{"critere":"Trois indices : caractères partagés, homologies, similitudes moléculaires ou développement embryonnaire","points":4},{"critere":"Argument moléculaire : ADN et code communs, donc ancêtre commun à tout le vivant","points":5},{"critere":"Calcul juste (environ 65,7 millions d'années) et conclusion : non","points":4},{"critere":"Extinction : milieux libérés, diversification des survivants, essor des mammifères","points":5},{"critere":"Rédaction claire et vocabulaire précis","points":2}],"dureeMin":16,"corrige":"1. Trois indices parmi : les **caractères partagés** (dérivés) ; les **homologies** (même plan d'organisation, ex. membre antérieur du chat, de la baleine, de la chauve-souris et de l'humain) ; les **similitudes moléculaires** ; les ressemblances du **développement embryonnaire**.\n\n2. C'est un argument **moléculaire** : tous les êtres vivants partagent l'**ADN** et le **même code génétique**. Un point commun aussi précis s'explique par un **héritage** : tous descendent d'**ancêtres communs**, et finalement d'une forme de vie unique apparue il y a environ 3,8 milliards d'années.\n\n3. 66 000 000 − 300 000 = **65 700 000 ans**, soit environ **65,7 millions d'années**. Les humains **n'ont jamais côtoyé** les dinosaures non aviens : ceux-ci avaient disparu des dizaines de millions d'années avant.\n\n4. Cinq grandes **extinctions de masse** ont éliminé une grande part des espèces. Les milieux et ressources occupés par les espèces disparues sont **libérés** : les **survivants** s'y **diversifient** et donnent de nombreuses espèces nouvelles. Ainsi, la disparition des dinosaures non aviens il y a 66 millions d'années a permis l'**essor des mammifères**, jusque-là discrets. L'extinction détruit, mais elle ouvre la voie à un renouvellement du vivant."}$exo$::jsonb),
  ('b86ecc5b-6bb0-5b81-8822-262da7f030d1'::uuid, 1, 'application', $exo${"titre":"Le raisonnement de Darwin","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Qui a décrit le mécanisme de la **sélection naturelle**, et en quelle année ?\n2. Donne dans l'ordre les **quatre étapes** du raisonnement de la sélection naturelle.\n3. D'où viennent les **variations héréditaires** entre individus ? Cite les deux sources.\n4. Complète : « Le hasard …, le milieu … ».","bareme":[{"critere":"Darwin, 1859","points":3},{"critere":"Les quatre étapes dans l'ordre","points":9},{"critere":"Mutations aléatoires et brassage de la reproduction sexuée","points":5},{"critere":"Le hasard fournit, le milieu choisit","points":3}],"dureeMin":7,"corrige":"1. **Charles Darwin**, en **1859**.\n\n2. Les quatre étapes :\n- les individus présentent des **variations héréditaires** ;\n- ils produisent **plus de descendants** que le milieu ne peut en nourrir : il y a **compétition** ;\n- les mieux **adaptés** survivent et se reproduisent davantage ;\n- leurs caractères deviennent plus **fréquents**, génération après génération.\n\n3. Des **mutations** de l'ADN, **aléatoires** (spontanées ou provoquées), et du **brassage** de la reproduction sexuée, qui redistribue les caractères à chaque génération.\n\n4. « Le hasard **fournit**, le milieu **choisit**. » La sélection ne crée rien : elle **trie**."}$exo$::jsonb),
  ('b86ecc5b-6bb0-5b81-8822-262da7f030d1'::uuid, 2, 'application', $exo${"titre":"La phalène du bouleau","consigne":"Exploite le document et explique avec le vocabulaire de la sélection naturelle.","enonce":"**Document – La phalène du bouleau près d'une ville industrielle anglaise**\n\n> La phalène est un papillon de nuit qui se repose le jour sur les troncs des arbres, où les oiseaux la chassent. Il en existe une forme **claire** et une forme **sombre**, et cette couleur est héréditaire.\n\n| Période | Troncs des arbres | Part de la forme sombre |\n|---|---|---|\n| Vers 1850 | clairs, couverts de lichens | environ 2 % |\n| Vers 1900 | noircis par la suie des usines | environ 95 % |\n| Vers 2000, air redevenu propre | à nouveau clairs | redevenue faible |\n\n1. Décris l'évolution de la part de la forme sombre entre 1850 et 1900.\n2. Explique cette évolution en utilisant les étapes de la sélection naturelle.\n3. Pourquoi la forme claire est-elle revenue après 1950 ?\n4. Un élève écrit : « La pollution a fait muter les papillons pour qu'ils deviennent sombres. » Corrige cette phrase.","bareme":[{"critere":"Description chiffrée : de 2 % à environ 95 %","points":3},{"critere":"Explication : variation préexistante, prédation par les oiseaux, meilleure survie et reproduction des sombres sur troncs noirs","points":8},{"critere":"Retour de la forme claire : le milieu change, l'avantage s'inverse","points":4},{"critere":"Correction : la mutation existait avant, elle est aléatoire, le milieu trie","points":5}],"dureeMin":11,"corrige":"1. La forme sombre passe d'environ **2 %** de la population vers 1850 à environ **95 %** vers 1900 : elle devient majoritaire en une cinquantaine d'années.\n\n2. Il existait **déjà** des phalènes claires et sombres (variation **héréditaire**). Les oiseaux mangent les papillons qu'ils voient. Sur des troncs **noircis par la suie**, les sombres sont **camouflées** et les claires très visibles : les sombres **survivent** davantage et **se reproduisent** plus. Elles transmettent leur couleur : génération après génération, la forme sombre devient **plus fréquente**. C'est la **sélection naturelle**.\n\n3. L'air redevenu propre, les troncs sont **à nouveau clairs** : ce sont maintenant les **claires** qui sont camouflées et les sombres qui sont repérées. L'avantage s'**inverse**, et la forme claire redevient fréquente. Une variation n'est ni bonne ni mauvaise en soi : c'est le **milieu** qui décide de sa valeur.\n\n4. Correction : « La mutation donnant la couleur sombre **existait déjà**, apparue **au hasard**. La pollution ne l'a pas créée : elle a **favorisé** les papillons sombres, qui ont survécu et se sont davantage reproduits. » L'évolution n'a pas de but, les papillons ne se transforment pas pour s'adapter."}$exo$::jsonb),
  ('b86ecc5b-6bb0-5b81-8822-262da7f030d1'::uuid, 3, 'application', $exo${"titre":"Des bactéries qui résistent","consigne":"Exploite la situation et tes connaissances pour construire des réponses argumentées.","enonce":"**Situation.** Dans une culture, on compte **10 millions** de bactéries. Parmi elles, **10** portent par hasard une mutation qui les rend résistantes à un antibiotique. On ajoute l'antibiotique : toutes les bactéries non résistantes meurent. Les bactéries survivantes se divisent en deux toutes les **30 minutes**.\n\n1. Quelle proportion de la population initiale est résistante ? Exprime-la en fraction simplifiée.\n2. Combien de bactéries résistantes y a-t-il **3 heures** après le traitement, si aucune ne meurt ? Détaille le calcul.\n3. Explique ce qui s'est passé avec le vocabulaire de la sélection naturelle.\n4. Un camarade affirme : « L'antibiotique a appris aux bactéries à résister. » Explique son erreur.\n5. Cite deux autres mécanismes de l'évolution vus en cours et ce qui les distingue de la sélection naturelle.","bareme":[{"critere":"Proportion juste : 1 sur 1 000 000","points":3},{"critere":"Calcul juste : 6 divisions, 10 × 64 = 640 bactéries résistantes","points":4},{"critere":"Sélection naturelle : variation préexistante, tri par le milieu, multiplication des résistantes","points":6},{"critere":"Erreur corrigée : la mutation est aléatoire et antérieure, l'antibiotique ne la crée pas","points":4},{"critere":"Dérive génétique et sélection sexuelle décrites","points":3}],"dureeMin":18,"corrige":"1. 10 / 10 000 000 = **1 / 1 000 000** : une bactérie sur un million est résistante.\n\n2. En 3 heures, il y a 3 × 60 / 30 = **6 divisions**. Chaque division double le nombre : 10 × 2⁶ = 10 × 64 = **640 bactéries** résistantes.\n\n3. Dans la population, il existait des **variations héréditaires** : une petite part de bactéries portait déjà, **par hasard**, une **mutation** de résistance. L'antibiotique est un changement du **milieu** qui **trie** : les non résistantes meurent, les résistantes **survivent** et **se multiplient**. En quelques heures, toute la population est formée de bactéries résistantes : le caractère est devenu **fréquent**. C'est la **sélection naturelle**, observée en quelques jours seulement.\n\n4. L'antibiotique n'a rien « appris » et n'a **pas créé** la mutation : elle existait **avant**, apparue au **hasard**. L'antibiotique a seulement **éliminé** les autres. La sélection ne crée rien, elle trie ; et l'évolution n'a pas de but.\n\n5. La **dérive génétique** : les fréquences des caractères changent par **pur hasard**, surtout dans les **petites populations**, sans lien avec un avantage. La **sélection sexuelle** : elle favorise les caractères qui améliorent l'**accès aux partenaires**, même s'ils sont coûteux pour la survie (la queue du paon)."}$exo$::jsonb),
  ('7d1d7305-fc67-50d5-8cd9-e7d6edfd2d71'::uuid, 1, 'application', $exo${"titre":"Où est écrite l'information ?","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Classe en caractères **d'espèce** ou **individuels** : avoir cinq doigts, la couleur des yeux, le groupe sanguin, avoir une colonne vertébrale.\n2. Dans quelle partie de la cellule se trouve l'information génétique ?\n3. Qu'est-ce qu'un **gène** ?\n4. Décris la **structure de l'ADN** et indique quelles bases s'apparient entre elles.","bareme":[{"critere":"Les quatre caractères correctement classés","points":5},{"critere":"Information génétique dans le noyau","points":3},{"critere":"Gène : segment d'ADN portant l'information d'un caractère (d'une protéine)","points":5},{"critere":"Double hélice de deux brins complémentaires, A avec T et G avec C","points":7}],"dureeMin":7,"corrige":"1. Caractères **d'espèce** : avoir cinq doigts, avoir une colonne vertébrale. Caractères **individuels** : la couleur des yeux, le groupe sanguin.\n\n2. L'information génétique se trouve dans le **noyau** de chaque cellule.\n\n3. Un gène est un **segment d'ADN** qui porte l'information d'un caractère, plus exactement l'information de fabrication d'une **protéine**.\n\n4. L'ADN est une **double hélice** formée de **deux brins complémentaires**. Ses quatre bases sont A, T, G et C ; elles s'apparient **A avec T** et **G avec C**. L'ordre des bases constitue le message génétique."}$exo$::jsonb),
  ('7d1d7305-fc67-50d5-8cd9-e7d6edfd2d71'::uuid, 2, 'application', $exo${"titre":"L'expérience du têtard albinos","consigne":"Analyse l'expérience et réponds en justifiant.","enonce":"**Document – Une expérience de transfert de noyau chez la grenouille**\n\n> On prélève un **ovule** chez une grenouille à peau **pigmentée** (sombre) et on détruit son noyau. On prélève ensuite le **noyau** d'une cellule d'intestin d'un têtard **albinos** (sans pigment) et on l'injecte dans l'ovule sans noyau. L'ovule se développe : on obtient un têtard **albinos**.\n\n1. Quel est le rôle de la destruction du noyau de l'ovule dans cette expérience ?\n2. Le têtard obtenu ressemble-t-il à la grenouille qui a fourni l'ovule ou au têtard qui a fourni le noyau ?\n3. Quelle conclusion peux-tu tirer sur la localisation de l'information génétique ?\n4. Quelle expérience célèbre de 1996 a montré le même principe chez un mammifère ?","bareme":[{"critere":"Rôle : éliminer l'information de la grenouille pigmentée, ne garder que le cytoplasme","points":5},{"critere":"Le têtard ressemble au donneur du noyau (albinos)","points":4},{"critere":"Conclusion : c'est le noyau qui impose les caractères, l'information est dans le noyau","points":7},{"critere":"Clonage de la brebis Dolly","points":4}],"dureeMin":10,"corrige":"1. En détruisant le noyau de l'ovule, on **supprime l'information** venant de la grenouille pigmentée : il ne reste que son **cytoplasme**. On pourra ainsi savoir si c'est le noyau ou le reste de la cellule qui décide des caractères.\n\n2. Le têtard est **albinos** : il ressemble au têtard qui a fourni le **noyau**, et non à la grenouille qui a fourni l'ovule.\n\n3. C'est le **noyau** qui impose les caractères : l'information génétique se trouve **dans le noyau** de la cellule. De plus, un noyau de cellule d'intestin suffit à fabriquer un têtard entier : chaque cellule contient **toute** l'information de l'individu.\n\n4. Le clonage de la **brebis Dolly**, en **1996** : le même principe (transfert de noyau) appliqué à un mammifère."}$exo$::jsonb),
  ('7d1d7305-fc67-50d5-8cd9-e7d6edfd2d71'::uuid, 3, 'application', $exo${"titre":"Même ADN, individus différents","consigne":"Réponds à chaque question en construisant une explication précise.","enonce":"**Situation.** Sarah et Maëlle sont de **vraies jumelles**. Sarah a passé son adolescence à faire de la natation en compétition ; Maëlle a vécu plusieurs années dans un pays où elle mangeait moins bien. Adultes, Sarah mesure 3 cm de plus que Maëlle.\n\n**Document** : un fragment d'un brin d'ADN de Sarah porte la séquence : **A T G C C G T A**.\n\n1. Écris la séquence du brin complémentaire. Justifie.\n2. Ce même fragment se trouve-t-il dans les cellules de la peau **et** dans les cellules du foie de Sarah ? Pourquoi ces cellules sont-elles pourtant différentes ?\n3. Maëlle possède-t-elle le même fragment ? Justifie.\n4. Explique pourquoi les deux sœurs n'ont pas la même taille. Quelles sont les deux origines de la diversité des individus ?","bareme":[{"critere":"Brin complémentaire juste : T A C G G C A T, avec la règle A-T, G-C","points":5},{"critere":"Même ADN dans toutes les cellules, gènes exprimés différents selon le tissu","points":5},{"critere":"Oui, les vraies jumelles partagent le même ADN (même cellule œuf)","points":4},{"critere":"Origine génétique et environnementale ; taille liée à la nutrition pendant la croissance","points":6}],"dureeMin":15,"corrige":"1. Les bases s'apparient **A avec T** et **G avec C**. Le brin complémentaire de A T G C C G T A est : **T A C G G C A T**.\n\n2. Oui : le **même ADN** est présent dans **toutes** les cellules d'un individu. Ce qui change d'un tissu à l'autre, ce sont les **gènes qui s'y expriment** : une cellule de peau et une cellule de foie n'utilisent pas les mêmes gènes, donc ne fabriquent pas les mêmes protéines.\n\n3. Oui. Les vraies jumelles sont issues de la **même cellule œuf** : elles ont le **même ADN**, donc le même fragment.\n\n4. La diversité a **deux origines** :\n- **génétique** : chaque individu reçoit une combinaison unique de versions de gènes (ici identique pour les jumelles) ;\n- **environnementale** : alimentation, activité physique, soleil, apprentissages modulent l'expression des gènes.\nLes deux sœurs ont les mêmes gènes, mais la taille adulte dépend **aussi de la nutrition** pendant la croissance : Maëlle, moins bien nourrie, a grandi un peu moins. Même des vrais jumeaux ne sont jamais exactement semblables."}$exo$::jsonb),
  ('3c9a5e5b-d862-5583-8985-d4d0073e39af'::uuid, 1, 'application', $exo${"titre":"Le vocabulaire des allèles","consigne":"Réponds à chaque question par une phrase complète.","enonce":"**Questions de cours.**\n\n1. Qu'est-ce qu'un **allèle** ? Combien d'allèles de chaque gène un individu porte-t-il, et d'où viennent-ils ?\n2. Définis **homozygote** et **hétérozygote**.\n3. Quelle différence y a-t-il entre un allèle **dominant** et un allèle **récessif** ?\n4. Définis **génotype** et **phénotype**.","bareme":[{"critere":"Allèle : version d'un gène ; deux allèles, un du père et un de la mère","points":5},{"critere":"Homozygote : deux allèles identiques ; hétérozygote : différents","points":5},{"critere":"Dominant : s'exprime dès qu'il est présent ; récessif : seulement en double","points":5},{"critere":"Génotype : ensemble des allèles ; phénotype : caractères observables","points":5}],"dureeMin":6,"corrige":"1. Un allèle est une **version d'un gène**. Chaque individu porte **deux allèles** de chaque gène : **un du père**, **un de la mère**.\n\n2. **Homozygote** : les deux allèles d'un gène sont **identiques**. **Hétérozygote** : ils sont **différents**.\n\n3. Un allèle **dominant** s'exprime **dès qu'il est présent** (une seule fois suffit). Un allèle **récessif** ne s'exprime que s'il est présent **en double** exemplaire.\n\n4. Le **génotype** est l'ensemble des **allèles** portés par un individu ; le **phénotype** est l'ensemble de ses **caractères observables**."}$exo$::jsonb),
  ('3c9a5e5b-d862-5583-8985-d4d0073e39af'::uuid, 2, 'application', $exo${"titre":"Les groupes sanguins de la famille Martin","consigne":"Utilise les données du cours rappelées ci-dessous et justifie chaque réponse.","enonce":"**Rappel.** Les allèles A et B sont **dominants** sur O, et **codominants** entre eux ; O est **récessif**.\n\n**Situation.** M. Martin est de groupe **A** et de génotype **A//O**. Mme Martin est de groupe **B** et de génotype **B//O**.\n\n1. M. Martin est-il homozygote ou hétérozygote ? Justifie.\n2. Quels allèles chacun des parents peut-il transmettre à un enfant ?\n3. Construis un tableau de croisement et donne tous les génotypes possibles des enfants, avec le groupe sanguin correspondant.\n4. Leur fille Jade est de groupe **O**. Est-ce possible alors qu'aucun des parents n'est de groupe O ? Explique.","bareme":[{"critere":"Hétérozygote car deux allèles différents","points":3},{"critere":"Allèles transmissibles : A ou O pour le père, B ou O pour la mère","points":4},{"critere":"Tableau juste : A//B (AB), A//O (A), B//O (B), O//O (O)","points":8},{"critere":"Explication pour Jade : un O reçu de chaque parent, récessif exprimé en double","points":5}],"dureeMin":11,"corrige":"1. M. Martin est **hétérozygote** : il porte deux allèles **différents** (A et O).\n\n2. Chaque parent transmet **un seul** de ses deux allèles : le père transmet **A ou O**, la mère **B ou O**.\n\n3. Tableau de croisement :\n\n| | A (père) | O (père) |\n|---|---|---|\n| **B (mère)** | A//B → groupe **AB** | B//O → groupe **B** |\n| **O (mère)** | A//O → groupe **A** | O//O → groupe **O** |\n\nLes quatre groupes sont possibles : AB, A, B et O.\n\n4. Oui. Jade est **O//O** : elle a reçu l'allèle **O de son père** et l'allèle **O de sa mère**. L'allèle O est **récessif** : chez ses parents, il était masqué par A ou par B, mais chez Jade il est en **double** et s'exprime. Deux génotypes différents (A//O et A//A) peuvent donner le même phénotype, mais ne transmettent pas la même chose."}$exo$::jsonb),
  ('3c9a5e5b-d862-5583-8985-d4d0073e39af'::uuid, 3, 'application', $exo${"titre":"Une maladie qui saute les générations","consigne":"Exploite la situation et construis des réponses argumentées.","enonce":"**Situation.** Une maladie héréditaire est due à un allèle **récessif**, noté m ; l'allèle normal, dominant, est noté N. Hugo et Clara ne sont **pas malades**, mais leur fils Théo est **malade**.\n\n**Document 2** : dans une région, un agriculteur ne cultive qu'**une seule variété** de blé obtenue par clonage. Une nouvelle maladie des plantes apparaît dans la région.\n\n1. Quel est le génotype de Théo ? Justifie.\n2. Déduis-en les génotypes d'Hugo et de Clara. Comment appelle-t-on de tels parents ?\n3. Hugo et Clara attendent un deuxième enfant. Montre, avec un tableau de croisement, qu'il peut être malade, porteur sain ou non porteur.\n4. D'où viennent les allèles nouveaux comme m ? Cite deux agents qui peuvent les provoquer.\n5. En t'appuyant sur le document 2, explique pourquoi la diversité génétique est « une assurance sur l'avenir ».","bareme":[{"critere":"Théo m//m, car un allèle récessif ne s'exprime qu'en double","points":4},{"critere":"Parents N//m, porteurs sains, justifiés","points":4},{"critere":"Tableau de croisement juste : N//N, N//m, m//m","points":5},{"critere":"Origine : mutation de la séquence d'ADN ; deux agents (UV, tabac, produits chimiques, rayonnements)","points":3},{"critere":"Diversité : une population variée compte des résistants, une variété clonée peut être détruite d'un coup","points":4}],"dureeMin":18,"corrige":"1. La maladie est due à un allèle **récessif** : il ne s'exprime qu'en **double**. Théo étant malade, il est **m//m**.\n\n2. Théo a reçu un allèle m de **chacun** de ses parents. Or ses parents ne sont pas malades : ils portent aussi l'allèle dominant N. Hugo et Clara sont donc **N//m** : ce sont des **porteurs sains** (hétérozygotes).\n\n3. Tableau de croisement :\n\n| | N (Hugo) | m (Hugo) |\n|---|---|---|\n| **N (Clara)** | N//N : non porteur | N//m : porteur sain |\n| **m (Clara)** | N//m : porteur sain | m//m : **malade** |\n\nLe deuxième enfant peut donc être malade (m//m), porteur sain (N//m) ou non porteur (N//N).\n\n4. Les nouveaux allèles viennent de **mutations** : une modification de la séquence d'ADN crée une nouvelle version du gène. Elles peuvent être spontanées (erreurs de copie) ou **provoquées** par les **ultraviolets**, le **tabac**, des **produits chimiques** ou des **rayonnements ionisants**.\n\n5. Le champ de blé cloné est **génétiquement uniforme** : si la nouvelle maladie atteint une plante, elle peut atteindre **toutes** les plantes et détruire la récolte **d'un seul coup**. Dans une population **diverse**, au contraire, certains individus portent des allèles qui leur permettent de **résister** : la population survit. La diversité génétique protège contre l'imprévu : c'est une **assurance sur l'avenir**."}$exo$::jsonb),
  ('1cf81499-8568-5b20-8f6c-90555a06f0f4'::uuid, 1, 'application', $exo${"titre":"Copier l'ADN","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Pourquoi l'ADN doit-il être copié avant chaque division cellulaire ?\n2. Décris les **quatre étapes** de la réplication de l'ADN.\n3. Complète : « La mitose …, la méiose et la fécondation … ». Explique en une phrase pourquoi un organisme a besoin des deux.","bareme":[{"critere":"Chaque cellule fille doit recevoir la même information","points":4},{"critere":"Les quatre étapes de la réplication dans l'ordre","points":9},{"critere":"Conserve / brassent, stabilité pour fonctionner et variabilité pour durer","points":7}],"dureeMin":7,"corrige":"1. Pour que **chaque cellule** fille possède **la même information** génétique que la cellule mère, l'ADN doit être **copié** avant la division.\n\n2. La réplication :\n- la double hélice s'**ouvre** ;\n- chaque brin sert de **modèle** ;\n- la **complémentarité** des bases (A-T, G-C) impose la séquence du brin neuf ;\n- on obtient **deux molécules d'ADN identiques**.\n\n3. « La mitose **conserve**, la méiose et la fécondation **brassent**. » Un organisme a besoin de **stabilité** pour fonctionner (des cellules identiques pour la croissance et la réparation) et de **variabilité** pour durer en tant qu'espèce."}$exo$::jsonb),
  ('1cf81499-8568-5b20-8f6c-90555a06f0f4'::uuid, 2, 'application', $exo${"titre":"Le daltonisme dans la famille de Lucas","consigne":"Lis la description de l'arbre généalogique et réponds en justifiant.","enonce":"**Document – La famille de Lucas**\n\n> Le grand-père maternel de Lucas, Georges, est **daltonien** (il confond certaines couleurs). Sa femme, Anne, ne l'est pas. Leur fille, Sophie, la mère de Lucas, **n'est pas daltonienne**. Sophie a épousé Karim, non daltonien. Ils ont deux enfants : **Lucas**, daltonien, et **Inès**, non daltonienne. Dans les trois générations de la famille, seuls des **hommes** sont daltoniens.\n\n1. Le daltonisme « saute-t-il » une génération ? Qu'en déduis-tu sur l'allèle responsable : dominant ou récessif ?\n2. Quel indice suggère que l'allèle est porté par le chromosome X ?\n3. Lucas a-t-il reçu l'allèle de son père ou de sa mère ? Justifie à l'aide des chromosomes sexuels.\n4. Cite un autre caractère transmis de la même façon.","bareme":[{"critere":"Oui, il saute la génération de Sophie, donc allèle probablement récessif","points":5},{"critere":"Indice : seuls des hommes sont touchés, donc chromosome X","points":5},{"critere":"Lucas XY : son X vient de sa mère, qui l'a reçu de Georges","points":7},{"critere":"Hémophilie citée","points":3}],"dureeMin":11,"corrige":"1. Oui : Georges est daltonien, sa fille Sophie ne l'est pas, et son petit-fils Lucas l'est. Le caractère **saute une génération** : l'allèle est probablement **récessif** (Sophie le porte sans l'exprimer).\n\n2. Seuls des **hommes** sont touchés dans la famille : un caractère qui touche presque uniquement les garçons est probablement porté par le chromosome **X**.\n\n3. Lucas est un garçon : il est **XY**. Son chromosome **Y** vient de son **père**, Karim ; son chromosome **X** vient donc de sa **mère**, Sophie. C'est de sa mère qu'il a reçu l'allèle du daltonisme. Sophie l'avait elle-même reçu de son père Georges, qui lui a transmis son X. N'ayant qu'un seul X, Lucas exprime l'allèle même s'il est récessif.\n\n4. L'**hémophilie** se transmet de la même façon."}$exo$::jsonb),
  ('1cf81499-8568-5b20-8f6c-90555a06f0f4'::uuid, 3, 'application', $exo${"titre":"Quand la copie se trompe","consigne":"Réponds en construisant un raisonnement précis, avec le vocabulaire du cours.","enonce":"**Situation.** Pendant l'été, Karl, 40 ans, prend de nombreux coups de soleil sans protection. Des années plus tard, un **cancer de la peau** se déclare. Il s'inquiète : « Mes enfants vont-ils hériter de ce cancer ? »\n\n**Document** : un brin d'ADN porte la séquence **G A T T C A**. Lors d'une réplication, la cellule fabrique pour ce brin le brin complémentaire **C T A T G T**.\n\n1. Écris le brin complémentaire correct. Repère l'erreur de copie commise par la cellule.\n2. Comment appelle-t-on une telle modification de la séquence ? Quel agent l'a probablement favorisée chez Karl ?\n3. Réponds à l'inquiétude de Karl en distinguant les cellules du corps et les cellules reproductrices.\n4. Explique comment une seule cellule mutée peut donner une tumeur, à l'aide de la mitose.\n5. Les tests génétiques permettent de dépister certains risques. Pourquoi posent-ils des questions éthiques ?","bareme":[{"critere":"Brin correct C T A A G T et erreur repérée (4e base : T au lieu de A)","points":4},{"critere":"Mutation ; agent : les ultraviolets","points":3},{"critere":"Mutation d'une cellule de peau non transmise ; seule une mutation des cellules reproductrices l'est","points":6},{"critere":"La mitose copie la mutation dans toutes les cellules issues de la cellule mutée","points":4},{"critere":"Question éthique argumentée (information sur soi et ses proches, choix que la science ne tranche pas)","points":3}],"dureeMin":17,"corrige":"1. Avec la règle A-T, G-C, le brin complémentaire de G A T T C A est **C T A A G T**. La cellule a écrit C T A **T** G T : la **4e base** est un **T** au lieu d'un **A**. C'est une erreur de copie.\n\n2. Une modification de la séquence d'ADN est une **mutation**. Chez Karl, elle a probablement été provoquée par les **ultraviolets** du soleil.\n\n3. Karl peut être rassuré sur ce point : la mutation est survenue dans une cellule **du corps** (la peau). Elle ne touche que la **descendance de cette cellule** et **ne se transmet pas** à ses enfants. Seule une mutation survenue dans une **cellule reproductrice** est **transmissible** à la descendance.\n\n4. La cellule mutée se divise par **mitose** : la mitose produit deux cellules **identiques**, qui portent donc toutes la mutation. Si la mutation n'est pas réparée et que les divisions se répètent, toutes les cellules issues de la première portent la même anomalie et peuvent former une **tumeur** : c'est ainsi que naissent certains cancers.\n\n5. Les tests génétiques reposent sur la connaissance de l'ADN. Ils révèlent des informations sur la personne **et sur sa famille**, qui partage une partie de son ADN ; ils peuvent annoncer un risque sans certitude, influencer des choix de vie, poser la question de qui a le droit de connaître ces informations. Ce sont des questions **éthiques** que la science seule ne tranche pas."}$exo$::jsonb),
  ('2255ef7e-b79b-5389-9649-a46db5471130'::uuid, 1, 'application', $exo${"titre":"Le corps à l'effort","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Que consomment davantage les muscles pendant un effort ?\n2. Cite **quatre** modifications immédiates de l'organisme pendant un effort, avec un chiffre pour au moins deux d'entre elles.\n3. Quel est le but commun de toutes ces modifications ?\n4. Dans quel ordre le muscle puise-t-il dans ses réserves d'énergie ?","bareme":[{"critere":"Glucose et dioxygène","points":3},{"critere":"Quatre modifications justes, dont deux chiffrées","points":8},{"critere":"But : apporter plus de dioxygène et de glucose, évacuer CO2 et chaleur","points":5},{"critere":"Ordre : glycogène du muscle, glucose sanguin, lipides","points":4}],"dureeMin":7,"corrige":"1. Les muscles consomment davantage de **glucose** et de **dioxygène**.\n\n2. Quatre modifications parmi :\n- la **fréquence cardiaque** augmente, de 70 à **150-190** battements par minute ;\n- le **débit cardiaque** est multiplié par **5** ;\n- la **ventilation** augmente (fréquence et amplitude) : la consommation de dioxygène est multipliée par **10 ou plus** ;\n- le sang est **redistribué** vers les muscles, qui passent d'environ **20 %** à plus de **80 %** du débit ;\n- la **sudation** augmente pour évacuer la chaleur.\n\n3. Toutes servent à **amener plus de dioxygène et de glucose aux muscles**, et à évacuer plus vite le **dioxyde de carbone** et la **chaleur**.\n\n4. D'abord le **glycogène** du muscle, puis le **glucose sanguin** (réapprovisionné par le foie), puis les **lipides** pour les efforts longs."}$exo$::jsonb),
  ('2255ef7e-b79b-5389-9649-a46db5471130'::uuid, 2, 'application', $exo${"titre":"Inès court le cross du collège","consigne":"Exploite les mesures et réponds en justifiant tes calculs.","enonce":"**Document – Les mesures d'Inès**\n\n| Mesure | Au repos | Pendant le cross |\n|---|---|---|\n| Fréquence cardiaque (battements/min) | 70 | 175 |\n| Volume d'air ventilé (L/min) | 8 | 80 |\n| Part du débit sanguin allant aux muscles | 20 % | 80 % |\n\n1. Calcule par combien est multiplié le volume d'air ventilé. Même question pour la part du débit sanguin allant aux muscles.\n2. De combien de battements par minute la fréquence cardiaque augmente-t-elle ?\n3. Explique l'intérêt de chacune de ces trois modifications pour les muscles d'Inès.\n4. Si la part du sang allant aux muscles augmente, quels organes en reçoivent moins ?","bareme":[{"critere":"Calculs justes : ventilation × 10, part du débit aux muscles × 4","points":5},{"critere":"Augmentation de 105 battements par minute","points":3},{"critere":"Intérêt expliqué pour les trois modifications (dioxygène, glucose, évacuation du CO2)","points":8},{"critere":"Organes digestifs moins irrigués","points":4}],"dureeMin":10,"corrige":"1. Ventilation : 80 / 8 = **10** : le volume d'air ventilé est **multiplié par 10**. Part du débit sanguin aux muscles : 80 / 20 = **4** : elle est **multipliée par 4**.\n\n2. 175 − 70 = **105 battements par minute** de plus.\n\n3. Intérêt :\n- la **ventilation** plus forte fait entrer plus de **dioxygène** dans le sang et rejette plus de **dioxyde de carbone** ;\n- le **cœur** qui bat plus vite envoie plus de sang, donc plus de dioxygène et de **glucose** aux muscles à chaque minute ;\n- la **redistribution** du sang envoie en priorité ce sang aux **muscles** qui travaillent.\nToutes ces modifications permettent aux muscles de produire plus d'énergie par la **respiration cellulaire**.\n\n4. Les **organes digestifs** reçoivent moins de sang pendant l'effort : le sang est redistribué vers les muscles à leur détriment."}$exo$::jsonb),
  ('2255ef7e-b79b-5389-9649-a46db5471130'::uuid, 3, 'application', $exo${"titre":"Le marathon de Paul","consigne":"Exploite la situation et construis des réponses argumentées avec les notions du cours.","enonce":"**Situation.** Paul, 45 ans, s'entraîne depuis un an pour un marathon. Sa fréquence cardiaque de repos est passée de **72** à **58** battements par minute. Le jour de la course, il part trop vite sans s'être échauffé. Vers le 30e kilomètre, il sent ses jambes « brûler », puis il a des vertiges et des sueurs froides. Il fait chaud et il n'a presque pas bu.\n\n1. Calcule la baisse de sa fréquence cardiaque de repos en pourcentage (arrondi à l'unité). Explique ce résultat par un effet de l'entraînement.\n2. Cite deux autres effets durables de l'entraînement.\n3. Au départ trop rapide, le dioxygène manque dans ses muscles. Quelle voie de production d'énergie prend le relais ? Quels sont ses inconvénients ?\n4. Les vertiges et sueurs froides du 30e kilomètre évoquent une **hypoglycémie**. Explique-la à partir de l'ordre d'utilisation des réserves.\n5. Relève deux erreurs de Paul et dis ce qu'il aurait dû faire.","bareme":[{"critere":"Baisse d'environ 19 % et explication : cœur plus puissant","points":4},{"critere":"Deux effets durables : capillaires, muscles, capacité respiratoire, récupération","points":3},{"critere":"Fermentation lactique : faible rendement, production d'acide lactique","points":4},{"critere":"Hypoglycémie : réserves de glycogène et de glucose épuisées","points":5},{"critere":"Deux erreurs et leurs corrections (échauffement, hydratation, allure progressive)","points":4}],"dureeMin":18,"corrige":"1. Baisse : 72 − 58 = 14 battements ; 14 / 72 × 100 ≈ **19 %**. L'entraînement rend le **cœur plus puissant** : il envoie plus de sang à chaque battement, donc il a besoin de battre **moins souvent** au repos.\n\n2. Deux effets parmi : des **muscles renforcés** (force, endurance) ; un réseau de **capillaires** plus dense ; une **capacité respiratoire** accrue ; une **récupération** plus rapide.\n\n3. Quand le dioxygène manque, la **fermentation lactique** prend le relais de la respiration cellulaire. Son **rendement est faible** (peu d'énergie produite) et elle produit de l'**acide lactique**.\n\n4. Le muscle puise d'abord dans son **glycogène**, puis dans le **glucose sanguin** fourni par le foie, et enfin dans les lipides. Au 30e kilomètre, les réserves de **glucose** sont **épuisées** : le taux de glucose dans le sang baisse, c'est l'**hypoglycémie**, qui se manifeste par des vertiges et des sueurs froides.\n\n5. Erreurs (deux parmi) :\n- **pas d'échauffement** : il aurait dû préparer progressivement cœur, muscles et articulations ;\n- **départ trop rapide** : il aurait dû garder une allure progressive pour rester en respiration cellulaire ;\n- **pas d'hydratation** par la chaleur : risque de **déshydratation**, de crampes et de coup de chaleur ; il aurait dû boire régulièrement (et se ravitailler en sucres pendant l'effort long)."}$exo$::jsonb),
  ('c44e4650-af80-585b-827b-0252ad8b1010'::uuid, 1, 'application', $exo${"titre":"Bouger pour sa santé","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Donne la définition de la **santé** selon l'OMS.\n2. Quelle durée d'activité physique l'OMS recommande-t-elle aux adolescents ?\n3. Cite **trois** bénéfices de l'activité physique, dans trois domaines différents.\n4. Cite deux risques de la **sédentarité**.","bareme":[{"critere":"Définition : état de complet bien-être physique, mental et social","points":5},{"critere":"Au moins 60 minutes par jour d'activité modérée à soutenue","points":4},{"critere":"Trois bénéfices justes dans trois domaines","points":7},{"critere":"Deux risques de la sédentarité","points":4}],"dureeMin":6,"corrige":"1. Selon l'OMS, la santé est **un état de complet bien-être physique, mental et social**, et pas seulement l'absence de maladie.\n\n2. Au moins **60 minutes** d'activité modérée à soutenue **par jour**.\n\n3. Trois bénéfices parmi :\n- **cardiovasculaire** : cœur plus efficace, moins d'infarctus et d'AVC ;\n- **métabolique** : contrôle du poids, prévention du diabète de type 2 ;\n- **musculo-squelettique** : muscles renforcés, os plus denses ;\n- **mental** : moins de stress, meilleur sommeil, meilleure concentration ;\n- **social** : appartenance à un groupe, coopération.\n\n4. Deux risques parmi : **surpoids** et **diabète**, **maladies cardiovasculaires** (la sédentarité est un facteur de risque **indépendant**), mal de dos, troubles du sommeil."}$exo$::jsonb),
  ('c44e4650-af80-585b-827b-0252ad8b1010'::uuid, 2, 'application', $exo${"titre":"La semaine de Nolan","consigne":"Exploite les données, fais les calculs demandés et justifie tes propositions.","enonce":"**Document – La semaine de Nolan, 14 ans**\n\n- EPS au collège : **3 heures** par semaine ;\n- entraînement de football le samedi : **1 h 30** ;\n- trajets en voiture, aucune marche ;\n- environ **5 heures d'écran** par jour.\n\n1. Calcule la durée totale d'activité physique de Nolan dans la semaine, en minutes.\n2. Calcule sa moyenne par jour (arrondie à la minute). Compare-la à la recommandation de l'OMS.\n3. Quels risques Nolan court-il à long terme ? Justifie.\n4. Propose trois changements réalistes, dont un qui dépend d'un aménagement collectif.","bareme":[{"critere":"Total juste : 270 minutes","points":4},{"critere":"Moyenne d'environ 39 minutes par jour, inférieure aux 60 minutes recommandées","points":5},{"critere":"Risques liés à la sédentarité et aux écrans justifiés","points":5},{"critere":"Trois propositions réalistes, dont une collective","points":6}],"dureeMin":10,"corrige":"1. 3 h = 180 min ; 1 h 30 = 90 min. Total : 180 + 90 = **270 minutes** par semaine.\n\n2. 270 / 7 ≈ **39 minutes** par jour. C'est **inférieur** aux **60 minutes par jour** recommandées par l'OMS : il lui manque environ 21 minutes chaque jour.\n\n3. Nolan est trop **sédentaire** : trajets en voiture et 5 heures d'écran. Il risque à long terme le **surpoids** et le **diabète de type 2** (dépense énergétique trop faible), des **maladies cardiovasculaires** (la sédentarité est un facteur de risque indépendant), le mal de dos et des **troubles du sommeil**. Le temps d'écran y contribue directement.\n\n4. Exemples de propositions :\n- aller au collège **à pied ou à vélo** ;\n- **réduire le temps d'écran** et le remplacer par une activité (sortie, sport entre amis) ;\n- s'inscrire à une deuxième activité, ou à l'association sportive du collège ;\n- aménagement **collectif** : une **piste cyclable** sécurisée jusqu'au collège, un équipement sportif accessible près de chez lui."}$exo$::jsonb),
  ('c44e4650-af80-585b-827b-0252ad8b1010'::uuid, 3, 'application', $exo${"titre":"Jusqu'où aller pour gagner ?","consigne":"Analyse le témoignage et rédige des réponses argumentées.","enonce":"**Document – Le témoignage de Mathis, 16 ans, cycliste**\n\n> « Je m'entraîne tous les jours, même quand je suis malade. Depuis deux mois, je suis tout le temps fatigué, je dors mal et je me suis blessé trois fois au genou. Pour perdre du poids, je saute le petit-déjeuner et je mange très peu de féculents. Un coéquipier me propose des produits “pour récupérer plus vite”. De toute façon, faire du sport, ça ne dépend que de moi. »\n\n1. Relève les signes de **surcharge** dans le témoignage. Que traduisent-ils ?\n2. Critique l'alimentation de Mathis : quel nutriment manque pour l'endurance, et pourquoi son régime est-il dangereux à son âge ?\n3. Quels risques les produits proposés lui feraient-ils courir ?\n4. Discute la dernière phrase de Mathis.\n5. Propose trois conseils pour qu'il pratique en préservant sa santé.","bareme":[{"critere":"Signes de surcharge relevés (fatigue, sommeil, blessures) et surentraînement nommé","points":4},{"critere":"Glucides complexes pour l'endurance ; régime restrictif dangereux pendant la croissance","points":4},{"critere":"Dopage : troubles cardiaques, hormonaux, psychiques, dépendance, tricherie","points":4},{"critere":"Responsabilité individuelle et collective discutée","points":4},{"critere":"Trois conseils pertinents (repos, récupération, sommeil, hydratation, s'entraîner guéri)","points":4}],"dureeMin":18,"corrige":"1. Signes de surcharge : **fatigue persistante**, **troubles du sommeil**, **blessures à répétition** (trois au genou). Ils indiquent que le corps ne **récupère plus** : c'est le **surentraînement**. S'entraîner malade l'aggrave.\n\n2. Mathis mange très peu de féculents : il manque de **glucides complexes**, indispensables aux efforts d'**endurance** comme le cyclisme. Sauter le petit-déjeuner le prive d'énergie. Les **régimes restrictifs** à l'adolescence sont **dangereux pendant la croissance** : risque de carences, de fatigue, de blessures. Aucun complément ne remplace une alimentation variée.\n\n3. Ces produits relèvent du **dopage** : c'est une **tricherie** sportive, et surtout un risque pour sa santé : **troubles cardiaques**, **hormonaux**, **psychiques**, et **dépendance**.\n\n4. La phrase est en partie vraie : le **choix de bouger** et la façon de pratiquer relèvent de la responsabilité **individuelle**. Mais la pratique dépend aussi du **collectif** : équipements accessibles, pistes cyclables, sécurité des trajets, cours d'EPS, encadrement du club. La santé publique se joue autant dans l'aménagement que dans la volonté individuelle.\n\n5. Conseils (trois parmi) : prévoir des **jours de repos** et une **récupération** ; respecter son **sommeil** ; ne pas s'entraîner **malade** ; manger équilibré avec des glucides complexes et des protéines ; bien **s'hydrater** ; s'échauffer et progresser graduellement ; refuser tout produit dopant et en parler à l'entraîneur ou à un médecin."}$exo$::jsonb),
  ('905df1c4-cc24-52ff-a3f1-9822574b5526'::uuid, 1, 'application', $exo${"titre":"Le trajet d'un message nerveux","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. De quoi se compose le système nerveux **central** ? Et le système nerveux **périphérique** ?\n2. Remets dans l'ordre le trajet d'un message : nerf moteur, récepteur sensoriel, organe effecteur, centre nerveux, nerf sensitif.\n3. Nomme les parties du **neurone** qui reçoivent le message et celle qui le transmet.\n4. Comment le message franchit-il une **synapse** ?","bareme":[{"critere":"Central : encéphale et moelle épinière ; périphérique : les nerfs","points":5},{"critere":"Ordre juste des cinq éléments","points":6},{"critere":"Dendrites reçoivent, axone transmet","points":5},{"critere":"Neurotransmetteurs chimiques à la synapse","points":4}],"dureeMin":7,"corrige":"1. Le système nerveux **central** comprend l'**encéphale** et la **moelle épinière** ; le système nerveux **périphérique** est formé des **nerfs**.\n\n2. Ordre : **récepteur sensoriel** → **nerf sensitif** → **centre nerveux** → **nerf moteur** → **organe effecteur** (muscle ou glande).\n\n3. Les **dendrites** reçoivent le message ; l'**axone** le transmet.\n\n4. À la synapse, le message passe grâce à des **neurotransmetteurs**, des substances **chimiques**. C'est là qu'agissent la plupart des drogues."}$exo$::jsonb),
  ('905df1c4-cc24-52ff-a3f1-9822574b5526'::uuid, 2, 'application', $exo${"titre":"La main sur la plaque chaude","consigne":"Lis la situation et réponds en utilisant le vocabulaire du cours.","enonce":"**Situation.** En cuisinant, Chloé pose par erreur la main sur une plaque brûlante. Elle la retire en une fraction de seconde, **avant** même de sentir la douleur. Quelques instants plus tard, elle décide volontairement d'aller passer sa main sous l'eau froide.\n\n1. Décris le trajet du message nerveux lors du retrait de la main, en nommant le stimulus, le récepteur, les nerfs, le centre nerveux et l'effecteur.\n2. Comment appelle-t-on ce type de réaction ? Où le message est-il traité ?\n3. Pourquoi Chloé retire-t-elle sa main avant d'avoir mal ?\n4. En quoi le geste d'aller sous l'eau froide est-il différent ? Où est-il décidé ?","bareme":[{"critere":"Trajet complet : chaleur, récepteurs de la peau, nerf sensitif, moelle, nerf moteur, muscle","points":7},{"critere":"Réflexe traité dans la moelle épinière","points":4},{"critere":"Explication : trajet court, réponse plus rapide que la perception par le cerveau","points":4},{"critere":"Geste volontaire décidé par le cerveau, plus lent","points":5}],"dureeMin":10,"corrige":"1. Le **stimulus** est la chaleur de la plaque. Il est capté par des **récepteurs sensoriels de la peau** de la main. Un message **sensitif** part par un **nerf sensitif** jusqu'à la **moelle épinière** (centre nerveux), qui élabore une réponse. Un message **moteur** repart par un **nerf moteur** vers les **muscles** du bras (effecteurs), qui se contractent et retirent la main.\n\n2. C'est un **réflexe** : le message est traité dans la **moelle épinière**, sans passer par la décision du cerveau.\n\n3. Le réflexe est **beaucoup plus rapide** qu'une réaction volontaire : la réponse est élaborée dans la moelle épinière, sur un trajet court. La sensation de douleur, elle, demande que le message remonte au cerveau : la main est déjà retirée quand Chloé a mal.\n\n4. Aller sous l'eau froide est une réaction **volontaire** : elle est décidée par le **cerveau**, après réflexion. Elle est **plus lente** que le réflexe."}$exo$::jsonb),
  ('905df1c4-cc24-52ff-a3f1-9822574b5526'::uuid, 3, 'application', $exo${"titre":"Protéger son cerveau","consigne":"Exploite les documents et construis des réponses argumentées.","enonce":"**Document 1 – Un test de temps de réaction** (freiner dès qu'un signal apparaît)\n\n| Situation | Temps de réaction |\n|---|---|\n| Sans alcool | 0,7 s |\n| Après consommation d'alcool | 1,2 s |\n\n**Document 2** : un conducteur de scooter roule à 45 km/h, soit **12,5 m/s**.\n\n**Document 3** : Enzo, 15 ans, se couche vers 1 h du matin après des heures d'écran, écoute sa musique très fort au casque et roule en scooter sans casque.\n\n1. Calcule la distance parcourue par le scooter pendant le temps de réaction, sans alcool puis avec alcool. Conclus.\n2. Sur quelle partie du neurone l'alcool et la plupart des drogues agissent-ils ? Pourquoi l'alcool est-il particulièrement toxique à l'adolescence ?\n3. Relève dans le document 3 trois comportements à risque et explique, pour chacun, ses effets sur le système nerveux.\n4. Explique pourquoi ces dégâts sont graves, en t'appuyant sur ce que devient un neurone détruit.","bareme":[{"critere":"Calculs justes : 8,75 m et 15 m, conclusion sur le danger","points":5},{"critere":"Synapse ; cerveau encore en développement","points":4},{"critere":"Trois comportements et leurs effets (sommeil, bruit, absence de casque)","points":7},{"critere":"Neurone détruit en général non remplacé, cellules ciliées irréversibles","points":4}],"dureeMin":18,"corrige":"1. Distance = vitesse × temps.\n- Sans alcool : 12,5 × 0,7 = **8,75 m**.\n- Avec alcool : 12,5 × 1,2 = **15 m**.\nAvec alcool, le scooter parcourt **6,25 m de plus** avant même que le conducteur commence à freiner : l'alcool **ralentit les réflexes** et augmente le risque d'accident.\n\n2. L'alcool et la plupart des drogues agissent au niveau de la **synapse**, sur la transmission par les **neurotransmetteurs**. L'alcool est particulièrement toxique à l'adolescence car le **cerveau est encore en développement**.\n\n3. Comportements à risque :\n- se coucher tard après des écrans : **manque de sommeil**. Le sommeil **consolide les apprentissages** ; en manquer dégrade la **mémoire**, l'**humeur** et l'**attention** ;\n- musique très forte au casque : le **bruit intense** détruit de façon **irréversible** les **cellules ciliées** de l'oreille interne ;\n- scooter **sans casque** : un choc à la tête peut détruire des neurones de l'encéphale.\n\n4. Ces dégâts sont graves car un neurone détruit n'est, dans la plupart des cas, **pas remplacé**, et les cellules ciliées ne se **régénèrent pas**. Il faut donc protéger son système nerveux : casque, protection auditive, temps de sommeil respecté, refus des substances."}$exo$::jsonb),
  ('1fae4080-61e9-51ba-899b-e3162f7754f2'::uuid, 1, 'application', $exo${"titre":"De l'aliment au nutriment","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. À quoi sert la **digestion** ?\n2. Dans quel organe se fait l'essentiel de la digestion **et** de l'absorption ?\n3. Recopie et complète :\n\n| L'aliment | Le nutriment obtenu |\n|---|---|\n| Amidon | … |\n| Protéines | … |\n| Lipides | … |\n\n4. Les **fibres** sont-elles digérées ? À quoi servent-elles ?","bareme":[{"critere":"Digestion : simplifier les grosses molécules en nutriments capables de traverser la paroi intestinale","points":5},{"critere":"Intestin grêle","points":3},{"critere":"Tableau juste : glucose, acides aminés, acides gras et glycérol","points":7},{"critere":"Fibres non digérées : transit et microbiote","points":5}],"dureeMin":7,"corrige":"1. La digestion sert à rendre les aliments **assimilables** : elle **simplifie les grosses molécules en petites**, les **nutriments**, capables de traverser la paroi intestinale.\n\n2. Dans l'**intestin grêle**.\n\n3. Tableau :\n\n| L'aliment | Le nutriment obtenu |\n|---|---|\n| Amidon | **glucose** |\n| Protéines | **acides aminés** |\n| Lipides | **acides gras** et **glycérol** |\n\n4. Non, les fibres **ne sont pas digérées** par nos enzymes. Elles **régulent le transit** et **nourrissent le microbiote** : elles sont indispensables, même sans valeur énergétique."}$exo$::jsonb),
  ('1fae4080-61e9-51ba-899b-e3162f7754f2'::uuid, 2, 'application', $exo${"titre":"L'expérience des trois tubes","consigne":"Analyse l'expérience et justifie chaque conclusion.","enonce":"**Document – Une expérience de digestion in vitro**\n\n> Rappel : l'eau iodée colore l'**amidon** en bleu-violet.\n\nOn place trois tubes à **37 °C** pendant 30 minutes.\n\n| Tube | Contenu | Test à l'eau iodée après 30 min | Glucose après 30 min |\n|---|---|---|---|\n| 1 | amidon + amylase | pas de coloration | présent |\n| 2 | amidon + eau | bleu-violet | absent |\n| 3 | blanc d'œuf (protéines) + amylase | — | absent, protéines intactes |\n\n1. À quoi sert le tube 2 ?\n2. Que s'est-il passé dans le tube 1 ? Justifie avec les résultats.\n3. Que montre le tube 3 sur l'amylase ? Quelle propriété des enzymes est ainsi mise en évidence ?\n4. Quelle enzyme aurait-il fallu mettre pour digérer le blanc d'œuf ?","bareme":[{"critere":"Tube 2 : témoin, l'amidon ne se transforme pas seul","points":4},{"critere":"Tube 1 : amidon disparu et glucose apparu, l'amylase a digéré l'amidon","points":6},{"critere":"Tube 3 : l'amylase n'agit pas sur les protéines, enzyme spécifique","points":6},{"critere":"Protéases","points":4}],"dureeMin":11,"corrige":"1. Le tube 2 est un **témoin** : il montre que, sans enzyme, l'amidon **ne se transforme pas** tout seul (l'eau iodée reste bleu-violet, pas de glucose).\n\n2. Dans le tube 1, l'eau iodée ne colore plus : l'**amidon a disparu**. Du **glucose est apparu**. L'**amylase** a donc **digéré l'amidon en glucose**, ce que l'eau seule ne fait pas.\n\n3. Dans le tube 3, les protéines sont intactes : l'amylase **n'agit pas** sur les protéines. Chaque enzyme digestive est **spécifique** d'un type de molécule : l'amylase n'attaque que l'amidon.\n\n4. Il aurait fallu des **protéases**, enzymes qui attaquent les protéines et les transforment en **acides aminés**."}$exo$::jsonb),
  ('1fae4080-61e9-51ba-899b-e3162f7754f2'::uuid, 3, 'application', $exo${"titre":"Les trois jours de Léo","consigne":"Analyse les menus et rédige des réponses argumentées avec les repères du cours.","enonce":"**Document – Ce qu'a mangé Léo, 14 ans, joueur de handball**\n\n| | Midi | Soir |\n|---|---|---|\n| Lundi | pizza, soda | chips, jambon, soda |\n| Mardi | pâtes complètes, lentilles, yaourt, pomme | poulet, riz, haricots verts, eau |\n| Mercredi | burger, frites, soda | céréales sucrées, lait |\n\nLe mardi soir, Léo a réchauffé un reste de poulet laissé une nuit hors du réfrigérateur ; il a eu des douleurs de ventre.\n\n1. Pourquoi ne faut-il pas juger l'équilibre alimentaire sur le seul repas du mardi midi ?\n2. En comparant aux repères du cours, relève sur les trois jours deux excès et deux manques.\n3. Léo est un adolescent sportif. Pourquoi ses besoins sont-ils particuliers ?\n4. Quel risque prend Léo si ce déséquilibre dure des années ?\n5. Explique les douleurs du mardi soir et cite deux règles de sécurité alimentaire.","bareme":[{"critere":"Équilibre évalué sur plusieurs jours","points":3},{"critere":"Deux excès (sodas, produits gras, sucrés, ultratransformés) et deux manques (fruits, légumes, eau) justifiés","points":6},{"critere":"Besoins variables : croissance et activité (énergie, calcium, protéines)","points":4},{"critere":"Risque à long terme : surpoids, obésité, diabète de type 2, maladies cardiovasculaires","points":3},{"critere":"Intoxication alimentaire (bactéries, chaîne du froid rompue) et deux règles","points":4}],"dureeMin":18,"corrige":"1. L'équilibre alimentaire ne s'évalue pas repas par repas mais **sur plusieurs jours** : un repas équilibré ne compense pas à lui seul les autres, et un repas déséquilibré n'est pas grave s'il reste exceptionnel.\n\n2. **Excès** : les **sodas** (quatre en trois jours, alors que l'**eau** est la seule boisson indispensable) ; les produits **gras, salés et ultratransformés** (pizza, chips, burger, frites) ; les **céréales sucrées**.\n**Manques** : les **fruits et légumes**, qui devraient être présents **à chaque repas** (une pomme et des haricots verts seulement, le mardi) ; l'**eau** ; les féculents complets et les légumineuses en dehors du mardi.\n\n3. Les besoins **varient** : Léo est **en croissance** et **sportif**. Il a besoin de plus d'**énergie** (glucides complexes pour l'effort), de **protéines** pour la croissance et la réparation musculaire, et de **calcium** et de **fer**.\n\n4. Si l'apport reste durablement **supérieur aux dépenses**, avec trop de sucres et de graisses, il risque le **surpoids** et l'**obésité**, puis le **diabète de type 2** et des **maladies cardiovasculaires** ; des carences sont aussi possibles.\n\n5. Le poulet est resté hors du froid : la **chaîne du froid** a été rompue, des **bactéries** (comme *Salmonella* ou *Listeria*) ont pu se multiplier : c'est une **intoxication alimentaire**. Règles (deux parmi) : respecter la chaîne du froid, cuire suffisamment, se laver les mains et laver les végétaux, respecter les dates de consommation, séparer le cru et le cuit."}$exo$::jsonb),
  ('7d8f4800-a58c-5119-abb9-0623e7a36e00'::uuid, 1, 'application', $exo${"titre":"Les défenses de l'organisme","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quelle différence y a-t-il entre une **contamination** et une **infection** ?\n2. Compare la réponse **innée** et la réponse **adaptative** : vitesse, spécificité, acteurs.\n3. Qu'est-ce que la **phagocytose** ?\n4. Que fabriquent les **lymphocytes B** ? Que font les **lymphocytes T** ?","bareme":[{"critere":"Contamination : entrée du micro-organisme ; infection : sa multiplication","points":4},{"critere":"Comparaison juste des deux réponses (vitesse, spécificité, acteurs)","points":7},{"critere":"Phagocytose : le phagocyte englobe et digère le micro-organisme","points":4},{"critere":"B : anticorps ; T : destruction des cellules infectées","points":5}],"dureeMin":7,"corrige":"1. La **contamination** est l'**entrée** d'un micro-organisme dans l'organisme (après avoir franchi la peau ou une muqueuse) ; l'**infection** est sa **multiplication** dans l'organisme.\n\n2. La réponse **innée** est **rapide** (quelques minutes à quelques heures) et **non spécifique** : réaction inflammatoire et **phagocytes**. La réponse **adaptative** est plus **lente** (quelques **jours**) et **spécifique** : **lymphocytes B et T**.\n\n3. La phagocytose : un **phagocyte** (globule blanc) **englobe** le micro-organisme et le **digère**.\n\n4. Les lymphocytes **B** fabriquent des **anticorps**, qui se fixent sur un antigène et neutralisent l'intrus. Les lymphocytes **T** **détruisent directement les cellules infectées**."}$exo$::jsonb),
  ('7d8f4800-a58c-5119-abb9-0623e7a36e00'::uuid, 2, 'application', $exo${"titre":"Premier et second contact","consigne":"Exploite le document et justifie tes réponses.","enonce":"**Document – La quantité d'anticorps dans le sang d'Aya contre un même virus**\n\n| | 1er contact avec le virus | 2e contact, deux ans plus tard |\n|---|---|---|\n| Apparition des anticorps | vers le 7e jour | dès le 2e jour |\n| Quantité maximale d'anticorps | 1 unité | environ 10 unités |\n| Symptômes | fièvre pendant 5 jours | aucun |\n\n1. Compare les deux réponses : délai et quantité d'anticorps.\n2. Explique pourquoi la réponse est différente au second contact.\n3. Pourquoi Aya n'a-t-elle aucun symptôme la deuxième fois ? Quel mot désigne son état ?\n4. Explique en quoi ce document permet de comprendre le principe de la vaccination.","bareme":[{"critere":"Comparaison chiffrée : plus rapide (2e jour contre 7e) et environ 10 fois plus intense","points":5},{"critere":"Cellules mémoire formées au premier contact","points":5},{"critere":"Intrus éliminé avant les symptômes, personne immunisée","points":4},{"critere":"Vaccination : antigène inoffensif, mémoire sans la maladie, rappel","points":6}],"dureeMin":11,"corrige":"1. Au second contact, la réponse est **plus rapide** (anticorps dès le 2e jour au lieu du 7e) et **plus intense** (environ **10 fois** plus d'anticorps).\n\n2. Lors du **premier contact**, la réponse adaptative a été lente, mais elle a laissé des **cellules mémoire**, qui persistent des années. Au second contact avec le **même antigène**, ces cellules réagissent aussitôt : c'est la **mémoire immunitaire**.\n\n3. Les anticorps, très nombreux et très vite produits, **éliminent le virus avant tout symptôme**. Aya est **immunisée**.\n\n4. Le vaccin apporte un **antigène rendu inoffensif** (micro-organisme tué, atténué, fragment, ou instruction pour fabriquer l'antigène). Il joue le rôle du **premier contact**, **sans provoquer la maladie** : il déclenche une réponse et surtout une **mémoire**. Lors d'une vraie contamination, la réponse est celle du second contact, rapide et intense. Un **rappel** entretient cette mémoire."}$exo$::jsonb),
  ('7d8f4800-a58c-5119-abb9-0623e7a36e00'::uuid, 3, 'application', $exo${"titre":"De l'écharde à l'immunité collective","consigne":"Exploite les situations et construis des réponses argumentées.","enonce":"**Situation 1.** Samuel s'est planté une écharde sale dans le doigt. Le lendemain, la zone est **rouge, chaude, gonflée et douloureuse**. Deux jours plus tard, tout est rentré dans l'ordre.\n\n**Situation 2.** Samuel attrape trois rhumes dans l'hiver, alors que chaque rhume laisse une mémoire immunitaire.\n\n**Situation 3.** Sa petite sœur, âgée de un mois, est trop jeune pour être vaccinée contre la rougeole. Pourtant, son médecin dit qu'elle est protégée si son entourage est vacciné.\n\n1. Situation 1 : comment appelle-t-on la réaction observée ? Explique l'origine de chacun des quatre signes, puis le mécanisme qui a éliminé les microbes.\n2. Situation 2 : explique pourquoi Samuel peut attraper plusieurs rhumes, en utilisant la notion de spécificité.\n3. Situation 3 : explique le principe de l'immunité collective.\n4. Quelle maladie a pu être éradiquée grâce à la vaccination, et en quelle année ?","bareme":[{"critere":"Réaction inflammatoire et origine des quatre signes","points":5},{"critere":"Phagocytose décrite, réponse innée suffisante","points":3},{"critere":"Spécificité : un anticorps ne reconnaît qu'un antigène, virus différents","points":5},{"critere":"Immunité collective : le microbe ne circule plus assez pour atteindre les non protégés","points":5},{"critere":"Variole, 1980","points":2}],"dureeMin":17,"corrige":"1. C'est la **réaction inflammatoire**, première étape de la réponse **innée**.\n- **Rougeur** et **chaleur** : dues à la **dilatation des vaisseaux** ;\n- **gonflement** : dû au **passage de liquide** hors des vaisseaux ;\n- **douleur** : due aux **médiateurs chimiques**.\nLes microbes ont ensuite été éliminés par **phagocytose** : des **phagocytes** les ont **englobés** puis **digérés**. Dans la plupart des cas, cette réponse innée suffit.\n\n2. Un **anticorps** ne reconnaît **qu'un seul antigène** : c'est la **spécificité** de la réponse adaptative. Les cellules mémoire formées contre un virus ne protègent que contre **ce** virus. Chaque rhume de Samuel est provoqué par un **virus différent** : sa mémoire ne le protège pas contre les nouveaux.\n\n3. Quand une **proportion suffisante** de la population est **immunisée**, le micro-organisme **ne circule plus assez** : il ne trouve presque plus de personnes à contaminer. Il n'atteint donc pas les personnes **non protégées**, comme les **nourrissons** trop jeunes pour être vaccinés ou les immunodéprimés. En se faisant vacciner, l'entourage protège la petite sœur.\n\n4. La **variole**, éradiquée en **1980**."}$exo$::jsonb),
  ('9369a0b4-6f60-50b0-8fc1-610fb095ee7d'::uuid, 1, 'application', $exo${"titre":"Trois leviers contre les infections","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Recopie et complète :\n\n| Le levier | Son moment | Ce qu'il fait |\n|---|---|---|\n| L'hygiène | … | … |\n| La vaccination | … | … |\n| Les antibiotiques | … | … |\n\n2. Quelle différence y a-t-il entre **asepsie** et **antisepsie** ?\n3. Contre quels micro-organismes les antibiotiques sont-ils efficaces ?","bareme":[{"critere":"Tableau complet et juste pour les trois leviers","points":9},{"critere":"Asepsie : éviter l'arrivée des microbes ; antisepsie : éliminer ceux déjà présents","points":6},{"critere":"Bactéries seulement, aucun effet sur les virus","points":5}],"dureeMin":7,"corrige":"1. Tableau :\n\n| Le levier | Son moment | Ce qu'il fait |\n|---|---|---|\n| L'hygiène | **Avant la contamination** | Elle **empêche l'arrivée** du microbe |\n| La vaccination | **Avant la maladie** | Elle **prépare** l'organisme (mémoire immunitaire) |\n| Les antibiotiques | **Après l'infection** | Ils **soignent**, les bactéries seulement |\n\n2. L'**asepsie** consiste à **éviter l'arrivée** des microbes (stérilisation, matériel à usage unique). L'**antisepsie** consiste à **éliminer ceux déjà présents**, sur la peau par exemple.\n\n3. Les antibiotiques ne sont efficaces que contre les **bactéries** : ils n'ont **aucun effet sur les virus** (grippe, rhume, bronchiolite, angine virale)."}$exo$::jsonb),
  ('9369a0b4-6f60-50b0-8fc1-610fb095ee7d'::uuid, 2, 'application', $exo${"titre":"L'angine d'Emma","consigne":"Lis la situation et le document, puis justifie chaque réponse.","enonce":"**Situation.** Emma a mal à la gorge et de la fièvre. Sa mère voudrait qu'elle reprenne les antibiotiques qui restent dans l'armoire.\n\nLe médecin fait un **test rapide** d'angine : il est **négatif**.\n\nUn mois plus tard, son frère Tom a une angine **bactérienne**. Le laboratoire réalise un **antibiogramme** :\n\n| Antibiotique | Résultat |\n|---|---|\n| Antibiotique A | la bactérie se multiplie |\n| Antibiotique B | la bactérie ne se multiplie plus |\n| Antibiotique C | la bactérie se multiplie |\n\n1. Que signifie le test négatif d'Emma ? Doit-elle prendre des antibiotiques ? Justifie.\n2. Pourquoi ne faut-il pas prendre les antibiotiques de l'armoire ?\n3. Qu'est-ce qu'un antibiogramme ? Quel antibiotique le médecin doit-il prescrire à Tom ?\n4. Tom se sent mieux au bout de 3 jours et veut arrêter son traitement de 6 jours. Que lui conseilles-tu ? Pourquoi ?","bareme":[{"critere":"Angine virale, antibiotiques inutiles car sans effet sur les virus","points":5},{"critere":"Pas d'automédication : pas forcément le bon antibiotique ni adapté","points":3},{"critere":"Antibiogramme défini, antibiotique B choisi et justifié","points":6},{"critere":"Traitement complet : arrêter tôt laisse survivre les bactéries les plus résistantes","points":6}],"dureeMin":11,"corrige":"1. Le test rapide sert à distinguer une angine **bactérienne** d'une angine **virale**. Négatif, il indique une angine **virale**. Emma ne doit **pas** prendre d'antibiotiques : ils n'ont **aucun effet sur les virus**. « Les antibiotiques, c'est pas automatique. »\n\n2. Ces antibiotiques ont été prescrits pour une autre infection : ce n'est pas forcément **le bon antibiotique**, et ici il n'y a pas de bactérie à soigner. Les prendre inutilement favorise en plus l'**antibiorésistance**.\n\n3. Un **antibiogramme** est un test qui permet de **choisir la molécule efficace** contre une bactérie donnée. Le médecin doit prescrire l'**antibiotique B** : c'est le seul qui empêche la bactérie de se multiplier ; elle est **résistante** à A et à C.\n\n4. Il faut aller **au bout du traitement**. Se sentir mieux ne veut pas dire que toutes les bactéries sont mortes : arrêter trop tôt laisse **survivre les bactéries les plus résistantes**, qui peuvent se multiplier à nouveau et favoriser l'antibiorésistance. Deux règles : **le bon antibiotique** et **le traitement complet**."}$exo$::jsonb),
  ('9369a0b4-6f60-50b0-8fc1-610fb095ee7d'::uuid, 3, 'application', $exo${"titre":"Antibiorésistance, sérum et vaccin","consigne":"Exploite les situations et construis des réponses argumentées.","enonce":"**Document 1.** L'OMS classe l'**antibiorésistance** parmi les grandes menaces sanitaires mondiales : certaines infections bactériennes deviennent difficiles à traiter.\n\n**Document 2.** Jules, 16 ans, se blesse profondément au pied avec un clou rouillé dans une ferme. Il n'est **pas vacciné** contre le tétanos. Aux urgences, on lui injecte d'abord un **sérum** contenant des anticorps contre la toxine du tétanos, puis on lui fait la **première dose du vaccin**.\n\n1. Explique comment un usage excessif des antibiotiques sélectionne des bactéries résistantes. Relie ce mécanisme à un autre chapitre du programme.\n2. Pourquoi le médecin injecte-t-il un sérum à Jules ? Quelles sont ses deux caractéristiques ?\n3. Pourquoi lui fait-il aussi le vaccin, alors que le sérum le protège déjà ?\n4. Le vaccin seul aurait-il suffi à protéger Jules de cette blessure ? Justifie.\n5. Cite deux mesures qui ont fait reculer la mortalité infectieuse, autres que les antibiotiques.","bareme":[{"critere":"Sélection des bactéries résistantes préexistantes, lien avec la sélection naturelle","points":5},{"critere":"Sérum : anticorps déjà formés, effet immédiat, sans mémoire, pour l'urgence","points":4},{"critere":"Vaccin : mémoire durable pour l'avenir","points":4},{"critere":"Non : vaccin préventif, réponse trop lente, sans effet sur une infection déclarée","points":4},{"critere":"Deux mesures : eau potable, assainissement, hygiène, vaccination","points":3}],"dureeMin":18,"corrige":"1. Dans une population de bactéries, quelques-unes portent **déjà**, par hasard, une mutation de résistance. Un antibiotique tue les bactéries sensibles et laisse **survivre les résistantes**, qui se **multiplient**. Plus on utilise d'antibiotiques (sans raison, ou en arrêtant trop tôt), plus on **sélectionne** les bactéries résistantes, qui deviennent majoritaires. C'est la **sélection naturelle** (chapitre sur l'évolution) appliquée aux microbes.\n\n2. Le tétanos est une urgence : Jules n'a aucune défense. Le **sérum thérapeutique** apporte des **anticorps déjà formés**. Il agit **immédiatement**, mais **sans mémoire** : sa protection ne dure pas.\n\n3. Le **vaccin** apporte un antigène inoffensif qui déclenche une réponse et surtout une **mémoire immunitaire**. Il protégera Jules **durablement**, lors des blessures futures (avec des **rappels**), ce que le sérum ne fait pas.\n\n4. Non. La vaccination est une mesure **préventive** : la réponse qu'elle déclenche prend **plusieurs jours**, et elle n'a **aucun effet sur une infection déjà déclarée**. Seul le sérum pouvait protéger Jules tout de suite.\n\n5. Deux mesures parmi : l'**eau potable**, l'**assainissement**, l'**hygiène** (lavage des mains, asepsie), la **vaccination**."}$exo$::jsonb),
  ('a5b6d7ab-1657-5ad8-b0e6-569bf41541df'::uuid, 1, 'application', $exo${"titre":"Ce qui change à la puberté","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Qu'est-ce que la **puberté** ? Entre quels âges se déroule-t-elle en moyenne ?\n2. Donne la différence entre caractères sexuels **primaires** et **secondaires**, avec deux exemples de caractères secondaires.\n3. Qu'est-ce qu'une **hormone** ?\n4. Quelle glande du cerveau déclenche la puberté ?","bareme":[{"critere":"Puberté : période qui rend capable de se reproduire, entre 10 et 16 ans en moyenne","points":5},{"critere":"Primaires : organes génitaux fonctionnels ; secondaires avec deux exemples","points":6},{"critere":"Hormone : message chimique produit par une glande, transporté par le sang, agit sur des cellules cibles","points":6},{"critere":"L'hypophyse","points":3}],"dureeMin":7,"corrige":"1. La puberté est la période de transformation qui **rend l'organisme capable de se reproduire**. Elle se déroule en moyenne entre **10 et 16 ans**, avec de grandes variations individuelles normales.\n\n2. Les caractères sexuels **primaires** sont les **organes génitaux**, qui se développent et deviennent **fonctionnels**. Les caractères **secondaires** sont les autres transformations du corps : deux parmi pilosité, développement des seins, mue de la voix, élargissement des hanches ou des épaules, poussée de croissance, changements de la peau.\n\n3. Une hormone est un **message chimique** produit par une **glande**, **transporté par le sang**, qui n'agit que sur les cellules capables de le reconnaître.\n\n4. L'**hypophyse**, commandée par le cerveau."}$exo$::jsonb),
  ('a5b6d7ab-1657-5ad8-b0e6-569bf41541df'::uuid, 2, 'application', $exo${"titre":"Le calendrier de Manon","consigne":"Exploite la situation et justifie tes réponses.","enonce":"**Situation.** Manon a un cycle régulier de **28 jours**. Ses dernières règles ont commencé le **3 mars**. On admet que l'ovulation a lieu environ **14 jours avant** le début des règles suivantes.\n\n1. Qu'est-ce que les **règles** ? Que marque leur premier jour ?\n2. Calcule la date probable du début des prochaines règles de Manon.\n3. Calcule la date probable de sa prochaine ovulation. Qu'est-ce que l'ovulation ?\n4. Compare la production de gamètes chez la femme et chez l'homme (rythme, organe, stock de départ).","bareme":[{"critere":"Règles : élimination de la muqueuse utérine sans fécondation, premier jour du cycle","points":4},{"critere":"Prochaines règles le 31 mars, calcul justifié","points":4},{"critere":"Ovulation vers le 17 mars et définition de l'ovulation","points":5},{"critere":"Comparaison : cyclique / continue, ovaires / testicules, stock dès la naissance / fabrication permanente","points":7}],"dureeMin":11,"corrige":"1. Les règles sont l'**élimination de la muqueuse de l'utérus**, qui s'était épaissie, quand il n'y a **pas eu de fécondation**. Leur premier jour marque le **premier jour du cycle**.\n\n2. 3 mars + 28 jours = **31 mars** : les prochaines règles devraient commencer vers le 31 mars.\n\n3. 31 mars − 14 jours = **17 mars** : l'ovulation aura lieu vers le 17 mars (14e jour du cycle). L'ovulation est la **libération d'un ovule par un ovaire**, environ tous les 28 jours.\n\n4. Comparaison :\n- chez la **femme**, la production est **cyclique** : un ovule environ tous les **28 jours**, par les **ovaires** ; le stock initial est constitué **dès la naissance** ; elle s'arrête à la **ménopause** ;\n- chez l'**homme**, elle est **continue** dès la puberté et toute la vie, par les **testicules** ; il n'y a pas de stock : les spermatozoïdes sont **fabriqués en permanence**."}$exo$::jsonb),
  ('a5b6d7ab-1657-5ad8-b0e6-569bf41541df'::uuid, 3, 'application', $exo${"titre":"Chloé n'est pas encore réglée","consigne":"Construis des réponses argumentées en t'appuyant sur les notions du cours.","enonce":"**Situation.** Chloé, 12 ans, n'a pas encore eu ses premières règles. Son amie Lina a eu les siennes il y a trois mois, mais ses cycles sont très irréguliers. Elles discutent :\n\n> **Chloé** : « Moi, je ne peux pas tomber enceinte puisque je n'ai jamais eu mes règles. »\n> **Lina** : « Et moi, avec des cycles aussi irréguliers, je ne risque rien non plus. »\n\n1. Décris la chaîne de commande hormonale qui déclenche la puberté, du cerveau jusqu'aux hormones produites chez la fille et chez le garçon.\n2. Chez la fille, dans quel ordre arrivent la première ovulation et les premières règles ? Explique pourquoi.\n3. Réponds à l'affirmation de Chloé, puis à celle de Lina.\n4. Où a lieu la fécondation ? Explique pourquoi une grossesse est possible dès la première ovulation.\n5. Les deux amies n'ont pas commencé leur puberté au même âge. Est-ce inquiétant ? Justifie.","bareme":[{"critere":"Chaîne cerveau → hypophyse → gonades → testostérone ou œstrogènes et progestérone","points":5},{"critere":"La première ovulation précède les premières règles, avec explication","points":4},{"critere":"Les deux affirmations réfutées et justifiées","points":6},{"critere":"Fécondation dans une trompe, ovule libéré fécondable","points":3},{"critere":"Variations individuelles normales","points":2}],"dureeMin":18,"corrige":"1. Le **cerveau** commande l'**hypophyse**, qui libère des **hormones** dans le sang. Ces hormones agissent sur les **gonades** : les **testicules** produisent la **testostérone** chez le garçon ; les **ovaires** produisent les **œstrogènes** et la **progestérone** chez la fille. Ces hormones déclenchent les transformations de la puberté.\n\n2. La **première ovulation précède** les premières règles. Les règles sont l'élimination de la muqueuse utérine **à la fin** d'un cycle sans fécondation : il faut donc qu'un cycle, avec son ovulation, ait déjà eu lieu avant les premières règles.\n\n3. **Chloé** se trompe : une première ovulation peut survenir **avant** ses premières règles, sans qu'elle le sache ; une grossesse est donc possible. **Lina** se trompe aussi : les **cycles irréguliers** du début n'offrent **aucune protection** ; on ne peut pas savoir quand l'ovulation a lieu.\n\n4. La fécondation a lieu dans une **trompe**. Dès la première ovulation, un **ovule** est libéré et peut rencontrer un spermatozoïde : la grossesse est possible dès ce moment (et, chez le garçon, dès les premières éjaculations).\n\n5. Non : la puberté se déroule en moyenne entre 10 et 16 ans, avec de **grandes variations individuelles**, **parfaitement normales**."}$exo$::jsonb),
  ('8c97c8d1-2d05-5212-8ebc-7ee745bbe9d7'::uuid, 1, 'application', $exo${"titre":"Le calendrier de la grossesse","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"**Questions de cours.**\n\n1. Où a lieu la **fécondation** ? Que se passe-t-il ?\n2. Combien de chromosomes la **cellule œuf** contient-elle ? Qu'est-ce qui détermine son sexe ?\n3. Qu'est-ce que la **nidation** ? Quand a-t-elle lieu ?\n4. Quelle différence y a-t-il entre la période **embryonnaire** et la période **fœtale** ?","bareme":[{"critere":"Fécondation dans une trompe, un spermatozoïde pénètre l'ovule, fusion des noyaux","points":5},{"critere":"46 chromosomes ; sexe déterminé par le chromosome du spermatozoïde","points":5},{"critere":"Nidation : implantation dans la muqueuse utérine, 6e ou 7e jour","points":5},{"critere":"Embryon jusqu'à 8 semaines (organes) ; fœtus ensuite (croissance)","points":5}],"dureeMin":7,"corrige":"1. La fécondation a lieu dans une **trompe** : un **seul spermatozoïde** pénètre l'**ovule**, et les **deux noyaux fusionnent**.\n\n2. La cellule œuf contient **46 chromosomes**. Son **sexe** est déterminé par le chromosome sexuel apporté par le **spermatozoïde** (X ou Y).\n\n3. La nidation est l'**implantation** de l'embryon dans la **muqueuse utérine**, au **6e ou 7e jour**. Sans nidation, il n'y a pas de grossesse.\n\n4. La période **embryonnaire** va jusqu'à la **8e semaine** : tous les **organes** se mettent en place (organogenèse). La période **fœtale** va de la 9e semaine à la naissance : c'est la **croissance** et la **maturation**."}$exo$::jsonb),
  ('8c97c8d1-2d05-5212-8ebc-7ee745bbe9d7'::uuid, 2, 'application', $exo${"titre":"Le placenta, organe des échanges","consigne":"Exploite le document et justifie tes réponses.","enonce":"**Document – Le sang du fœtus avant et après son passage dans le placenta** (valeurs relatives)\n\n| | Sang allant vers le placenta | Sang revenant du placenta |\n|---|---|---|\n| Dioxygène | 5 | 15 |\n| Glucose | 8 | 12 |\n| Dioxyde de carbone | 50 | 40 |\n| Urée (déchet) | 6 | 3 |\n\n1. Quelles substances le fœtus reçoit-il dans le placenta ? Lesquelles y dépose-t-il ? Justifie avec les valeurs.\n2. Quel organe relie le fœtus au placenta ?\n3. Les sangs de la mère et du fœtus se mélangent-ils ? Explique.\n4. Quel est le rôle du liquide amniotique ?","bareme":[{"critere":"Reçoit dioxygène et glucose (valeurs qui augmentent)","points":5},{"critere":"Dépose dioxyde de carbone et urée (valeurs qui diminuent)","points":5},{"critere":"Cordon ombilical ; sangs séparés par une barrière fine","points":6},{"critere":"Liquide amniotique : amortit les chocs, maintient la température","points":4}],"dureeMin":10,"corrige":"1. Le **dioxygène** passe de 5 à 15 et le **glucose** de 8 à 12 : leur quantité **augmente** dans le sang du fœtus, qui les **reçoit** de la mère (dioxygène et **nutriments**). Le **dioxyde de carbone** passe de 50 à 40 et l'**urée** de 6 à 3 : leur quantité **diminue**, le fœtus les **dépose** dans le placenta, et ils passent dans le sang de la mère (déchets).\n\n2. Le **cordon ombilical**.\n\n3. **Non** : les sangs maternel et fœtal circulent de part et d'autre d'une **barrière très fine**, à travers laquelle se font les échanges, sans se mélanger.\n\n4. Le liquide amniotique **amortit** et **protège des chocs**, et **maintient la température** du fœtus."}$exo$::jsonb),
  ('8c97c8d1-2d05-5212-8ebc-7ee745bbe9d7'::uuid, 3, 'application', $exo${"titre":"Protéger la grossesse dès le début","consigne":"Construis des réponses argumentées avec les notions du cours.","enonce":"**Situation.** Sarah apprend qu'elle est enceinte de **5 semaines**. Pendant les semaines précédentes, sans le savoir, elle a bu de l'alcool lors de deux fêtes. Une amie lui dit : « Pas grave, le placenta filtre tout, et un petit verre de temps en temps, ça ne risque rien. »\n\n1. À 5 semaines, s'agit-il d'un embryon ou d'un fœtus ? Pourquoi cette période est-elle la plus sensible ?\n2. Réfute les deux affirmations de l'amie.\n3. Cite trois autres règles qui protègent la grossesse, en justifiant l'une d'elles.\n4. Décris les étapes de l'accouchement.\n5. Après la naissance, le bébé est protégé quelques mois contre certaines maladies. Explique pourquoi.","bareme":[{"critere":"Embryon (avant 8 semaines), organogenèse, période la plus sensible","points":4},{"critere":"Placenta non filtre absolu ; aucune dose d'alcool sans risque","points":5},{"critere":"Trois règles dont une justifiée (tabac, drogue, médicaments, suivi médical, alimentation, vaccination)","points":4},{"critere":"Étapes : contractions, expulsion, cordon coupé, délivrance","points":4},{"critere":"Anticorps transmis par la mère","points":3}],"dureeMin":17,"corrige":"1. À 5 semaines, c'est un **embryon** : la période embryonnaire dure jusqu'à la **8e semaine**. C'est la période où **tous les organes se mettent en place** (organogenèse) : une agression extérieure peut perturber leur formation. C'est la période **la plus sensible**.\n\n2. « Le placenta filtre tout » est **faux** : le placenta n'est **pas un filtre absolu**, l'**alcool**, le tabac, les drogues, certains médicaments et certains virus le **traversent**. « Un petit verre ne risque rien » est **faux** aussi : il n'existe **aucune dose d'alcool sans risque** pendant la grossesse ; la règle est **zéro alcool**.\n\n3. Trois règles parmi : **ni tabac ni drogue** (ils traversent le placenta) ; **aucun médicament sans avis médical** (certains sont tératogènes, c'est-à-dire qu'ils provoquent des malformations) ; une **alimentation équilibrée** (les besoins augmentent) ; une **vaccination à jour** ; un **suivi médical** régulier avec consultations, **échographies** (datation, morphologie, croissance) et analyses.\n\n4. Les **contractions** dilatent le col de l'utérus ; l'**expulsion** : le bébé naît, après environ 9 mois ; le **cordon** est coupé ; la **délivrance** : le placenta est expulsé. Dans les premières minutes, le nouveau-né **respire seul** et sa circulation se réorganise.\n\n5. Le nouveau-né bénéficie encore quelques mois des **anticorps transmis par sa mère**, qui le protègent en attendant que ses propres défenses se construisent."}$exo$::jsonb),
  ('87819865-cef0-5fe3-a802-80754a06225f'::uuid, 1, 'application', $exo${"titre":"Les moyens de contraception en tableau","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite **deux** moyens de contraception **hormonaux** et **deux** moyens **mécaniques**.\n2. Explique comment agit principalement la **pilule** contraceptive.\n3. Quel est le **seul** moyen qui protège à la fois d'une grossesse et des **infections sexuellement transmissibles** ?\n4. Qu'est-ce que la « pilule du lendemain » ? Donne une règle importante sur son utilisation.","bareme":[{"critere":"Deux moyens hormonaux et deux moyens mécaniques correctement classés","points":6},{"critere":"Mode d'action de la pilule (blocage de l'ovulation, prise régulière) et préservatif cité","points":7},{"critere":"Contraception d'urgence : prise le plus tôt possible, ne remplace pas une contraception régulière","points":7}],"dureeMin":7,"corrige":"1. **Hormonaux** (deux parmi) : pilule, implant, patch, anneau, injection. **Mécaniques** (deux parmi) : préservatif masculin ou féminin, stérilet, diaphragme.\n\n2. La pilule **bloque l'ovulation** : aucun ovule n'est libéré, donc aucune fécondation n'est possible. Elle n'est efficace que si elle est **prise régulièrement**, sans oubli.\n\n3. Le **préservatif** (masculin ou féminin) : c'est le seul moyen qui protège à la fois d'une grossesse et des IST.\n\n4. C'est une **contraception d'urgence**, à prendre après un rapport non protégé (ou un oubli de pilule, un préservatif déchiré). Règles attendues (une suffit, deux valorisées) : la prendre **le plus tôt possible** ; elle **ne remplace jamais** une contraception régulière ; elle est délivrée sans ordonnance, gratuitement pour les mineures."}$exo$::jsonb),
  ('87819865-cef0-5fe3-a802-80754a06225f'::uuid, 2, 'application', $exo${"titre":"Inès et Hugo se posent des questions","consigne":"Lis la situation, puis réponds aux questions en justifiant avec tes connaissances.","enonce":"**Situation.** Inès, 16 ans, et Hugo, 17 ans, sont ensemble depuis quelques mois. Ils veulent choisir une contraception mais n'osent pas en parler à leurs parents. Un soir, le préservatif s'est déchiré.\n\n1. Où Inès et Hugo peuvent-ils aller pour être conseillés ? Précise deux caractéristiques de cette consultation pour des mineurs.\n2. Que doit faire Inès après le préservatif déchiré ? Justifie la rapidité.\n3. Inès envisage de prendre la pilule. Hugo propose alors d'arrêter le préservatif. Explique pourquoi ce n'est pas forcément une bonne idée.\n4. Cite deux éléments dont dépend le choix d'un moyen de contraception.","bareme":[{"critere":"Centre de santé sexuelle, consultation gratuite et confidentielle pour les mineurs","points":5},{"critere":"Contraception d'urgence prise le plus tôt possible, sans ordonnance et gratuite","points":5},{"critere":"La pilule ne protège pas des IST : seul le préservatif le fait","points":6},{"critere":"Deux critères de choix cités (âge, santé, mode de vie, contre-indications, désir de chacun)","points":4}],"dureeMin":10,"corrige":"1. Ils peuvent aller dans un **centre de santé sexuelle**. Pour les mineurs, la consultation est **gratuite** et **confidentielle** : l'accord des parents n'est pas nécessaire.\n\n2. Inès doit prendre une **contraception d'urgence** (« pilule du lendemain ») **le plus tôt possible** après le rapport, car son efficacité diminue avec le temps. Elle est délivrée **sans ordonnance** en pharmacie, **gratuitement** pour une mineure.\n\n3. La pilule **bloque l'ovulation** et évite donc une grossesse, mais elle **ne protège pas des infections sexuellement transmissibles**. Seul le **préservatif** protège à la fois d'une grossesse et des IST. Tant qu'ils n'ont pas fait de dépistage, garder le préservatif en plus de la pilule est la solution la plus sûre.\n\n4. Le choix dépend de **l'âge**, de **la santé** (contre-indications), du **mode de vie**, du **désir de chacun** (deux éléments suffisent)."}$exo$::jsonb),
  ('87819865-cef0-5fe3-a802-80754a06225f'::uuid, 3, 'application', $exo${"titre":"Maîtriser sa procréation : éviter, et être aidé","consigne":"Exploite les documents et tes connaissances. La dernière question demande un court paragraphe argumenté.","enonce":"**Document 1 — Deux couples en consultation.**\n\n> **Couple A** : après deux ans d'essais sans grossesse, les examens montrent que Mme A a les **trompes obstruées** ; ses ovaires fonctionnent normalement.\n>\n> **Couple B** : Mme B est en bonne santé ; M. B produit des **spermatozoïdes très peu nombreux et peu mobiles**.\n\n**Document 2 — Quelques repères.** Un couple sur six consulte pour des difficultés à concevoir. En France, l'IVG est autorisée depuis la **loi Veil de 1975**.\n\n1. Pour chaque couple, dis si l'infertilité est d'origine féminine ou masculine.\n2. Explique pourquoi une **insémination artificielle** ne suffirait pas au couple A. Quelle technique lui proposer ? Décris son principe.\n3. Quelle technique d'assistance médicale à la procréation est la plus adaptée au couple B ? Justifie.\n4. Un camarade affirme : « L'IVG, c'est un moyen de contraception comme un autre. » Corrige-le en donnant le statut, le délai et la prise en charge de l'IVG.\n5. Ces techniques posent des questions éthiques. Rédige un court paragraphe : cite deux de ces questions et explique qui les tranche en France, et comment.","bareme":[{"critere":"Origines de l'infertilité correctement identifiées pour les deux couples","points":3},{"critere":"Couple A : trompes bouchées donc rencontre impossible dans le corps, FIV décrite (fécondation au laboratoire, transfert d'embryon)","points":5},{"critere":"Couple B : ICSI (un spermatozoïde injecté dans l'ovule) justifiée par le faible nombre et la faible mobilité","points":4},{"critere":"IVG : droit (loi Veil 1975), 14 semaines de grossesse, prise en charge à 100 %, pas une contraception","points":4},{"critere":"Paragraphe : deux questions éthiques et rôle de la loi de bioéthique révisée par le débat démocratique","points":4}],"dureeMin":18,"corrige":"1. Couple A : infertilité d'origine **féminine** (trompes obstruées). Couple B : infertilité d'origine **masculine** (spermatozoïdes peu nombreux et peu mobiles).\n\n2. L'insémination dépose le sperme **dans l'utérus** ; mais la fécondation se fait normalement dans la **trompe**. Si les trompes sont bouchées, les spermatozoïdes ne peuvent pas rejoindre l'ovule : l'insémination échoue. On propose une **FIV** (fécondation in vitro) : on prélève des ovules, la rencontre des gamètes se fait **au laboratoire**, puis un **embryon est transféré** dans l'utérus — les trompes sont contournées.\n\n3. L'**ICSI** : un **spermatozoïde unique est injecté** directement dans l'ovule. Elle convient quand les spermatozoïdes sont trop peu nombreux ou trop peu mobiles pour féconder seuls l'ovule, même au laboratoire. (Un don de gamètes est possible si l'ICSI ne suffit pas.)\n\n4. L'IVG **n'est pas un moyen de contraception** : c'est un **droit** garanti en France depuis la **loi Veil de 1975**, possible jusqu'à **14 semaines de grossesse** (16 semaines d'aménorrhée), par méthode médicamenteuse ou chirurgicale, et **prise en charge à 100 %**. La contraception, elle, sert à **éviter** la grossesse.\n\n5. Paragraphe attendu : les techniques d'AMP posent des questions **éthiques**, par exemple le **devenir des embryons congelés** non utilisés, l'**anonymat des donneurs** de gamètes, ou l'**accès** à ces techniques (qui peut en bénéficier). En France, ces questions sont tranchées par la **loi de bioéthique**, **régulièrement révisée** : ce n'est pas la science seule qui décide, mais le **débat démocratique** (Parlement, consultation des citoyens), car ces choix engagent des valeurs et pas seulement des possibilités techniques."}$exo$::jsonb),
  ('7b9cf9f2-dd75-52e8-b501-e03af97cdc28'::uuid, 1, 'application', $exo${"titre":"Objet ou système ?","consigne":"Réponds à chaque question par une phrase complète en utilisant le vocabulaire du cours.","enonce":"**Situation.** Dans la maison de Yanis, on trouve : un tournevis, une alarme anti-intrusion, une chaise, un portail automatisé.\n\n1. Classe ces quatre éléments en deux groupes : objets techniques et systèmes techniques. Justifie la différence entre les deux.\n2. Pour la lampe de bureau de Yanis, indique l'utilisateur, la matière d'œuvre et la fonction d'usage.","bareme":[{"critere":"Classement juste : tournevis et chaise = objets ; alarme et portail = systèmes","points":8},{"critere":"Différence objet / système expliquée (seul ou plusieurs objets qui travaillent ensemble)","points":5},{"critere":"Utilisateur, matière d'œuvre et fonction d'usage de la lampe corrects","points":7}],"dureeMin":6,"corrige":"1. **Objets techniques** : le tournevis et la chaise. **Systèmes techniques** : l'alarme et le portail automatisé.\nUn objet technique répond à un besoin **par lui-même** ; un système technique associe **plusieurs objets qui travaillent ensemble**, souvent avec de l'électronique et un programme (capteurs, carte, moteur ou sirène).\n2. Pour la lampe de bureau :\n- **utilisateur** (à qui elle rend service) : Yanis, celui qui lit ou travaille ;\n- **matière d'œuvre** (sur quoi elle agit) : la lumière de la pièce / du bureau ;\n- **fonction d'usage** (dans quel but) : **éclairer**."}$exo$::jsonb),
  ('7b9cf9f2-dd75-52e8-b501-e03af97cdc28'::uuid, 2, 'application', $exo${"titre":"Famille et lignée de l'éclairage","consigne":"Lis la situation puis réponds en justifiant avec les notions du cours.","enonce":"**Situation.** Pour un exposé, Chloé a réuni des objets et des images :\n\n- une bougie ;\n- une lampe à huile ;\n- une ampoule à filament ;\n- une ampoule LED ;\n- trois générations successives du même modèle de lampe frontale d'une marque (2015, 2019, 2024).\n\n1. Quelle est la fonction d'usage commune à la bougie, la lampe à huile, l'ampoule et la LED ? Comment appelle-t-on ce groupement ?\n2. Comment appelle-t-on le groupement des trois générations de lampe frontale ? Justifie.\n3. Cite deux moteurs d'évolution qui peuvent expliquer le passage de l'ampoule à filament à la LED.","bareme":[{"critere":"Fonction d'usage « éclairer » et notion de famille correctement nommée","points":6},{"critere":"Notion de lignée nommée et justifiée par les améliorations successives d'un même objet","points":6},{"critere":"Deux moteurs d'évolution pertinents, appliqués à l'éclairage","points":8}],"dureeMin":10,"corrige":"1. Tous ces objets ont la même fonction d'usage : **éclairer**, mais avec des solutions différentes (flamme, filament chauffé, diode). C'est une **famille** d'objets techniques.\n2. C'est une **lignée** : on suit **un même objet** (la lampe frontale de ce modèle) dans ses **améliorations successives** au fil du temps.\n3. Deux moteurs parmi :\n- le **progrès scientifique et technique** : l'électronique a permis la diode électroluminescente (LED) ;\n- les **contraintes environnementales et réglementaires** : réduire la consommation d'énergie, normes interdisant peu à peu les ampoules peu efficaces ;\n- les **contraintes économiques** : baisser le coût d'usage (électricité) ;\n- l'**évolution des besoins** : un éclairage qui dure plus longtemps et chauffe moins.\nChaque moteur doit être relié à l'éclairage pour obtenir tous les points."}$exo$::jsonb),
  ('7b9cf9f2-dd75-52e8-b501-e03af97cdc28'::uuid, 3, 'application', $exo${"titre":"150 ans de vélo","consigne":"Analyse le document puis rédige tes réponses en mobilisant toutes les notions du chapitre.","enonce":"**Document.**\n\n| Époque | Le vélo |\n|---|---|\n| Vers 1870 | Grand bi : cadre en fer, roue avant géante, pédales fixées sur la roue, pas de frein efficace |\n| Vers 1890 | Bicyclette « de sécurité » : deux roues égales, transmission par chaîne, pneus gonflables |\n| Vers 1980 | Cadre en aluminium, dérailleur à plusieurs vitesses, freins à patins |\n| Aujourd'hui | Vélo à assistance électrique : moteur, batterie, capteur de pédalage, éclairage LED |\n\n1. Le vélo d'aujourd'hui est-il un objet technique ou un système technique ? Et le grand bi ? Justifie.\n2. Donne l'utilisateur, la matière d'œuvre et la fonction d'usage du vélo. A-t-elle changé en 150 ans ?\n3. Ces quatre vélos forment-ils une famille ou une lignée ? Justifie.\n4. Pour deux évolutions du document, identifie le moteur d'évolution en jeu.","bareme":[{"critere":"Grand bi = objet technique ; VAE = système (moteur, batterie, capteur travaillent ensemble)","points":5},{"critere":"Utilisateur, matière d'œuvre, fonction d'usage « se déplacer » inchangée","points":4},{"critere":"Lignée justifiée (même objet amélioré successivement)","points":4},{"critere":"Deux évolutions reliées chacune à un moteur d'évolution pertinent","points":5},{"critere":"Réponses rédigées et appuyées sur le document","points":2}],"dureeMin":16,"corrige":"1. Le **grand bi** est un **objet technique** : il répond au besoin par lui-même, sans électronique. Le **vélo à assistance électrique** est un **système technique** : moteur, batterie, capteur de pédalage et carte électronique **travaillent ensemble**.\n2. Utilisateur : le cycliste. Matière d'œuvre : le cycliste lui-même (sa position, qu'on déplace). Fonction d'usage : **se déplacer**. Elle **n'a pas changé** en 150 ans ; tout le reste a changé.\n3. C'est une **lignée** : le document suit **le même objet**, le vélo, à travers ses **améliorations successives**. Une famille réunirait des objets différents de même fonction (vélo, trottinette, voiture…).\n4. Exemples attendus (deux suffisent) :\n- roues égales, chaîne, freins → **évolution des besoins** (se déplacer plus sûrement) ;\n- cadre en aluminium, dérailleur → **progrès scientifique et technique** (nouveaux matériaux, mécanismes) ;\n- assistance électrique, LED → **progrès technique** (électronique, batteries) et besoins de se déplacer **plus proprement** (contraintes environnementales) ;\n- éclairage obligatoire → **contraintes réglementaires** (sécurité)."}$exo$::jsonb),
  ('f504522a-6e0f-5389-af46-93f2102f9fb1'::uuid, 1, 'application', $exo${"titre":"Du service rendu au composant","consigne":"Complète et justifie en utilisant les quatre niveaux vus en cours.","enonce":"**Situation.** Inès étudie la trottinette de son frère.\n\n1. Donne la définition de : fonction d'usage, fonction technique, principe technique, solution technique.\n2. Pour la trottinette, range ces quatre éléments dans le bon niveau : « se déplacer », « freiner », « le frottement », « frein à disque ».","bareme":[{"critere":"Quatre définitions justes (service rendu, fonction interne, phénomène physique, composant concret)","points":10},{"critere":"Quatre éléments de la trottinette rangés au bon niveau","points":10}],"dureeMin":6,"corrige":"1. Définitions :\n- **fonction d'usage** : le **service rendu** à l'utilisateur, exprimé par un verbe à l'infinitif ;\n- **fonction technique** : ce que l'objet doit assurer **en interne** pour remplir sa fonction d'usage ;\n- **principe technique** : le **phénomène physique** utilisé pour réaliser une fonction ;\n- **solution technique** : le **composant concret** retenu.\n2. Pour la trottinette :\n- fonction d'usage : **se déplacer** ;\n- fonction technique : **freiner** ;\n- principe technique : **le frottement** ;\n- solution technique : **frein à disque**."}$exo$::jsonb),
  ('f504522a-6e0f-5389-af46-93f2102f9fb1'::uuid, 2, 'application', $exo${"titre":"Le diagramme des fonctions d'un vélo de ville","consigne":"Construis ta réponse étape par étape en respectant le vocabulaire du cours.","enonce":"**Situation.** Un fabricant conçoit un vélo de ville. Voici des éléments en vrac :\n\n> chaîne et pignons · phare LED · guidon et fourche · cadre en acier · frein à patins · dynamo\n\n1. Donne la fonction d'usage du vélo.\n2. Associe chaque élément de la liste à la fonction technique qu'il réalise, parmi : transmettre le mouvement, freiner, diriger, supporter le poids, éclairer.\n3. Pour la fonction « freiner », cite deux autres solutions techniques possibles et le principe technique commun.","bareme":[{"critere":"Fonction d'usage « se déplacer » exprimée par un verbe à l'infinitif","points":3},{"critere":"Chaque élément associé à la bonne fonction technique","points":10},{"critere":"Deux autres solutions de freinage et principe du frottement","points":7}],"dureeMin":10,"corrige":"1. Fonction d'usage : **se déplacer**.\n2. Associations :\n- chaîne et pignons → **transmettre le mouvement** (du pédalier à la roue) ;\n- phare LED et dynamo → **éclairer** (voir et être vu) ;\n- guidon et fourche → **diriger** ;\n- cadre en acier → **supporter le poids** ;\n- frein à patins → **freiner**.\n3. Autres solutions pour freiner : **frein à disque**, **rétropédalage** (ou frein à tambour). Elles reposent toutes sur le **même principe technique : le frottement**. Une même fonction technique peut donc avoir **plusieurs solutions techniques**."}$exo$::jsonb),
  ('f504522a-6e0f-5389-af46-93f2102f9fb1'::uuid, 3, 'application', $exo${"titre":"Choisir le frein d'un vélo cargo","consigne":"Analyse les documents, compare les solutions et justifie ton choix avec des critères chiffrés.","enonce":"**Situation.** Une entreprise conçoit un vélo cargo pour livrer des colis en ville. Le cahier des charges impose, pour la fonction « freiner » : **distance d'arrêt inférieure à 5 m à 20 km/h, vélo chargé**.\n\n**Document – Essais réalisés à 20 km/h, vélo chargé**\n\n| Solution | Distance d'arrêt | Masse | Coût | Entretien |\n|---|---|---|---|---|\n| Frein à patins | 6,2 m | 0,4 kg | 25 € | Patins à changer souvent |\n| Frein à disque mécanique | 4,6 m | 0,9 kg | 70 € | Moyen |\n| Frein à disque hydraulique | 3,8 m | 0,8 kg | 140 € | Faible |\n\n1. Identifie la fonction d'usage du vélo cargo, la fonction technique étudiée et le principe technique commun aux trois solutions.\n2. Dans l'exigence du cahier des charges, quel est le critère et quel est le niveau ?\n3. Quelle(s) solution(s) respecte(nt) l'exigence ? Justifie avec les valeurs.\n4. Propose un choix final en tenant compte des autres contraintes et justifie-le.\n5. Pourquoi l'exigence « le vélo doit bien freiner » serait-elle insuffisante ?","bareme":[{"critere":"Fonction d'usage, fonction technique et principe (frottement) corrects","points":4},{"critere":"Critère (distance de freinage) et niveau (< 5 m à 20 km/h) identifiés","points":3},{"critere":"Élimination du frein à patins justifiée par 6,2 m > 5 m","points":4},{"critere":"Choix final argumenté avec au moins deux contraintes (coût, masse, entretien)","points":6},{"critere":"Explication : sans critère chiffré l'exigence est invérifiable","points":3}],"dureeMin":18,"corrige":"1. Fonction d'usage : **transporter / livrer des colis en se déplaçant** (se déplacer). Fonction technique : **freiner**. Principe technique commun : **le frottement** (patins ou plaquettes frottent sur la jante ou le disque).\n2. **Critère** : la distance de freinage (ce qu'on mesure). **Niveau** : moins de 5 m à 20 km/h, vélo chargé (la valeur à atteindre).\n3. Le frein à patins ne respecte pas l'exigence : **6,2 m > 5 m**. Les deux freins à disque la respectent : **4,6 m** et **3,8 m**, tous deux inférieurs à 5 m.\n4. Choix argumenté attendu, par exemple : le **frein à disque hydraulique** — marge de sécurité plus grande (3,8 m), entretien faible pour un usage professionnel quotidien, masse légèrement plus faible ; son coût plus élevé (140 €) se justifie par la sécurité et l'entretien réduit. Un choix du disque mécanique est accepté s'il est justifié (respecte l'exigence, deux fois moins cher). Le diagramme des fonctions sert justement à **comparer** les solutions selon coût, poids, sécurité, entretien.\n5. « Bien freiner » n'a **ni critère ni niveau chiffré** : on ne peut pas le mesurer, donc pas le vérifier. Sans critère chiffré, une exigence n'est qu'un vœu."}$exo$::jsonb),
  ('bb3476f5-4feb-5287-8e49-cc3dc2990cf1'::uuid, 1, 'application', $exo${"titre":"Les étapes de la vie d'un smartphone","consigne":"Réponds en utilisant le vocabulaire du cours.","enonce":"**Situation.** Lucie vient de changer de téléphone. Son ancien appareil fonctionne encore mais ne reçoit plus de mises à jour.\n\n1. Cite dans l'ordre les cinq étapes du cycle de vie d'un smartphone et donne un exemple d'action pour chacune.\n2. Où Lucie doit-elle déposer son ancien téléphone ? Pourquoi ?\n3. Quelle forme d'obsolescence touche son ancien téléphone ?","bareme":[{"critere":"Cinq étapes dans l'ordre avec un exemple chacune","points":10},{"critere":"Dépôt en déchèterie ou point de collecte (DEEE), justifié","points":6},{"critere":"Obsolescence logicielle identifiée","points":4}],"dureeMin":7,"corrige":"1. Les cinq étapes :\n- **extraction** des matières premières : minerais pour les métaux, pétrole pour les plastiques, sable pour le verre ;\n- **fabrication** : transformation, assemblage des composants, emballage ;\n- **distribution** : transport et vente en magasin ou en ligne ;\n- **utilisation** : usage, recharge (énergie), entretien, réparation ;\n- **fin de vie** : collecte, tri, recyclage, valorisation énergétique ou enfouissement.\n2. C'est un **DEEE** (déchet d'équipement électrique et électronique) : il contient des métaux précieux **et** des substances dangereuses. Il ne va **jamais** à la poubelle ordinaire : Lucie le dépose en **déchèterie ou dans un point de collecte** (ou le donne pour réemploi).\n3. Il n'est pas cassé mais ne reçoit plus de mises à jour : c'est l'**obsolescence logicielle**."}$exo$::jsonb),
  ('bb3476f5-4feb-5287-8e49-cc3dc2990cf1'::uuid, 2, 'application', $exo${"titre":"Sac plastique ou sac réutilisable ?","consigne":"Utilise les données pour répondre, en montrant tes calculs.","enonce":"**Situation.** Une analyse du cycle de vie simplifiée donne l'énergie consommée pour fabriquer et transporter deux sacs de courses :\n\n| Sac | Énergie sur tout son cycle de vie | Nombre d'utilisations |\n|---|---|---|\n| Sac plastique jetable | 0,5 MJ | 1 |\n| Sac réutilisable en tissu | 12 MJ | autant qu'on veut |\n\n1. Que mesure une analyse du cycle de vie (ACV) ?\n2. La famille Martin fait 2 courses par semaine. Combien d'énergie consomment les sacs jetables en une année (52 semaines) ?\n3. À partir de combien d'utilisations le sac en tissu devient-il plus avantageux en énergie ?\n4. Explique en une phrase ce que montre cet exemple.","bareme":[{"critere":"Définition de l'ACV : impacts à toutes les étapes du cycle de vie","points":4},{"critere":"Calcul juste : 104 sacs × 0,5 MJ = 52 MJ","points":5},{"critere":"Seuil trouvé : plus de 24 utilisations (12 ÷ 0,5)","points":7},{"critere":"Conclusion : le réutilisable n'est avantageux qu'après un certain nombre de réemplois","points":4}],"dureeMin":11,"corrige":"1. L'**ACV** mesure les **impacts environnementaux** d'un objet (énergie, eau, ressources consommées ; déchets et émissions produits) sur **toutes les étapes** de son cycle de vie, de l'extraction à la fin de vie.\n2. Nombre de sacs par an : 2 × 52 = **104 sacs**. Énergie : 104 × 0,5 = **52 MJ**.\n3. Le sac en tissu coûte 12 MJ quel que soit le nombre d'utilisations. Il devient avantageux quand les sacs jetables qu'il remplace dépassent 12 MJ : 12 ÷ 0,5 = **24**. Il faut donc l'utiliser **plus de 24 fois** (à 24 utilisations, égalité).\n4. Un sac réutilisable coûte plus cher à fabriquer : il ne devient avantageux **qu'après un certain nombre de réemplois** ; seule l'analyse du cycle de vie permet de le savoir. Ici, la famille Martin l'amortit en moins de 3 mois."}$exo$::jsonb),
  ('bb3476f5-4feb-5287-8e49-cc3dc2990cf1'::uuid, 3, 'application', $exo${"titre":"Réparer ou remplacer un lave-linge ?","consigne":"Analyse les documents, puis rédige une réponse argumentée en mobilisant le cycle de vie, l'économie circulaire et l'obsolescence.","enonce":"**Situation.** Le lave-linge de la famille Diallo a 7 ans. La pompe de vidange est en panne.\n\n**Document 1 – Deux devis**\n\n| Option | Coût |\n|---|---|\n| Réparation : pompe neuve + main-d'œuvre | 110 € |\n| Lave-linge neuf | 450 € |\n\n**Document 2 – Données constructeur**\n\n> Indice de réparabilité du modèle : 7,8/10. Pièces détachées disponibles pendant 10 ans. Pour un lave-linge, l'étape d'utilisation (électricité, eau chaude) représente la plus grande part de l'énergie consommée sur tout le cycle de vie.\n\n1. Si la famille jette l'appareil, quelles étapes du cycle de vie faudra-t-il refaire pour un nouvel appareil ? Quel modèle économique cela illustre-t-il ?\n2. Quel levier de l'économie circulaire la réparation représente-t-elle ? Que signifie l'indice de réparabilité ?\n3. Un vendeur affirme : « Un appareil neuf consomme un peu moins, donc le changer est toujours plus écologique. » Discute cette affirmation avec le document 2.\n4. Conclus : que conseilles-tu à la famille ? Où doit aller l'appareil le jour de sa fin de vie ?","bareme":[{"critere":"Extraction, fabrication, distribution à refaire ; modèle linéaire identifié","points":4},{"critere":"Levier réemployer/réparer et sens de l'indice de réparabilité","points":4},{"critere":"Discussion nuancée de l'affirmation (utilisation dominante, mais fabrication évitée)","points":5},{"critere":"Conseil argumenté avec les devis et fin de vie en filière DEEE","points":5},{"critere":"Rédaction structurée, vocabulaire précis","points":2}],"dureeMin":18,"corrige":"1. Il faudrait refaire l'**extraction** (métaux, plastiques), la **fabrication** et la **distribution** d'un nouvel appareil, et gérer la **fin de vie** de l'ancien. C'est le modèle **linéaire** : extraire, fabriquer, jeter — il épuise les ressources.\n2. La réparation relève du levier **réemployer et réparer** de l'économie circulaire, qui referme la boucle. L'**indice de réparabilité** est une note obligatoire indiquant si un produit est facile à réparer ; 7,8/10 est une bonne note, et les pièces restent disponibles 10 ans.\n3. L'affirmation est **partiellement vraie** : l'utilisation est bien l'étape qui consomme le plus d'énergie, donc un appareil plus sobre fait économiser. Mais elle oublie que remplacer impose l'énergie et les ressources de l'**extraction** et de la **fabrication** d'un appareil neuf, et crée un déchet. Seule une **analyse du cycle de vie** complète permet de trancher ; un gain de consommation faible ne compense pas toujours un appareil entier fabriqué.\n4. Conseil attendu : **réparer** (110 € contre 450 €, soit 340 € économisés ; appareil bien réparable, pièces disponibles ; panne limitée à une pièce). Le jour de sa fin de vie, c'est un **DEEE** : déchèterie ou point de collecte, **jamais** la poubelle ordinaire, pour récupérer les métaux et traiter les substances dangereuses."}$exo$::jsonb),
  ('dbd2d18c-ae0c-50e3-9173-f9906f2161d0'::uuid, 1, 'application', $exo${"titre":"Les interacteurs d'un sèche-cheveux","consigne":"Réponds en utilisant le vocabulaire du diagramme des interacteurs.","enonce":"**Situation.** Tom étudie un sèche-cheveux.\n\n1. Qu'est-ce qu'un interacteur ? Cite quatre interacteurs du sèche-cheveux.\n2. Quelle est la différence entre une fonction principale et une fonction contrainte dans un diagramme des interacteurs ?\n3. Écris la fonction principale du sèche-cheveux.","bareme":[{"critere":"Définition de l'interacteur et quatre interacteurs pertinents","points":8},{"critere":"Fonction principale (relie deux interacteurs) / contrainte (un seul) distinguées","points":6},{"critere":"Fonction principale correctement formulée avec deux interacteurs","points":6}],"dureeMin":7,"corrige":"1. Un **interacteur** est un élément de l'environnement en relation avec l'objet technique. Pour le sèche-cheveux : l'**utilisateur**, les **cheveux** (matière d'œuvre), l'**énergie électrique** (réseau), le **milieu** (humidité de la salle de bain), les **normes** de sécurité électrique, le **budget**, l'**esthétique**.\n2. La **fonction principale** relie **deux** interacteurs **à travers l'objet** : c'est la raison d'être de l'objet. Une **fonction contrainte** relie l'objet à **un seul** interacteur : c'est une exigence à respecter.\n3. Fonction principale : **permettre à l'utilisateur de sécher ses cheveux**."}$exo$::jsonb),
  ('dbd2d18c-ae0c-50e3-9173-f9906f2161d0'::uuid, 2, 'application', $exo${"titre":"Le diagramme d'une borne de recharge","consigne":"Construis le diagramme des interacteurs en respectant les règles du cours.","enonce":"**Situation.** Une commune installe une borne de recharge pour vélos électriques sur une place publique.\n\n1. Cite six interacteurs de la borne.\n2. Rédige la fonction principale de la borne.\n3. Rédige quatre fonctions contraintes, chacune avec un seul interacteur.\n4. Décris comment on dessine le diagramme des interacteurs (place de l'objet, des interacteurs, des liaisons).","bareme":[{"critere":"Six interacteurs pertinents","points":4},{"critere":"Fonction principale reliant deux interacteurs à travers la borne","points":5},{"critere":"Quatre fonctions contraintes correctes, un seul interacteur chacune","points":8},{"critere":"Règles de construction : objet au centre, interacteurs autour, liaisons","points":3}],"dureeMin":12,"corrige":"1. Interacteurs : l'**utilisateur** (cycliste), le **vélo électrique / sa batterie** (matière d'œuvre), le **réseau électrique**, le **milieu** (pluie, froid, soleil), les **normes** électriques, le **budget** de la commune, le **paysage urbain** (esthétique), les **vandales / passants**.\n2. Fonction principale : **permettre au cycliste de recharger la batterie de son vélo**.\n3. Fonctions contraintes (exemples) :\n- résister aux **intempéries** ;\n- s'alimenter sur le **réseau électrique** ;\n- respecter les **normes** de sécurité électrique ;\n- s'intégrer au **paysage urbain** ;\n- rester dans le **budget** de la commune.\n4. On place **l'objet (la borne) au centre**, les **interacteurs autour**. La fonction principale est un trait qui relie **deux interacteurs en passant par l'objet** ; chaque fonction contrainte est un trait entre l'objet et **un seul** interacteur."}$exo$::jsonb),
  ('dbd2d18c-ae0c-50e3-9173-f9906f2161d0'::uuid, 3, 'application', $exo${"titre":"Une gourde connectée au banc d'essai","consigne":"Analyse la situation, construis le diagramme des interacteurs et porte un jugement argumenté.","enonce":"**Situation.** Une start-up lance une gourde connectée pour lycéens : elle mesure l'eau bue et envoie un rappel au téléphone.\n\n**Document – Retours de clients après un mois**\n\n> « Elle me rappelle bien de boire, mais elle a fui dans mon sac. » (Sarah)\n> « Impossible de la laver au lave-vaisselle, l'électronique a grillé. » (Mehdi)\n> « À 49 €, c'est trop cher pour une gourde. » (un parent)\n\n1. Identifie la matière d'œuvre et rédige la fonction principale de la gourde.\n2. Cite quatre autres interacteurs et rédige pour chacun une fonction contrainte.\n3. Pour chaque retour client, indique quelle fonction contrainte n'est pas remplie.\n4. La start-up affirme : « Notre gourde est réussie, puisqu'elle rappelle bien de boire. » Discute cette affirmation.\n5. À quoi aurait dû servir ce diagramme au début du projet ?","bareme":[{"critere":"Matière d'œuvre (l'eau) et fonction principale à deux interacteurs","points":4},{"critere":"Quatre interacteurs avec une fonction contrainte chacun","points":5},{"critere":"Chaque retour client relié à la bonne fonction contrainte non remplie","points":5},{"critere":"Discussion : fonction principale remplie ne suffit pas","points":4},{"critere":"Rôle du diagramme : première étape du cahier des charges","points":2}],"dureeMin":17,"corrige":"1. Matière d'œuvre : **l'eau**. Fonction principale : **permettre au lycéen de transporter son eau et de suivre ce qu'il boit** (relie l'utilisateur et l'eau à travers la gourde).\n2. Interacteurs et contraintes (exemples) : le **sac** → ne pas fuir (étanchéité) ; le **lave-vaisselle / l'entretien** → résister au lavage ; le **téléphone** → communiquer avec lui ; l'**énergie** (batterie) → fonctionner plusieurs jours ; le **budget** → coûter un prix acceptable ; les **normes** → être sans danger au contact alimentaire.\n3. Sarah → contrainte d'**étanchéité** (ne pas fuir dans le sac) non remplie. Mehdi → contrainte de **résistance au lavage / au milieu** non remplie. Le parent → contrainte **économique / budget** non remplie.\n4. L'affirmation est fausse : la gourde remplit sa **fonction principale**, mais elle **manque plusieurs fonctions contraintes**. Or un objet réussi est celui qui remplit sa fonction principale **sans manquer une seule** de ses fonctions contraintes.\n5. Le diagramme des interacteurs est la **première étape du cahier des charges** : chaque fonction identifiée devient une **exigence à mesurer** (étanchéité, lavage, prix). Fait au début, il aurait évité ces défauts."}$exo$::jsonb),
  ('8e8fdd30-590a-522d-aa79-d2c24580337c'::uuid, 1, 'application', $exo${"titre":"Ranger les contraintes d'un jouet","consigne":"Associe chaque contrainte à sa famille et justifie brièvement.","enonce":"**Situation.** Un fabricant conçoit une voiture télécommandée pour enfants. Voici des contraintes du projet :\n\na. Prix de vente inférieur à 30 €.\nb. Porter le marquage CE et être interdit aux moins de 3 ans.\nc. Coque en plastique recyclable.\nd. Télécommande tenant dans une main d'enfant.\ne. Couleurs vives dans le style de la marque.\n\n1. Donne la famille de chaque contrainte.\n2. Qu'est-ce qu'une contrainte, en technologie ?","bareme":[{"critere":"Cinq contraintes rangées dans la bonne famille","points":15},{"critere":"Définition : exigence imposée au concepteur, qui limite ses choix","points":5}],"dureeMin":6,"corrige":"1. Familles :\n- a. prix inférieur à 30 € → **économique** ;\n- b. marquage CE, âge minimal → **réglementaire** (normes, sécurité) ;\n- c. plastique recyclable → **environnementale** ;\n- d. télécommande adaptée à la main d'un enfant → **ergonomique** (confort, facilité d'usage) ;\n- e. couleurs et style de la marque → **esthétique**.\n2. Une **contrainte** est une **exigence imposée au concepteur** : elle **limite ses choix** et doit être respectée."}$exo$::jsonb),
  ('8e8fdd30-590a-522d-aa79-d2c24580337c'::uuid, 2, 'application', $exo${"titre":"Réécrire le cahier des charges d'un casque","consigne":"Transforme les souhaits en exigences vérifiables, avec critère, niveau et flexibilité.","enonce":"**Situation.** Pour un casque de vélo, le client a écrit :\n\n> « Le casque doit être léger, bien aéré et pas trop cher. »\n\n1. Pourquoi ces trois souhaits ne sont-ils pas des exigences utilisables ?\n2. Réécris chacun sous forme d'exigence avec un critère, un niveau chiffré et une flexibilité (F0, F1 ou F2). Invente des valeurs réalistes.\n3. Laquelle de ces exigences mettrais-tu en F0 si l'on ajoutait « résister à un choc selon la norme » ? Justifie.","bareme":[{"critere":"Explication : aucun critère mesurable ni niveau chiffré, donc invérifiable","points":4},{"critere":"Trois exigences réécrites avec critère, niveau chiffré et flexibilité cohérents","points":12},{"critere":"Sécurité (choc selon la norme) en F0 justifiée","points":4}],"dureeMin":11,"corrige":"1. « Léger », « bien aéré », « pas trop cher » sont des adjectifs : il n'y a **ni critère mesurable ni niveau chiffré**. On ne peut pas les tester ; une contrainte non mesurable est **invérifiable**.\n2. Exemples attendus :\n- **Léger** → critère : masse ; niveau : inférieure à 300 g ; flexibilité : ±20 g, **F1** ;\n- **Aéré** → critère : nombre ou surface d'ouvertures d'aération ; niveau : au moins 12 aérations ; flexibilité **F2** ;\n- **Pas trop cher** → critère : prix de vente ; niveau : inférieur à 40 € ; flexibilité **F1** ou **F2**.\nToute valeur réaliste est acceptée si le trio critère / niveau / flexibilité est complet.\n3. La résistance aux chocs selon la norme est en **F0 (impératif)** : c'est une contrainte **réglementaire et de sécurité**, non négociable ; le casque ne peut pas être vendu sans elle. La masse ou le prix peuvent être négociés, pas la sécurité."}$exo$::jsonb),
  ('8e8fdd30-590a-522d-aa79-d2c24580337c'::uuid, 3, 'application', $exo${"titre":"Arbitrer pour une trottinette électrique","consigne":"Analyse le cahier des charges et les solutions proposées, puis rédige un arbitrage argumenté.","enonce":"**Document 1 – Extrait du cahier des charges**\n\n| Fonction | Critère | Niveau | Flexibilité |\n|---|---|---|---|\n| Être transportable | Masse | < 14 kg | ±1 kg, F1 |\n| Être sûre | Freinage | Conforme à la norme | F0 |\n| Être abordable | Prix de vente | < 400 € | F2 |\n| Avoir de l'autonomie | Distance | > 25 km | F1 |\n\n**Document 2 – Trois prototypes**\n\n| Prototype | Masse | Freinage | Prix | Autonomie |\n|---|---|---|---|---|\n| A (cadre acier, grosse batterie) | 17 kg | Conforme | 380 € | 35 km |\n| B (cadre aluminium, batterie moyenne) | 14,5 kg | Conforme | 450 € | 27 km |\n| C (cadre aluminium, frein simplifié) | 12 kg | Non conforme | 330 € | 26 km |\n\n1. Que signifient F0, F1 et F2 ?\n2. Vérifie chaque prototype exigence par exigence (tolérances comprises).\n3. Quel prototype élimines-tu d'emblée ? Pourquoi ?\n4. Explique, avec deux exemples tirés du document, pourquoi concevoir c'est arbitrer.\n5. Quel prototype retiens-tu ? Justifie ton arbitrage.","bareme":[{"critere":"F0 impératif, F1 peu négociable, F2 négociable","points":3},{"critere":"Vérification juste des trois prototypes, tolérance de ±1 kg appliquée","points":5},{"critere":"Élimination de C : exigence F0 de sécurité non respectée","points":4},{"critere":"Deux exemples de contraintes qui s'opposent (alléger/prix, autonomie/masse)","points":4},{"critere":"Choix final cohérent et justifié par les flexibilités","points":4}],"dureeMin":20,"corrige":"1. **F0** : impératif ; **F1** : peu négociable ; **F2** : négociable. C'est la **flexibilité** (tolérance) de chaque exigence.\n2. Vérification :\n- **A** : masse 17 kg > 15 kg (14 + 1) → non conforme (F1) ; freinage conforme ; prix 380 € < 400 € conforme ; autonomie 35 km conforme.\n- **B** : masse 14,5 kg, dans la tolérance (≤ 15 kg) → acceptable ; freinage conforme ; prix 450 € > 400 € → hors niveau mais **F2 négociable** ; autonomie 27 km conforme.\n- **C** : masse 12 kg conforme ; **freinage non conforme** ; prix 330 € conforme ; autonomie 26 km conforme.\n3. On élimine **C** : il manque une exigence **F0 (sécurité)**, impérative, même s'il est le meilleur ailleurs.\n4. Les contraintes s'opposent : **alléger** (aluminium de B et C) coûte **plus cher** (B à 450 €) ; plus d'**autonomie** (grosse batterie de A) rend **plus lourd** ; baisser le **prix** (C) a été obtenu en dégradant la **sécurité**. On ne peut pas tout satisfaire au maximum.\n5. Retenir **B** : il respecte les exigences F0 et F1 (masse dans la tolérance, autonomie) ; seul le prix dépasse, sur une exigence **F2 négociable**. A échoue sur une exigence F1 (3 kg de trop pour être transportable). Concevoir, c'est **arbitrer**, en sacrifiant d'abord ce qui est négociable."}$exo$::jsonb),
  ('07196afe-c9c5-5917-a216-b2daff251ef8'::uuid, 1, 'application', $exo${"titre":"Les critères pour choisir une bouilloire","consigne":"Réponds en utilisant les critères de comparaison du cours.","enonce":"**Situation.** Nadia hésite entre deux bouilloires.\n\n1. Associe chaque question au bon critère de comparaison :\n   a. Combien de temps fonctionne-t-elle sans panne ?\n   b. Est-elle facile et confortable à utiliser ?\n   c. Les pièces détachées existent-elles ?\n   d. Ses matériaux sont-ils recyclables ?\n2. Qu'est-ce que le coût global d'un objet ?","bareme":[{"critere":"Quatre questions associées au bon critère","points":12},{"critere":"Coût global défini : achat + usage + entretien","points":8}],"dureeMin":5,"corrige":"1. Associations :\n- a. → la **fiabilité** ;\n- b. → l'**ergonomie** ;\n- c. → la **réparabilité** ;\n- d. → l'**impact environnemental**.\n2. Le **coût global** est le **prix d'achat plus les coûts d'usage** (énergie consommée) **et d'entretien** sur toute la durée de vie. C'est lui qui décide, pas le seul prix d'achat : une bouilloire moins chère mais qui consomme plus ou casse vite peut revenir plus cher."}$exo$::jsonb),
  ('07196afe-c9c5-5917-a216-b2daff251ef8'::uuid, 2, 'application', $exo${"titre":"Le tableau multicritère des enceintes","consigne":"Complète le tableau par le calcul et conclus.","enonce":"**Situation.** Le foyer du collège doit acheter une enceinte. Chaque solution est notée sur 5.\n\n| Critère | Coefficient | Enceinte A | Enceinte B |\n|---|---|---|---|\n| Performance sonore | 2 | 4 | 5 |\n| Coût | 3 | 5 | 2 |\n| Fiabilité | 1 | 3 | 4 |\n\n1. Calcule le total **sans** pondération de chaque enceinte.\n2. Calcule le total **pondéré** de chaque enceinte.\n3. Quelle enceinte choisir ? Explique pourquoi le résultat change.","bareme":[{"critere":"Totaux non pondérés justes : A = 12, B = 11","points":4},{"critere":"Totaux pondérés justes avec calculs : A = 26, B = 20","points":8},{"critere":"Choix de A et rôle du coefficient expliqué","points":8}],"dureeMin":10,"corrige":"1. Sans pondération : A = 4 + 5 + 3 = **12** ; B = 5 + 2 + 4 = **11**.\n2. Avec pondération :\n- A = 4 × 2 + 5 × 3 + 3 × 1 = 8 + 15 + 3 = **26** ;\n- B = 5 × 2 + 2 × 3 + 4 × 1 = 10 + 6 + 4 = **20**.\n3. On choisit l'**enceinte A** (26 contre 20). Ici les deux méthodes donnent le même vainqueur, mais l'écart grandit (1 point → 6 points) : le **coefficient 3 sur le coût** fait entrer la priorité du foyer (un budget limité) dans le calcul. Sans pondération, le prix et la fiabilité compteraient autant ; c'est le **coefficient** qui traduit les priorités du cahier des charges."}$exo$::jsonb),
  ('07196afe-c9c5-5917-a216-b2daff251ef8'::uuid, 3, 'application', $exo${"titre":"Filament ou LED : le coût global","consigne":"Calcule, compare et rédige une justification fondée sur le coût global et le cahier des charges.","enonce":"**Situation.** Le gymnase municipal doit remplacer ses ampoules. On compare, pour une durée de **15 000 heures** d'éclairage :\n\n| Ampoule | Prix unitaire | Puissance | Durée de vie |\n|---|---|---|---|\n| À filament | 1 € | 60 W | 1 000 h |\n| LED | 8 € | 8 W | 15 000 h |\n\nPrix de l'électricité : **0,25 € par kWh**. Rappel : énergie (kWh) = puissance (kW) × durée (h).\n\n1. Combien d'ampoules de chaque type faut-il pour 15 000 h ? Quel est le coût d'achat ?\n2. Calcule l'énergie consommée et son coût pour chaque type.\n3. Calcule le coût global de chaque solution sur 15 000 h.\n4. Le cahier des charges impose aussi : « recyclable en filière DEEE » et « éclairement suffisant (F0) ». Les deux ampoules éclairent autant. Rédige la justification du choix.","bareme":[{"critere":"Nombre d'ampoules et coûts d'achat justes (15 € / 8 €)","points":4},{"critere":"Énergies et coûts d'électricité justes (900 kWh, 225 € / 120 kWh, 30 €)","points":6},{"critere":"Coûts globaux justes (240 € / 38 €)","points":4},{"critere":"Justification par le coût global et la confrontation au cahier des charges","points":6}],"dureeMin":18,"corrige":"1. Filament : 15 000 ÷ 1 000 = **15 ampoules**, soit 15 × 1 € = **15 €**. LED : 15 000 ÷ 15 000 = **1 ampoule**, soit **8 €**.\n2. Filament : 0,060 kW × 15 000 h = **900 kWh**, coût 900 × 0,25 = **225 €**. LED : 0,008 kW × 15 000 h = **120 kWh**, coût 120 × 0,25 = **30 €**.\n3. Coût global : filament = 15 + 225 = **240 €** ; LED = 8 + 30 = **38 €**. La LED coûte plus de six fois moins cher sur la durée.\n4. Justification attendue : les deux solutions atteignent l'exigence **F0** d'éclairement ; on les départage donc sur les autres critères. La LED est **huit fois plus chère à l'achat** mais son **coût global** est bien plus faible (38 € contre 240 €), elle consomme 7,5 fois moins d'énergie et produit 15 fois moins de déchets (1 ampoule au lieu de 15), recyclée en filière DEEE. On choisit la **LED** : un choix se justifie par la **confrontation au cahier des charges** et par le coût global, jamais par le seul prix d'achat."}$exo$::jsonb),
  ('7a86ab1e-0c46-5c92-9521-40dbe889788d'::uuid, 1, 'application', $exo${"titre":"La chaîne d'énergie du ventilateur","consigne":"Complète la chaîne d'énergie dans l'ordre et nomme les composants.","enonce":"**Situation.** Un ventilateur de bureau est branché sur une prise. On l'allume avec un interrupteur ; un moteur fait tourner l'hélice, fixée directement sur l'arbre du moteur.\n\n1. Écris dans l'ordre les quatre fonctions de la chaîne d'énergie.\n2. Pour le ventilateur, donne le composant qui assure chaque fonction.\n3. Quelle est l'action produite ?","bareme":[{"critere":"Quatre fonctions dans l'ordre : alimenter, distribuer, convertir, transmettre","points":8},{"critere":"Composants justes pour chaque fonction","points":9},{"critere":"Action : l'hélice tourne et brasse l'air","points":3}],"dureeMin":6,"corrige":"1. **Alimenter → distribuer → convertir → transmettre**.\n2. Pour le ventilateur :\n- **alimenter** : le **réseau électrique** 230 V (la prise) ;\n- **distribuer** : l'**interrupteur**, qui laisse passer ou coupe le courant ;\n- **convertir** : le **moteur électrique** (actionneur), qui transforme l'énergie électrique en énergie mécanique ;\n- **transmettre** : l'**arbre** du moteur, qui entraîne l'hélice.\n3. L'**action** : l'hélice tourne et **brasse l'air** (elle crée un courant d'air)."}$exo$::jsonb),
  ('7a86ab1e-0c46-5c92-9521-40dbe889788d'::uuid, 2, 'application', $exo${"titre":"Le store banne automatique","consigne":"Analyse la description et identifie chaque élément de la chaîne d'énergie.","enonce":"**Situation.** Un store banne se déroule automatiquement quand il y a du soleil.\n\n> Le store est alimenté par le réseau 230 V. Une carte électronique reçoit l'information d'un capteur de luminosité et commande un relais. Le relais alimente un moteur électrique placé dans le tube du store. Un réducteur à engrenages ralentit la rotation du moteur avant d'entraîner le tube, sur lequel s'enroule la toile.\n\n1. Réalise la chaîne d'énergie du store (fonction → composant).\n2. Comment appelle-t-on la famille de composants à laquelle appartient le moteur ?\n3. Où la chaîne d'information rejoint-elle la chaîne d'énergie ? Explique.\n4. Quelle est l'action produite ?","bareme":[{"critere":"Chaîne d'énergie complète et juste : réseau, relais, moteur, réducteur/tube","points":8},{"critere":"Moteur identifié comme actionneur","points":3},{"critere":"Jonction à la fonction distribuer : la carte commande le relais","points":6},{"critere":"Action : la toile se déroule / s'enroule","points":3}],"dureeMin":10,"corrige":"1. Chaîne d'énergie :\n- **alimenter** : le réseau 230 V ;\n- **distribuer** : le **relais** ;\n- **convertir** : le **moteur électrique** ;\n- **transmettre** : le **réducteur à engrenages** puis le **tube** d'enroulement.\n2. Le moteur est un **actionneur** : il convertit l'énergie électrique en énergie mécanique.\n3. Les deux chaînes se rejoignent à la fonction **distribuer** : la carte électronique (partie commande, chaîne d'information) décide à partir du capteur de luminosité et **envoie l'ordre au relais**, qui laisse alors passer le courant vers le moteur. La chaîne d'information **décide**, la chaîne d'énergie **agit**.\n4. Action : **la toile du store se déroule** (ou s'enroule)."}$exo$::jsonb),
  ('7a86ab1e-0c46-5c92-9521-40dbe889788d'::uuid, 3, 'application', $exo${"titre":"Diagnostiquer une barrière de parking","consigne":"Analyse le fonctionnement, puis raisonne sur la chaîne d'énergie pour localiser les pannes.","enonce":"**Situation.** La barrière du parking d'un collège fonctionne ainsi :\n\n> Un panneau solaire charge une batterie 24 V. Quand un badge est présenté, la carte de commande ferme un contact de relais. Le moteur tourne ; un réducteur à engrenages diminue sa vitesse et entraîne l'axe de la lisse, qui se lève.\n\n1. Réalise la chaîne d'énergie complète de la barrière.\n2. Explique le rôle du réducteur : que perd-on, que gagne-t-on ?\n3. Panne n° 1 : on entend le « clic » du relais mais le moteur ne tourne pas, et un voltmètre indique 0 V aux bornes de la batterie. Quelle fonction est défaillante ? Propose une cause.\n4. Panne n° 2 : le moteur tourne mais la lisse ne se lève pas. Quelle fonction est en cause ? Propose une cause.\n5. Panne n° 3 : aucun « clic » du relais au passage du badge, batterie chargée. Dans quelle chaîne chercher la panne ? Justifie.","bareme":[{"critere":"Chaîne d'énergie complète : panneau/batterie, relais, moteur, réducteur/axe, action","points":5},{"critere":"Réducteur : moins de vitesse, plus d'effort","points":3},{"critere":"Panne 1 : alimenter défaillante, cause plausible","points":4},{"critere":"Panne 2 : transmettre défaillante, cause plausible","points":4},{"critere":"Panne 3 : chaîne d'information (ordre non envoyé au distribuer), justifiée","points":4}],"dureeMin":18,"corrige":"1. **Alimenter** : panneau solaire + batterie 24 V → **distribuer** : relais → **convertir** : moteur électrique → **transmettre** : réducteur à engrenages et axe → **action** : la lisse se lève.\n2. Le réducteur **diminue la vitesse** de rotation et **augmente l'effort** (le couple) : le moteur tourne vite mais faiblement ; il faut lever la lisse lentement et avec force.\n3. Le relais commute (le « clic »), donc l'ordre arrive et la fonction distribuer réagit, mais il n'y a **aucune énergie** : 0 V à la batterie. La fonction **alimenter** est défaillante. Causes possibles : batterie déchargée ou hors d'usage, panneau solaire sale ou débranché, câble de liaison coupé.\n4. Le moteur tourne, donc alimenter, distribuer et convertir fonctionnent. C'est la fonction **transmettre** : engrenage cassé ou dents usées, axe désaccouplé du réducteur, clavette cassée.\n5. Le relais ne reçoit pas d'ordre alors que l'énergie est présente : la panne est dans la **chaîne d'information** (lecteur de badge qui n'acquiert pas, carte de commande ou programme défaillant, liaison carte-relais coupée). Les deux chaînes se rejoignent au relais : sans ordre de la partie commande, la fonction distribuer ne laisse rien passer."}$exo$::jsonb),
  ('59e215ec-618c-506c-8014-4642720b2b95'::uuid, 1, 'application', $exo${"titre":"Transmettre ou transformer ?","consigne":"Classe chaque mécanisme et justifie avec le vocabulaire du mouvement.","enonce":"**Situation.** Voici cinq mécanismes :\n\n- les pignons et la chaîne d'un vélo ;\n- le pignon-crémaillère d'un portail coulissant ;\n- la vis-écrou d'un étau ;\n- les engrenages d'une perceuse ;\n- la bielle-manivelle d'un moteur thermique.\n\n1. Quelle est la différence entre transmettre et transformer un mouvement ?\n2. Classe chaque mécanisme dans la bonne famille.\n3. Pour les mécanismes de transformation, indique le mouvement d'entrée et de sortie.","bareme":[{"critere":"Différence : transmettre conserve la nature du mouvement, transformer la change","points":5},{"critere":"Cinq mécanismes correctement classés","points":8},{"critere":"Mouvements d'entrée et de sortie justes pour les trois transformations","points":7}],"dureeMin":7,"corrige":"1. **Transmettre** change la **vitesse** et l'**effort** mais conserve la **nature** du mouvement (le plus souvent une rotation). **Transformer** change la **nature** du mouvement.\n2. **Transmission** : pignons-chaîne du vélo, engrenages de la perceuse. **Transformation** : pignon-crémaillère, vis-écrou, bielle-manivelle.\n3. Mouvements :\n- pignon-crémaillère : **rotation → translation** (le portail coulisse) ;\n- vis-écrou : **rotation → translation lente et puissante** (la mâchoire de l'étau avance) ;\n- bielle-manivelle : **translation alternative ↔ rotation** (les pistons font tourner le vilebrequin)."}$exo$::jsonb),
  ('59e215ec-618c-506c-8014-4642720b2b95'::uuid, 2, 'application', $exo${"titre":"Le rapport de transmission d'un mixeur","consigne":"Montre tous tes calculs et conclus avec le vocabulaire du cours.","enonce":"**Situation.** Dans un batteur de cuisine, le moteur entraîne une roue dentée de **12 dents** qui engrène sur une roue de **48 dents** reliée au fouet. Le moteur tourne à **2 400 tr/min**.\n\n1. Calcule le rapport de transmission r.\n2. Calcule la vitesse de rotation du fouet.\n3. Ce mécanisme est-il un réducteur ou un multiplicateur ? Qu'y gagne-t-on ?\n4. Le fouet tourne-t-il dans le même sens que le moteur ? Justifie.","bareme":[{"critere":"r = 12 ÷ 48 = 0,25 avec la bonne formule","points":6},{"critere":"Vitesse du fouet : 2 400 × 0,25 = 600 tr/min","points":6},{"critere":"Réducteur (r < 1) : moins de vitesse, plus de force","points":5},{"critere":"Sens inverse pour deux roues dentées en contact","points":3}],"dureeMin":10,"corrige":"1. r = dents de l'entrée ÷ dents de la sortie = 12 ÷ 48 = **0,25**.\n2. r = vitesse de sortie ÷ vitesse d'entrée, donc vitesse du fouet = 2 400 × 0,25 = **600 tr/min**.\n3. r = 0,25 < 1 : c'est un **réducteur**. On perd de la vitesse (quatre fois moins vite) mais on **gagne de la force** : le fouet peut mélanger une pâte épaisse sans que le moteur cale.\n4. Non : deux roues dentées en contact tournent **en sens inverse** l'une de l'autre (sauf roue intermédiaire ou engrenage intérieur)."}$exo$::jsonb),
  ('59e215ec-618c-506c-8014-4642720b2b95'::uuid, 3, 'application', $exo${"titre":"Les vitesses du vélo de Maëlle","consigne":"Calcule, compare les mécanismes puis argumente tes choix.","enonce":"**Situation.** Maëlle pédale à **60 tours par minute**. Son plateau (à l'avant, entrée) a **48 dents**. À l'arrière, elle peut choisir un pignon de **12 dents** ou de **32 dents**.\n\n1. Calcule le rapport de transmission et la vitesse de rotation de la roue arrière pour chacun des deux pignons.\n2. Quel pignon est un multiplicateur, lequel se rapproche le plus d'un réducteur ? Lequel choisir pour monter une côte ? Justifie.\n3. La roue arrière fait 2,1 m de tour. Calcule la distance parcourue en une minute avec le pignon de 12 dents, puis la vitesse en km/h.\n4. Pourquoi utilise-t-on une chaîne plutôt qu'une courroie ou des roues de friction sur un vélo ? Dans quel sens tournent plateau et pignon ?\n5. Le dérailleur ne change que la vitesse et l'effort. Est-ce un mécanisme de transmission ou de transformation ?","bareme":[{"critere":"Rapports justes (4 et 1,5) et vitesses de roue (240 et 90 tr/min)","points":6},{"critere":"Pignon de 32 dents pour la côte : moins de vitesse, plus de force, justifié","points":4},{"critere":"Distance 504 m par minute et vitesse ≈ 30 km/h","points":4},{"critere":"Chaîne : pas de glissement ; plateau et pignon tournent dans le même sens","points":4},{"critere":"Transmission : la nature du mouvement (rotation) est conservée","points":2}],"dureeMin":20,"corrige":"1. r = dents de l'entrée ÷ dents de la sortie.\n- Pignon de 12 dents : r = 48 ÷ 12 = **4** ; roue = 60 × 4 = **240 tr/min**.\n- Pignon de 32 dents : r = 48 ÷ 32 = **1,5** ; roue = 60 × 1,5 = **90 tr/min**.\n2. Les deux ont r > 1 : ce sont des **multiplicateurs**, mais celui de **32 dents** multiplie beaucoup moins (1,5) : il est le plus proche d'un réducteur. Pour monter une côte, on choisit le **grand pignon de 32 dents** : la roue tourne moins vite, mais l'effort demandé aux jambes est plus faible (on gagne de la force). Un grand pignon entraîné par un plus petit tourne moins vite mais plus fort.\n3. Distance en une minute : 240 × 2,1 = **504 m**. En une heure : 504 × 60 = 30 240 m, soit environ **30 km/h**.\n4. La **chaîne** ne **glisse pas** (contrairement à une courroie ou à des roues de friction qui patinent) et transmet de gros efforts. Avec une chaîne, plateau et pignon tournent dans le **même sens**.\n5. C'est une **transmission** : le mouvement reste une **rotation** ; seules la vitesse et l'effort changent."}$exo$::jsonb),
  ('13fbc7bc-9096-5495-800c-24e7bd6c5480'::uuid, 1, 'application', $exo${"titre":"Les familles de matériaux","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite les **quatre familles** de matériaux et donne un exemple pour chacune.\n2. À quelle famille appartiennent : le verre, le laiton, le contreplaqué, le cuir ?\n3. Définis la **dureté**, l'**élasticité** et la **masse volumique**.\n4. Qu'est-ce qu'un matériau **composite** ?","bareme":[{"critere":"Quatre familles nommées avec un exemple juste chacune","points":6},{"critere":"Classement correct des quatre matériaux proposés","points":5},{"critere":"Définitions exactes de la dureté, de l'élasticité et de la masse volumique","points":6},{"critere":"Définition du composite : il cumule les qualités de deux matériaux","points":3}],"dureeMin":7,"corrige":"1. **Métalliques** (acier, aluminium, cuivre), **organiques** (plastiques, bois, papier), **céramiques** (verre, porcelaine, béton), **composites** (fibre de carbone, béton armé, contreplaqué).\n2. Le verre : **céramique** ; le laiton : **métallique** ; le contreplaqué : **composite** ; le cuir : **organique**.\n3. La **dureté** est la résistance à la rayure. L'**élasticité** est la capacité à reprendre sa forme après une déformation. La **masse volumique** est la masse par unité de volume : elle décide de la légèreté d'une pièce.\n4. Un composite associe **deux matériaux** pour **cumuler leurs qualités** (par exemple le béton armé : le béton résiste à la compression, l'acier à la traction)."}$exo$::jsonb),
  ('13fbc7bc-9096-5495-800c-24e7bd6c5480'::uuid, 2, 'application', $exo${"titre":"Le cadre de trottinette","consigne":"Lis la situation et le tableau, puis réponds en justifiant chaque choix avec les propriétés vues en cours.","enonce":"**Situation.** L'entreprise de Nora conçoit une trottinette. Le cahier des charges du cadre impose : **léger**, **résistant** aux efforts, **résistant à la corrosion** (usage sous la pluie) et **recyclable**.\n\n| Matériau | Masse volumique | Résistance mécanique | Corrosion | Recyclage |\n|---|---|---|---|---|\n| Acier ordinaire | 7,8 g/cm³ | Très bonne | Rouille | Bon |\n| Aluminium | 2,7 g/cm³ | Bonne | Résiste bien | Presque indéfini |\n| Plastique ABS | 1,05 g/cm³ | Faible | Résiste bien | Médiocre |\n\n1. Pour chaque matériau, indique quelle exigence du cahier des charges il ne respecte pas bien.\n2. Quel matériau choisis-tu ? Justifie.\n3. Propose deux procédés de fabrication adaptés à ce matériau pour réaliser le cadre.","bareme":[{"critere":"Point faible de chaque matériau identifié à partir du tableau","points":6},{"critere":"Choix de l'aluminium justifié par son profil de propriétés","points":8},{"critere":"Deux procédés adaptés aux métaux (pliage, soudage, usinage, découpe laser, moulage)","points":6}],"dureeMin":10,"corrige":"1. **Acier** : trop lourd (7,8 g/cm³) et il **rouille**. **Aluminium** : résistance un peu moins bonne que l'acier, mais suffisante. **ABS** : **résistance mécanique faible** et **recyclage médiocre**.\n2. On choisit l'**aluminium** : il est **léger** (2,7 g/cm³, presque trois fois moins que l'acier), sa résistance est **bonne**, il **résiste à la corrosion** et se **recycle presque indéfiniment**. Ce n'est pas « le meilleur matériau » en tout : c'est celui dont le **profil de propriétés** correspond au cahier des charges.\n3. Procédés des métaux : **découpe laser** ou **usinage** des pièces, **pliage** des tubes, **soudage** des éléments du cadre (ou **moulage** de certaines pièces)."}$exo$::jsonb),
  ('13fbc7bc-9096-5495-800c-24e7bd6c5480'::uuid, 3, 'application', $exo${"titre":"Une coque de téléphone responsable","consigne":"Analyse les documents, puis rédige des réponses argumentées. Chaque choix doit être justifié par les propriétés, le procédé et l'impact environnemental.","enonce":"**Situation.** Une start-up veut fabriquer **cent mille** coques de téléphone. Trois solutions sont proposées.\n\n| Solution | Matériau | Atouts | Limites |\n|---|---|---|---|\n| A | Thermoplastique recyclé | Léger, mise en forme facile, peu cher en série | Moins rigide |\n| B | Aluminium | Rigide, recyclable presque indéfiniment | Très cher à produire, conduit la chaleur, plus lourd |\n| C | Composite fibre de carbone + résine | Très léger et très rigide | Quasi impossible à séparer pour le recyclage, cher |\n\n**Contraintes du cahier des charges** : masse inférieure à 30 g, amortir les chocs, prix de revient bas, fin de vie maîtrisée.\n\n1. Classe chaque matériau dans sa famille.\n2. Pour chaque solution, indique le procédé de fabrication le plus adapté parmi : injection, usinage, moulage de composite, et justifie.\n3. Compare les trois solutions au regard du cahier des charges (tu peux construire un tableau).\n4. Quelle solution recommandes-tu ? Rédige un paragraphe argumenté qui tient compte de l'impact environnemental.","bareme":[{"critere":"Familles correctes : organique, métallique, composite","points":3},{"critere":"Procédés adaptés et justifiés (injection pour le thermoplastique, usinage pour l'aluminium)","points":5},{"critere":"Comparaison des trois solutions sur chaque contrainte","points":6},{"critere":"Recommandation argumentée intégrant l'impact environnemental","points":6}],"dureeMin":18,"corrige":"1. Thermoplastique : **organique** ; aluminium : **métallique** ; fibre de carbone + résine : **composite**.\n2. A : **injection** plastique, procédé des thermoplastiques, très rentable pour cent mille pièces identiques. B : **usinage** (ou moulage) de l'aluminium, procédés des métaux, plus long et coûteux. C : **moulage** du composite, lent et cher.\n3. Comparaison attendue :\n\n| Contrainte | A | B | C |\n|---|---|---|---|\n| Masse | Légère | Plus lourde | Très légère |\n| Chocs | Amortit (souple) | Rigide, transmet le choc | Rigide |\n| Prix en série | Bas | Élevé | Élevé |\n| Fin de vie | Matière déjà recyclée | Recyclable presque indéfiniment, mais production très énergivore | Quasi impossible à recycler |\n\n4. Recommandation attendue : la **solution A**. Elle respecte la masse, sa relative souplesse **amortit les chocs**, l'**injection** la rend peu chère en grande série, et l'emploi d'un plastique **recyclé** limite l'impact. L'aluminium se recycle très bien mais coûte cher et beaucoup d'énergie à produire ; le composite cumule rigidité et légèreté mais sa **fin de vie** n'est pas maîtrisée. On ne choisit pas le meilleur matériau dans l'absolu, mais celui qui répond aux contraintes au meilleur coût. (Une recommandation différente est acceptée si elle est cohérente et justifiée.)"}$exo$::jsonb),
  ('8be61738-19b7-522f-85ab-5ddfb449c327'::uuid, 1, 'application', $exo${"titre":"Acquérir, traiter, communiquer","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Nomme les **trois fonctions** de la chaîne d'information et donne le rôle de chacune.\n2. Range ces composants selon leur fonction : bouton-poussoir, écran, microcontrôleur, capteur à ultrasons, module Bluetooth, photorésistance.\n3. Quelle est la différence entre un **capteur** et un **actionneur** ? À quelle chaîne appartient chacun ?","bareme":[{"critere":"Trois fonctions nommées avec leur rôle","points":6},{"critere":"Classement correct des six composants","points":8},{"critere":"Différence capteur / actionneur et chaîne de chacun","points":6}],"dureeMin":6,"corrige":"1. **Acquérir** : recueillir une information sur l'environnement ou le système. **Traiter** : décider quoi faire de l'information (partie commande qui exécute un programme). **Communiquer** : transmettre l'information à l'utilisateur ou à un autre système.\n2. Acquérir : **bouton-poussoir, capteur à ultrasons, photorésistance**. Traiter : **microcontrôleur**. Communiquer : **écran, module Bluetooth**.\n3. Le **capteur** prend une information ; il appartient à la **chaîne d'information**. L'**actionneur** produit une action (moteur, vérin, lampe) ; il appartient à la **chaîne d'énergie**."}$exo$::jsonb),
  ('8be61738-19b7-522f-85ab-5ddfb449c327'::uuid, 2, 'application', $exo${"titre":"Le portail automatique de la famille Diallo","consigne":"Lis la description du système, puis réponds aux questions en justifiant avec le vocabulaire du cours.","enonce":"**Description.** Le portail des Diallo s'ouvre quand on appuie sur une **télécommande radio**. Une carte à **microcontrôleur** reçoit l'ordre et commande le **moteur**. Un **capteur de fin de course** détecte que le portail est complètement ouvert. Un **capteur infrarouge** détecte un obstacle pendant la fermeture. Un **gyrophare** clignote pendant le mouvement.\n\n1. Pour chaque élément souligné en gras, indique s'il relève de la chaîne d'information (et de quelle fonction) ou de la chaîne d'énergie.\n2. Décris dans l'ordre ce qui se passe quand une voiture passe devant le capteur infrarouge pendant la fermeture.\n3. Explique comment l'ordre du microcontrôleur arrive jusqu'au moteur (lien entre les deux chaînes).","bareme":[{"critere":"Six éléments correctement classés (chaîne et fonction)","points":8},{"critere":"Scénario de détection d'obstacle ordonné : acquérir, traiter, agir","points":7},{"critere":"Lien avec la fonction distribuer de la chaîne d'énergie","points":5}],"dureeMin":10,"corrige":"1. Télécommande radio : chaîne d'information, **acquérir** l'action de l'utilisateur (et la transmission radio relève de communiquer). Microcontrôleur : **traiter**. Moteur : **chaîne d'énergie** (actionneur). Capteur de fin de course : **acquérir**. Capteur infrarouge : **acquérir**. Gyrophare : **communiquer** (il informe les personnes autour).\n2. Le capteur infrarouge **acquiert** la présence de l'obstacle ; il envoie l'information au **microcontrôleur**, qui **traite** : son programme décide d'arrêter (ou de rouvrir) le portail ; il envoie l'ordre à la chaîne d'énergie qui **arrête le moteur**. Le gyrophare continue de signaler.\n3. La chaîne d'information **décide**, la chaîne d'énergie **agit** : l'ordre du microcontrôleur arrive à la fonction **distribuer** de la chaîne d'énergie, qui laisse alors passer le courant vers le moteur (ou le coupe)."}$exo$::jsonb),
  ('8be61738-19b7-522f-85ab-5ddfb449c327'::uuid, 3, 'application', $exo${"titre":"Un thermostat connecté sous la loupe","consigne":"Analyse le document, puis réponds en argumentant. Utilise précisément le vocabulaire des chaînes d'information et d'énergie.","enonce":"**Document : notice d'un thermostat connecté.**\n\n> Le boîtier mesure la température de la pièce grâce à une thermistance. Si la température descend sous la consigne, il envoie l'ordre d'allumer la chaudière. L'écran affiche la température et la consigne. Grâce au Wi-Fi, l'application du téléphone permet de changer la consigne à distance et envoie chaque heure les relevés sur un serveur du fabricant.\n\n1. Construis le schéma de la chaîne d'information du thermostat (trois fonctions, composant de chacune).\n2. La chaudière appartient-elle à la chaîne d'information ? Justifie.\n3. Écris en pseudo-code simple la décision prise par le thermostat (condition et deux actions).\n4. Le Wi-Fi apporte une nouvelle fonction. Laquelle ? Explique deux risques qu'elle crée et propose une réponse pour chacun.","bareme":[{"critere":"Chaîne d'information complète : thermistance, microcontrôleur, écran et Wi-Fi","points":6},{"critere":"Chaudière dans la chaîne d'énergie, justifiée par décider / agir","points":3},{"critere":"Pseudo-code cohérent avec condition et deux actions","points":4},{"critere":"Fonction de l'objet connecté et deux risques (piratage, données personnelles) avec parades","points":7}],"dureeMin":16,"corrige":"1. **Acquérir** : la thermistance (capteur de température) ; les ordres reçus par Wi-Fi depuis l'application. **Traiter** : le microcontrôleur, qui compare la température à la consigne selon son programme. **Communiquer** : l'écran (vers l'utilisateur), le Wi-Fi (vers le téléphone et le serveur), et l'ordre transmis à la chaudière.\n2. Non : la chaudière **produit une action** (chauffer). Elle relève de la **chaîne d'énergie** ; la chaîne d'information **décide**, la chaîne d'énergie **agit**.\n3. Exemple :\n\n> SI température < consigne ALORS allumer la chaudière SINON éteindre la chaudière\n\n4. Le Wi-Fi fait du thermostat un **objet connecté** : il envoie ses données vers un serveur ou un téléphone et **reçoit des ordres à distance**. Risques : le **piratage** (quelqu'un prend la main sur le chauffage) — réponse : mot de passe solide, mises à jour ; les **données personnelles** (les relevés révèlent quand la maison est vide) — réponse : limiter les données envoyées, choisir un fabricant qui garantit leur protection et leur sécurité."}$exo$::jsonb),
  ('f2d23327-4a38-5e91-b496-2a1e36b29d97'::uuid, 1, 'application', $exo${"titre":"Les quatre familles de procédés","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Nomme les **quatre familles** de procédés de fabrication et donne leur principe.\n2. Classe ces procédés : perçage, pliage, impression 3D, rivetage, emboutissage, découpe laser, vissage.\n3. Donne un atout et une limite de la fabrication par **enlèvement de matière**.","bareme":[{"critere":"Quatre familles nommées avec leur principe","points":6},{"critere":"Classement correct des sept procédés","points":9},{"critere":"Atout (précision, toutes matières) et limite (copeaux perdus) de l'enlèvement","points":5}],"dureeMin":6,"corrige":"1. Par **enlèvement** : on retire ce qui est en trop. Par **déformation** : la matière change de forme. Par **ajout** : on construit couche par couche. Par **assemblage** : on réunit des pièces.\n2. Enlèvement : **perçage, découpe laser**. Déformation : **pliage, emboutissage**. Ajout : **impression 3D**. Assemblage : **rivetage, vissage**.\n3. Atout : c'est **précis** et cela fonctionne sur toutes les matières. Limite : la matière retirée part en **copeaux perdus**."}$exo$::jsonb),
  ('f2d23327-4a38-5e91-b496-2a1e36b29d97'::uuid, 2, 'application', $exo${"titre":"Du prototype à la série","consigne":"Lis la situation, puis réponds en justifiant chaque choix de procédé.","enonce":"**Situation.** Le club de robotique d'Inès a dessiné un **support de capteur** en plastique, de forme complexe. Il en faut d'abord **un seul** pour essayer. Si l'essai réussit, un fabricant en produira **cent mille** pour un kit vendu dans les collèges.\n\n1. Quel procédé choisir pour la pièce unique ? Justifie.\n2. Quel procédé choisir pour les cent mille pièces ? Justifie.\n3. Quel critère est décisif dans ces deux choix ?\n4. Le support se fixe sur le robot. Faut-il un assemblage démontable ou non démontable ? Justifie en pensant à la réparation.","bareme":[{"critere":"Impression 3D pour la pièce unique, justifiée (prototype, forme complexe)","points":5},{"critere":"Injection plastique pour la série, justifiée (rapide, rentable en série)","points":5},{"critere":"La quantité identifiée comme critère décisif","points":4},{"critere":"Assemblage démontable (vis, clips) justifié par la réparation et le recyclage","points":6}],"dureeMin":10,"corrige":"1. **Impression 3D** (fabrication par ajout) : idéale pour un **prototype** unique et pour les **formes complexes**, sans outillage coûteux.\n2. **Injection plastique** : une fois le moule payé, elle produit très vite des pièces identiques ; c'est le procédé adapté à cent mille pièces (l'impression 3D serait trop **lente en série**).\n3. La **quantité** : un prototype et une série n'appellent presque jamais le même procédé.\n4. Un assemblage **démontable** (vis, clips) : on peut **remplacer** le support ou le capteur en cas de casse, **réparer** le robot et **recycler** séparément les pièces. Un collage ou un rivetage serait définitif."}$exo$::jsonb),
  ('f2d23327-4a38-5e91-b496-2a1e36b29d97'::uuid, 3, 'application', $exo${"titre":"Fabriquer une boîte à outils métallique","consigne":"Analyse la situation, puis réponds de façon argumentée en mobilisant les familles de procédés, les machines à commande numérique et les critères de choix.","enonce":"**Situation.** Une petite entreprise fabrique des boîtes à outils en tôle d'acier. Chaque boîte comporte : un **fond** (plaque pliée en U), deux **côtés** percés, une **poignée** et deux **charnières**. L'entreprise produit **2 000 boîtes par an** et possède une découpeuse laser à commande numérique, une presse plieuse et un poste de soudage.\n\n1. Propose une suite d'opérations pour fabriquer le fond et un côté, en nommant pour chacune sa famille de procédé.\n2. Pour assembler les côtés au fond, compare le soudage et le vissage (au moins deux critères).\n3. Quel est l'intérêt d'utiliser une machine à commande numérique pour la découpe ? Cite deux garanties.\n4. Un client demande une seule boîte au couvercle en forme de logo très complexe. L'entreprise doit-elle changer de procédé pour ce couvercle ? Discute.","bareme":[{"critere":"Suite d'opérations cohérente avec la famille de chaque procédé","points":6},{"critere":"Comparaison soudage / vissage sur au moins deux critères","points":5},{"critere":"Intérêt de la MOCN : répétabilité et précision","points":4},{"critere":"Discussion sur la pièce unique complexe : quantité, forme, coût, matériau","points":5}],"dureeMin":18,"corrige":"1. Exemple : **découpe laser** de la tôle aux dimensions (enlèvement) → **perçage** des trous des côtés (enlèvement ; ils peuvent aussi être découpés au laser) → **pliage** du fond en U à la presse plieuse (déformation, aucune perte de matière) → **assemblage** avec les côtés.\n2. **Soudage** : non démontable, très **résistant** et étanche, mais **définitif** : impossible de remplacer un côté abîmé ou de séparer les pièces. **Vissage** : **démontable**, permet de **réparer** et de recycler, mais un peu moins rigide et demande des perçages et des vis (plus de pièces). Pour une boîte à outils, on peut accepter l'un ou l'autre si le choix est justifié.\n3. La MOCN exécute un programme issu du dessin numérique : elle garantit la **répétabilité** (des pièces identiques, 2 000 boîtes semblables) et la **précision** (au dixième de millimètre).\n4. Pour une pièce **unique** à **forme complexe**, l'outillage de série serait trop coûteux. La découpe laser à commande numérique suit n'importe quel contour dessiné : elle convient pour découper le logo dans la tôle d'acier, sans changer de procédé. L'impression 3D, idéale pour une pièce unique complexe, obligerait à changer de **matériau** (plastique). La conclusion doit relier le choix à la **quantité**, à la **forme**, au **matériau** et au **coût**."}$exo$::jsonb),
  ('24d4550c-4cce-5380-9671-bbd1cb3f038b'::uuid, 1, 'application', $exo${"titre":"Les EPI et les pictogrammes","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Que signifie **EPI** ? Cite quatre EPI de l'atelier et une situation où l'on porte chacun.\n2. Pourquoi ne porte-t-on **jamais** de gants près d'une pièce en rotation ?\n3. Donne la signification de chaque forme : triangle jaune, rond bleu, rond rouge barré, carré vert.","bareme":[{"critere":"Sigle EPI expliqué, quatre équipements avec une situation juste","points":8},{"critere":"Risque d'être happé par la pièce en rotation","points":4},{"critere":"Signification exacte des quatre pictogrammes","points":8}],"dureeMin":6,"corrige":"1. **Équipements de protection individuelle**. Exemples : les **lunettes** (perçage, sciage, meulage : tout ce qui projette) ; les **gants** (pièces coupantes ou chaudes) ; la **blouse** et des vêtements ajustés (toujours) ; les **chaussures fermées** (toujours, contre la chute d'objets) ; la **protection auditive** (bruit prolongé).\n2. Parce que le gant peut être **happé** par la pièce qui tourne, entraînant la main.\n3. **Triangle jaune** : un **danger** (électrique, laser, matière chaude). **Rond bleu** : une **obligation** (porter des lunettes). **Rond rouge barré** : une **interdiction**. **Carré vert** : une information de **secours** (issue, trousse de premiers soins)."}$exo$::jsonb),
  ('24d4550c-4cce-5380-9671-bbd1cb3f038b'::uuid, 2, 'application', $exo${"titre":"Ce qui cloche à la perceuse","consigne":"Lis la scène, repère les erreurs, puis corrige-les en expliquant la raison de chaque règle.","enonce":"**Scène.** Au fond de l'atelier, Hugo s'installe à la perceuse à colonne, sans avoir demandé l'autorisation. Il porte une écharpe et des gants épais, mais pas de lunettes. Il a laissé le carter de protection ouvert « pour mieux voir ». Pendant que le foret tourne, il enlève un copeau avec les doigts. Son ami Sami se penche à côté de lui pour lui parler. Aucun des deux ne sait où se trouve le bouton d'arrêt d'urgence.\n\n1. Relève au moins **six** erreurs dans cette scène.\n2. Pour chacune, écris la règle correcte et sa raison.\n3. Quelle est, selon le cours, l'erreur à l'origine de la grande majorité des accidents d'atelier ?","bareme":[{"critere":"Au moins six erreurs correctement relevées","points":8},{"critere":"Règle correcte et raison pour chaque erreur","points":9},{"critere":"Intervention sur une machine qui tourne encore identifiée","points":3}],"dureeMin":10,"corrige":"1 et 2. Erreurs et règles :\n- **Pas d'autorisation** → ne jamais utiliser une machine sans autorisation : la consigne précède le geste.\n- **Écharpe** → vêtements ajustés, aucune écharpe ni bijou, cheveux attachés : ils peuvent être entraînés.\n- **Gants près du foret qui tourne** → jamais de gants près d'une pièce en rotation : ils peuvent être happés.\n- **Pas de lunettes** → lunettes obligatoires au perçage, qui projette des copeaux.\n- **Carter ouvert** → vérifier les carters avant de démarrer : ils protègent des pièces mobiles.\n- **Copeau enlevé pendant la rotation** → tout réglage ou nettoyage se fait machine à l'arrêt complet.\n- **Sami qui parle à Hugo** → un opérateur à la fois, ne jamais distraire celui qui travaille.\n- **Arrêt d'urgence inconnu** → savoir où il se trouve **avant** de démarrer : le chercher pendant l'incident est trop tard.\n3. La grande majorité des accidents vient d'un seul geste : **intervenir sur une machine qui tourne encore** (régler ou nettoyer sans l'arrêt complet)."}$exo$::jsonb),
  ('24d4550c-4cce-5380-9671-bbd1cb3f038b'::uuid, 3, 'application', $exo${"titre":"Rédiger la fiche sécurité du poste de découpe","consigne":"Rédige une fiche de sécurité complète et justifiée, en mobilisant les EPI, les règles de conduite, les pictogrammes et l'arrêt d'urgence.","enonce":"**Situation.** Le collège reçoit une **scie à ruban** pour découper du bois et du plastique. Le professeur demande à ta classe d'écrire la fiche de sécurité affichée à côté de la machine. Données sur la machine : lame en mouvement rapide, projection de sciure, bruit important lors des longues découpes, alimentation électrique 230 V, bouton d'arrêt d'urgence rouge sur fond jaune situé sur le côté gauche.\n\n1. Identifie **trois dangers** de cette machine et associe à chacun le pictogramme qui convient (forme et couleur).\n2. Liste les **EPI** et les tenues obligatoires ou interdits, en justifiant chacun.\n3. Rédige **cinq règles de conduite** numérotées, dans l'ordre d'utilisation (avant, pendant, après), chacune avec sa raison.\n4. Explique en deux ou trois phrases le rôle de l'arrêt d'urgence et pourquoi il faut le repérer avant de démarrer.","bareme":[{"critere":"Trois dangers identifiés avec le pictogramme adapté (triangle jaune, rond bleu, rond rouge barré)","points":5},{"critere":"EPI et tenue justifiés, gants proscrits près de la lame en mouvement","points":5},{"critere":"Cinq règles ordonnées avant / pendant / après, chacune justifiée","points":6},{"critere":"Rôle et repérage de l'arrêt d'urgence expliqués","points":4}],"dureeMin":18,"corrige":"1. Dangers : la **lame en mouvement** (coupure) → triangle jaune de danger ; les **projections de sciure** → rond bleu d'obligation « port des lunettes » ; le **bruit** → rond bleu « protection auditive » ; le **risque électrique** → triangle jaune ; on peut ajouter un rond rouge barré « interdit de porter des gants près de la lame en mouvement ».\n2. **Lunettes** (projections), **protection auditive** pour les longues découpes (bruit prolongé), **blouse** et vêtements ajustés, **cheveux attachés**, **aucun bijou ni écharpe** (entraînement), **chaussures fermées** (chute d'objet). **Pas de gants** près de la lame en mouvement : ils peuvent être happés.\n3. Exemple : (avant) 1. Obtenir l'**autorisation** du professeur : la consigne précède le geste. 2. Vérifier que les **carters** et protections sont en place et repérer l'**arrêt d'urgence**. (pendant) 3. **Un seul opérateur**, personne ne le distrait. 4. Pousser la pièce sans approcher les doigts de la lame ; ne jamais retirer une chute tant que la lame tourne. (après) 5. Attendre l'**arrêt complet** avant tout réglage ou nettoyage, **ranger** le poste et **signaler** toute anomalie (bruit inhabituel, câble abîmé).\n4. Le bouton d'arrêt d'urgence, rouge sur fond jaune, **coupe l'alimentation immédiatement**. Il faut savoir où il se trouve **avant** de démarrer, car le chercher pendant un incident fait perdre des secondes décisives : c'est déjà trop tard."}$exo$::jsonb),
  ('6beaa39b-0ba6-5305-9e5d-b5be53c8da7c'::uuid, 1, 'application', $exo${"titre":"Les quatre structures d'un algorithme","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Quelle est la différence entre un **algorithme** et un **programme** ?\n2. Nomme les **quatre structures fondamentales** et donne un exemple pour chacune.\n3. Quelle est la différence entre une boucle **bornée** et une boucle **non bornée** ?\n4. Dans un organigramme, que représentent un losange et un rectangle ?","bareme":[{"critere":"Algorithme (suite d'instructions) et programme (traduction dans un langage) distingués","points":4},{"critere":"Quatre structures nommées avec un exemple juste","points":8},{"critere":"Boucle bornée / non bornée distinguées","points":4},{"critere":"Losange = test, rectangle = action","points":4}],"dureeMin":6,"corrige":"1. Un **algorithme** est une suite d'instructions permettant d'obtenir un résultat ; un **programme** en est la traduction dans un langage compris par la machine.\n2. La **séquence** : les instructions s'exécutent l'une après l'autre. La **condition** : un bloc s'exécute seulement si un test est vrai (si température > 25, allumer le ventilateur, sinon l'éteindre). La **boucle** : on répète des instructions (répéter 10 fois). La **variable** : une case mémoire nommée qui stocke une valeur (un compteur, un score).\n3. Pour une boucle **bornée**, on connaît d'avance le **nombre de tours** ; pour une boucle **non bornée**, on répète **tant qu'**une condition est vraie (tant que le bouton n'est pas appuyé).\n4. Le **losange** représente un **test**, le **rectangle** une **action** ; des flèches montrent l'enchaînement."}$exo$::jsonb),
  ('6beaa39b-0ba6-5305-9e5d-b5be53c8da7c'::uuid, 2, 'application', $exo${"titre":"La lampe de chevet intelligente","consigne":"Lis le cahier des charges, puis écris l'algorithme demandé en pseudo-code et réponds aux questions.","enonce":"**Situation.** Lucie programme une lampe de chevet. Elle dispose d'un **capteur de lumière** (valeur de 0 à 100) et d'un **capteur de présence**. La lampe doit s'allumer **si** la pièce est sombre (lumière < 30) **et** si quelqu'un est présent ; sinon elle doit s'éteindre. Le programme vérifie cela en permanence.\n\n1. Identifie les **entrées** et la **sortie** du système.\n2. Quel opérateur logique faut-il utiliser ? Justifie.\n3. Écris l'algorithme en pseudo-code, avec une boucle et une condition.\n4. La boucle utilisée est-elle bornée ou non bornée ?","bareme":[{"critere":"Entrées (deux capteurs) et sortie (lampe) identifiées","points":4},{"critere":"Opérateur « et » justifié : les deux conditions doivent être vraies","points":4},{"critere":"Pseudo-code correct : boucle, condition avec sinon, indentation","points":9},{"critere":"Boucle non bornée (répéter indéfiniment) identifiée","points":3}],"dureeMin":10,"corrige":"1. **Entrées** : le capteur de lumière et le capteur de présence (le programme les **lit**). **Sortie** : la lampe (le programme la **commande**).\n2. L'opérateur **et** : la lampe ne s'allume que si les **deux** conditions sont vraies en même temps (sombre **et** quelqu'un présent).\n3. Pseudo-code attendu :\n\n> RÉPÉTER indéfiniment\n>   lumiere ← lire capteur de lumière\n>   presence ← lire capteur de présence\n>   SI lumiere < 30 ET presence = vrai ALORS\n>     allumer la lampe\n>   SINON\n>     éteindre la lampe\n>   FIN SI\n> FIN RÉPÉTER\n\n4. C'est une boucle **non bornée** : on ne connaît pas d'avance le nombre de tours, elle tourne tant que la lampe est alimentée."}$exo$::jsonb),
  ('6beaa39b-0ba6-5305-9e5d-b5be53c8da7c'::uuid, 3, 'application', $exo${"titre":"Le compteur de visiteurs du CDI","consigne":"Analyse l'algorithme proposé, repère ses défauts, puis écris une version corrigée et justifie chaque modification.","enonce":"**Situation.** Au CDI, un capteur détecte chaque personne qui entre. Quand **30 personnes** sont présentes, une LED rouge s'allume pour signaler que la salle est pleine. Un bouton permet à la documentaliste de remettre le compteur à zéro. Yasmine a écrit cet algorithme :\n\n> RÉPÉTER indéfiniment\n>   SI capteur détecte quelqu'un ALORS\n>     compteur ← 1\n>   FIN SI\n>   SI compteur > 30 ALORS\n>     allumer la LED rouge\n>   FIN SI\n> FIN RÉPÉTER\n\n1. Quel est le rôle de la variable **compteur** ? Quelle valeur doit-elle avoir au départ, et où faut-il l'écrire ?\n2. Repère **deux erreurs** dans l'algorithme de Yasmine et explique leurs conséquences.\n3. Écris l'algorithme corrigé, qui gère aussi le bouton de remise à zéro (qui éteint la LED).\n4. Yasmine propose d'écrire « TANT QUE compteur < 30 : attendre ». Pourquoi cette boucle pourrait-elle devenir une **boucle infinie** si personne n'entre plus ?","bareme":[{"critere":"Rôle de la variable compteur et initialisation à 0 avant la boucle","points":4},{"critere":"Deux erreurs repérées : affectation au lieu d'incrémentation, > au lieu de ≥","points":5},{"critere":"Algorithme corrigé complet avec remise à zéro et extinction de la LED","points":7},{"critere":"Explication de la boucle infinie : condition d'arrêt jamais atteinte","points":4}],"dureeMin":18,"corrige":"1. **compteur** stocke le **nombre de personnes** entrées. Il doit valoir **0** au départ, et cette initialisation s'écrit **avant** la boucle (sinon il serait remis à zéro à chaque tour).\n2. Erreur 1 : « compteur ← 1 » **remet** la valeur à 1 au lieu de l'**augmenter** : le compteur ne dépasse jamais 1 et la LED ne s'allume jamais. Il faut **compteur ← compteur + 1**. Erreur 2 : « compteur > 30 » n'allume la LED qu'à **31** personnes ; il faut **compteur ≥ 30** (ou = 30).\n3. Algorithme corrigé :\n\n> compteur ← 0\n> RÉPÉTER indéfiniment\n>   SI capteur détecte quelqu'un ALORS\n>     compteur ← compteur + 1\n>   FIN SI\n>   SI compteur ≥ 30 ALORS\n>     allumer la LED rouge\n>   FIN SI\n>   SI bouton appuyé ALORS\n>     compteur ← 0\n>     éteindre la LED rouge\n>   FIN SI\n> FIN RÉPÉTER\n\n4. Dans une boucle « tant que », si la condition ne devient **jamais fausse**, la boucle **ne s'arrête jamais**. Si le compteur n'est pas mis à jour à l'intérieur de cette boucle (ou si personne n'entre), compteur reste inférieur à 30 : c'est la **boucle infinie**, qui bloque aussi la lecture du bouton."}$exo$::jsonb),
  ('830977f6-bd57-5ceb-bd17-11b717331c02'::uuid, 1, 'application', $exo${"titre":"Blocs ou lignes de code","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite deux environnements de **programmation graphique** et deux langages de **programmation textuelle**.\n2. Pourquoi ne peut-on pas faire de faute de syntaxe en programmation par blocs ?\n3. Donne deux avantages de la programmation textuelle.\n4. En Python, quel est le rôle du **deux-points** et celui de l'**indentation** ?","bareme":[{"critere":"Deux environnements graphiques et deux langages textuels justes","points":4},{"critere":"Absence de faute de syntaxe expliquée : les blocs incompatibles ne s'emboîtent pas","points":4},{"critere":"Deux avantages du texte : programmes longs, partage facile","points":5},{"critere":"Rôle du deux-points et de l'indentation en Python","points":7}],"dureeMin":6,"corrige":"1. Graphique : **Scratch, mBlock, Blockly, Snap!** Textuelle : **Python, JavaScript, C, C++ (Arduino)**.\n2. Parce que les **blocs incompatibles ne s'emboîtent pas** : l'environnement empêche d'assembler une instruction mal formée.\n3. Elle convient aux **programmes longs** (sans limite de taille) et le code est **facile à copier, comparer, versionner et partager**.\n4. Le **deux-points** termine la ligne qui **ouvre un bloc** (condition, boucle, fonction). L'**indentation** indique les instructions qui **appartiennent** au bloc ; elle fait partie du langage."}$exo$::jsonb),
  ('830977f6-bd57-5ceb-bd17-11b717331c02'::uuid, 2, 'application', $exo${"titre":"Traduire un script Scratch en Python","consigne":"Lis le script en blocs, puis réponds aux questions. Écris le code Python avec soin : chaque caractère compte.","enonce":"**Script Scratch de Théo** (pour un capteur de température) :\n\n> si température > 25 alors\n>   allumer ventilateur\n> sinon\n>   éteindre ventilateur\n\n1. Quelle structure algorithmique ce script utilise-t-il ?\n2. Traduis ce script en Python. On suppose que les instructions s'écrivent allumer_ventilateur() et eteindre_ventilateur().\n3. Théo a écrit en Python la version suivante, qui ne démarre pas :\n\n> if temperature > 25\n> allumer_ventilateur()\n> else:\n>     eteindre_ventilateur()\n\nRepère les deux erreurs et explique pourquoi elles bloquent le programme.\n4. Le passage des blocs au texte a-t-il changé l'algorithme ? Justifie.","bareme":[{"critere":"Structure conditionnelle (si … alors … sinon) identifiée","points":3},{"critere":"Traduction Python correcte : if, deux-points, indentation, else","points":7},{"critere":"Deux erreurs repérées : deux-points manquant, indentation absente","points":6},{"critere":"Seule l'écriture change, pas l'algorithme","points":4}],"dureeMin":10,"corrige":"1. Une **condition** : si … alors … sinon.\n2. Traduction attendue :\n\n> if temperature > 25:\n>     allumer_ventilateur()\n> else:\n>     eteindre_ventilateur()\n\n3. Erreur 1 : il manque le **deux-points** à la fin de la ligne « if temperature > 25 », qui ouvre un bloc. Erreur 2 : la ligne « allumer_ventilateur() » n'est **pas indentée**, alors que l'indentation indique ce qui appartient au bloc. En programmation textuelle, la **syntaxe est stricte** : un deux-points ou une indentation oubliés bloquent tout.\n4. Non : passer des blocs au texte ne change **rien** à l'algorithme. La même condition, avec les mêmes actions, est simplement écrite autrement."}$exo$::jsonb),
  ('830977f6-bd57-5ceb-bd17-11b717331c02'::uuid, 3, 'application', $exo${"titre":"Quel langage pour la station météo ?","consigne":"Analyse la situation, compare les deux approches de façon argumentée, puis écris le programme demandé.","enonce":"**Situation.** La classe de Mehdi construit une station météo. Deux usages sont prévus :\n- un **atelier de découverte** d'une heure pour des élèves de 5e qui n'ont jamais programmé ;\n- le **programme final**, de plusieurs centaines de lignes, qui pilotera la carte programmable, enregistrera les mesures et sera amélioré pendant des mois par plusieurs groupes.\n\n1. Compare la programmation graphique et la programmation textuelle sur **quatre** points du cours (syntaxe, lecture, programmes longs, partage).\n2. Quelle approche recommandes-tu pour chaque usage ? Justifie.\n3. Écris en Python une boucle qui répète **10 fois** : lire la température (lire_temperature()) et l'afficher (print). Explique le rôle de chaque élément de syntaxe.\n4. Selon le programme du cycle 4, que doit savoir faire un élève avec ces deux approches ?","bareme":[{"critere":"Comparaison sur quatre points justes du cours","points":6},{"critere":"Recommandation argumentée pour chaque usage","points":5},{"critere":"Boucle Python correcte (for, range, deux-points, indentation) et commentée","points":6},{"critere":"Lire et modifier les deux formes : blocs pour la logique, texte pour piloter ou traiter des données","points":3}],"dureeMin":18,"corrige":"1. **Syntaxe** : aucune faute possible en blocs (ils ne s'emboîtent pas s'ils sont incompatibles) ; stricte en texte (majuscule, deux-points, indentation). **Lecture** : structure visible d'un coup d'œil en blocs ; le texte demande de l'habitude. **Programmes longs** : peu adaptés en blocs ; sans limite en texte. **Partage** : les blocs dépendent d'un environnement ; le texte se copie, se versionne et se partage facilement.\n2. Atelier de découverte : la **programmation graphique** (Scratch, mBlock), car des débutants ne peuvent pas faire d'erreur de syntaxe et voient la logique. Programme final : la **programmation textuelle** (Python ou C++ Arduino), car il est long, doit piloter la carte et être partagé et amélioré par plusieurs groupes.\n3. Programme attendu :\n\n> for i in range(10):\n>     temperature = lire_temperature()\n>     print(temperature)\n\n« for … in range(10) » est une **boucle bornée** de 10 tours ; le **deux-points** ouvre le bloc ; l'**indentation** indique les deux instructions répétées ; **temperature** est une variable qui stocke la mesure.\n4. Savoir **lire et modifier** les deux : les blocs pour comprendre la logique, le texte pour piloter une carte programmable ou traiter des données."}$exo$::jsonb),
  ('cfa07410-9b3c-5063-a71e-8d001fe3295a'::uuid, 1, 'application', $exo${"titre":"La démarche et les erreurs","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite dans l'ordre les **cinq étapes** pour écrire un programme qui fonctionne.\n2. Comment s'appelle la recherche et la correction des erreurs ?\n3. Présente les trois types d'erreurs : ce qui se passe, et laquelle est la plus difficile à détecter.","bareme":[{"critere":"Cinq étapes dans l'ordre","points":7},{"critere":"Le débogage nommé","points":3},{"critere":"Trois types d'erreurs décrits, erreur de logique la plus difficile","points":10}],"dureeMin":6,"corrige":"1. **Analyser le besoin** (entrées, sorties) → écrire l'**algorithme** (pseudo-code ou organigramme) → **traduire** dans le langage → **tester** (comparer à l'attendu) → **corriger**, puis retester.\n2. Le **débogage**.\n3. Erreur de **syntaxe** : le programme ne démarre pas, un message indique la ligne ; c'est la plus facile. Erreur de **logique** : le programme s'exécute mais fait autre chose que prévu, sans aucun message ; c'est la **plus difficile**. Erreur d'**exécution** : le programme s'arrête en cours de route (division par zéro, capteur absent)."}$exo$::jsonb),
  ('cfa07410-9b3c-5063-a71e-8d001fe3295a'::uuid, 2, 'application', $exo${"titre":"Le distributeur de croquettes","consigne":"Lis la situation, puis réponds en justifiant avec le vocabulaire du cours.","enonce":"**Situation.** Amir programme un distributeur de croquettes pour son chat : il doit verser une dose à **8 h** et à **19 h**. Voici ses observations lors des essais :\n\n- Essai A : au lancement, le logiciel affiche « SyntaxError ligne 12 ».\n- Essai B : après correction, le programme tourne, mais verse la dose à **8 h** et à **9 h**.\n- Essai C : quand le réservoir est vide, le programme s'arrête avec un message « capteur de niveau absent ».\n\n1. Classe chaque essai selon le type d'erreur. Justifie.\n2. Pour l'essai B, propose une technique de mise au point pour trouver l'origine du problème.\n3. Construis un **jeu d'essai** de trois cas pour tester l'heure de distribution (un cas normal, un cas limite, un cas interdit).\n4. Pourquoi Amir doit-il commenter son code et nommer ses variables clairement ?","bareme":[{"critere":"Syntaxe, logique, exécution correctement attribuées et justifiées","points":6},{"critere":"Technique de mise au point adaptée (afficher les valeurs, pas à pas)","points":4},{"critere":"Jeu d'essai pertinent avec cas normal, limite et interdit","points":6},{"critere":"Intérêt de la documentation : modifiable par un autre ou plus tard","points":4}],"dureeMin":11,"corrige":"1. A : erreur de **syntaxe** (le programme ne démarre pas, la ligne est indiquée). B : erreur de **logique** (il s'exécute mais fait autre chose que prévu, sans message). C : erreur d'**exécution** (il s'arrête en cours de route à cause d'un capteur absent).\n2. **Afficher les valeurs intermédiaires** (par exemple l'heure lue et la condition testée) ou **exécuter pas à pas** en mode débogage pour voir où le comportement dévie (la condition contient sans doute 9 au lieu de 19).\n3. Exemple : cas **normal** : heure = 8 h → une dose ; cas **limite** : heure = 18 h 59 puis 19 h 00 → rien, puis une dose (ou minuit, 23 h 59) ; cas **interdit** : une heure absurde (25 h) ou réservoir vide → pas de dose et un message. Un programme qui marche une fois n'est pas validé : ce sont les cas limites qui révèlent les défauts.\n4. Les **commentaires** expliquent le pourquoi et des **noms explicites** (heure_repas plutôt que h2) rendent le programme **modifiable par un autre, ou par soi-même trois mois plus tard**."}$exo$::jsonb),
  ('cfa07410-9b3c-5063-a71e-8d001fe3295a'::uuid, 3, 'application', $exo${"titre":"Déboguer la moyenne de Chloé","consigne":"Analyse le programme, mène la démarche de mise au point, puis rédige une version corrigée et documentée.","enonce":"**Besoin.** Chloé veut un programme qui demande **trois notes**, calcule leur **moyenne** et affiche « Admis » si la moyenne est **supérieure ou égale à 10**, sinon « Refusé ».\n\n**Son programme (pseudo-code) :**\n\n> a ← lire une note\n> b ← lire une note\n> c ← lire une note\n> m ← a + b + c / 3\n> SI m > 10 ALORS afficher « Admis » SINON afficher « Refusé »\n\n**Ses essais :**\n\n| Notes | Moyenne attendue | Affichage obtenu |\n|---|---|---|\n| 12, 14, 16 | 14 | Admis |\n| 6, 6, 3 | 5 | Admis |\n\n1. Quel type d'erreur Chloé rencontre-t-elle ? Justifie à partir des essais.\n2. Calcule la valeur de m obtenue par son programme pour les notes 6, 6, 3. Quelle est l'erreur de calcul ?\n3. Quelle autre erreur apparaîtrait avec les notes 10, 10, 10 ? Pourquoi son premier essai ne suffisait-il pas à valider le programme ?\n4. Propose un jeu d'essai de trois cas et le résultat attendu pour chacun.\n5. Écris le programme corrigé, avec des noms de variables explicites et un commentaire.","bareme":[{"critere":"Erreur de logique identifiée et justifiée par les essais","points":3},{"critere":"Calcul de m = 13 et priorité de la division expliquée","points":4},{"critere":"Cas limite 10 : > au lieu de ≥ ; un essai réussi ne valide pas","points":4},{"critere":"Jeu d'essai normal, limite, interdit avec résultats attendus","points":4},{"critere":"Programme corrigé, variables explicites, commentaire","points":5}],"dureeMin":18,"corrige":"1. Une erreur de **logique** : le programme s'exécute sans message, mais affiche « Admis » pour une moyenne de 5.\n2. La division est prioritaire : m = 6 + 6 + 3 ÷ 3 = 6 + 6 + 1 = **13**, d'où « Admis ». Seule c est divisée ; il faut des **parenthèses** : m ← (a + b + c) / 3. Le premier essai donnait « Admis » par chance (m ≈ 31,3).\n3. Avec 10, 10, 10, la moyenne vaut 10 mais « m > 10 » est faux : le programme afficherait « Refusé » alors que le besoin demande « supérieure ou égale ». Il faut **m ≥ 10**. Le premier essai est un **cas normal** qui a « marché une fois » : cela ne valide rien, ce sont les **cas limites** qui révèlent les défauts.\n4. Exemple : cas normal 12, 14, 16 → 14, Admis ; cas limite 10, 10, 10 → 10, Admis (et 9, 10, 10 → 9,67, Refusé) ; cas interdit : une note de 25 ou une lettre → message d'erreur attendu (le programme devra alors vérifier chaque saisie : 0 ≤ note ≤ 20).\n5. Programme corrigé :\n\n> // calcule la moyenne de trois notes et indique la décision\n> note1 ← lire une note\n> note2 ← lire une note\n> note3 ← lire une note\n> moyenne ← (note1 + note2 + note3) / 3\n> SI moyenne ≥ 10 ALORS afficher « Admis » SINON afficher « Refusé »"}$exo$::jsonb),
  ('c4ba3ef4-aa90-5628-b329-1bab857d18d2'::uuid, 1, 'application', $exo${"titre":"Données, tableaux et graphiques","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Quelle est la différence entre une **donnée** et une **information** ? Donne un exemple.\n2. Dans un tableau de données, que représentent une **ligne**, une **colonne** et la **clé** ?\n3. Quel graphique choisir pour : une évolution dans le temps ; une comparaison ; une répartition ?\n4. Qu'est-ce qu'un fichier **CSV** ?","bareme":[{"critere":"Donnée et information distinguées avec un exemple","points":5},{"critere":"Ligne = enregistrement, colonne = champ, clé = identifiant sans ambiguïté","points":6},{"critere":"Courbe, histogramme, camembert correctement associés","points":6},{"critere":"CSV : tableau en texte, champs séparés par des virgules ou points-virgules","points":3}],"dureeMin":6,"corrige":"1. Une **donnée** est une valeur brute (18) ; une **information** est une donnée interprétée dans un contexte (« la température du local est de 18 °C »).\n2. Une **ligne** est un **enregistrement** (un objet, une personne, une mesure) ; une **colonne** est un **champ** (nom, date, valeur) ; la **clé** est le champ qui identifie chaque ligne **sans ambiguïté**.\n3. Évolution dans le temps : la **courbe** ; comparaison : l'**histogramme** ; répartition : le **camembert**.\n4. Un **tableau écrit en texte**, dont les champs sont séparés par des **virgules ou des points-virgules** ; simple et lisible partout."}$exo$::jsonb),
  ('c4ba3ef4-aa90-5628-b329-1bab857d18d2'::uuid, 2, 'application', $exo${"titre":"Les relevés de la mini-station météo","consigne":"Lis le tableau, puis réponds en justifiant chaque réponse. Détaille tes calculs.","enonce":"**Document.** Relevés de la station météo du collège de Baptiste :\n\n| Numéro | Jour | Température (°C) | Pluie (oui/non) |\n|---|---|---|---|\n| 1 | Lundi | 14 | oui |\n| 2 | Mardi | 17 | non |\n| 3 | Mercredi | 16 | non |\n| 4 | Jeudi | 150 | oui |\n| 5 | Vendredi | 18 | non |\n\n1. Quel champ joue le rôle de **clé** ? Donne le **type** de données des champs Température et Pluie.\n2. Repère une valeur **aberrante**. Que faut-il faire avant tout calcul ?\n3. Filtre les jours **sans pluie** et calcule leur température moyenne.\n4. Baptiste veut montrer l'évolution de la température sur la semaine. Quel graphique choisir ? Pourquoi un camembert serait-il un mauvais choix ?","bareme":[{"critere":"Clé (numéro) et types (nombre, booléen) identifiés","points":4},{"critere":"Valeur de 150 °C repérée comme aberrante, vérification avant calcul","points":5},{"critere":"Filtre correct et moyenne des jours sans pluie : 17 °C","points":6},{"critere":"Courbe justifiée, camembert inadapté (répartition)","points":5}],"dureeMin":10,"corrige":"1. La **clé** est le champ **Numéro** : il identifie chaque ligne sans ambiguïté. Température : **nombre** ; Pluie : **booléen** (vrai/faux).\n2. **150 °C** le jeudi est une valeur **aberrante** (erreur de saisie : sans doute 15). Il faut **vérifier et corriger** (ou écarter) cette valeur avant tout calcul, car elle fausserait tout le traitement.\n3. Filtre « Pluie = non » : mardi (17), mercredi (16), vendredi (18). Moyenne : (17 + 16 + 18) ÷ 3 = 51 ÷ 3 = **17 °C**.\n4. Une **courbe**, qui représente une **évolution dans le temps**. Un camembert montre une **répartition** (des parts d'un tout) : des températures ne sont pas les parts d'un total ; il raconterait autre chose que ce que disent les données."}$exo$::jsonb),
  ('c4ba3ef4-aa90-5628-b329-1bab857d18d2'::uuid, 3, 'application', $exo${"titre":"Enquête sur la cantine","consigne":"Analyse le jeu de données, mène les traitements demandés et rédige des conclusions justifiées.","enonce":"**Document 1 : extrait du fichier CSV de l'enquête** (séparateur point-virgule)\n\n> id;classe;plat_prefere;note_sur_10\n> 1;5eA;pâtes;8\n> 2;5eA;poisson;6\n> 3;4eB;pâtes;9\n> 4;4eB;pâtes;7\n> 5;3eC;poisson;-4\n> 6;3eC;légumes;7\n\n**Document 2.** Le gestionnaire veut savoir **quel plat est préféré** et **quelle note moyenne** les élèves donnent à la cantine.\n\n1. Reconstitue le tableau : combien d'enregistrements et de champs ? Quel est le type de chaque champ ?\n2. Repère la donnée à vérifier avant tout calcul et explique pourquoi.\n3. Calcule la note moyenne **en écartant** la valeur aberrante.\n4. Calcule la répartition des plats préférés (en nombre d'élèves) et choisis le graphique adapté. Justifie.\n5. Quel autre format d'échange aurait pu servir, et dans quel contexte l'utilise-t-on ?","bareme":[{"critere":"6 enregistrements, 4 champs, types corrects (nombre, texte)","points":4},{"critere":"Note de -4 repérée comme aberrante, justifiée","points":3},{"critere":"Moyenne correcte sans la valeur aberrante : 7,4","points":5},{"critere":"Répartition 3 / 2 / 1 et camembert justifié","points":5},{"critere":"JSON, couples nom-valeur, objets connectés et sites web","points":3}],"dureeMin":18,"corrige":"1. **6 enregistrements** (une ligne par élève) et **4 champs** : id (nombre entier, c'est la **clé**), classe (texte), plat_prefere (texte), note_sur_10 (nombre).\n2. La note **-4** est **aberrante** : une note sur 10 est comprise entre 0 et 10. Une valeur mal saisie fausse tout le traitement ; vérifier les valeurs extrêmes fait partie du travail.\n3. Notes retenues : 8, 6, 9, 7, 7. Somme = 37 ; moyenne = 37 ÷ 5 = **7,4 sur 10**.\n4. Répartition : pâtes **3** élèves, poisson **2**, légumes **1** (6 au total). Il s'agit des **parts d'un tout** : le **camembert** convient (un histogramme serait acceptable pour comparer, mais pas une courbe, qui montre une évolution dans le temps). Les pâtes sont le plat préféré (la moitié des élèves).\n5. Le format **JSON**, fait de **couples nom-valeur** (par exemple « plat_prefere » : « pâtes »), utilisé par les **objets connectés** et les **sites web**."}$exo$::jsonb),
  ('09d618b9-bd1a-58ae-a0d1-e7b64f37d1ec'::uuid, 1, 'application', $exo${"titre":"Où vivent les données ?","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Qu'est-ce qu'un **système d'information** ? Cite ses cinq composantes.\n2. Donne un atout et une limite du stockage **local** et du stockage **dans le nuage**.\n3. Combien d'octets valent 1 Mo, 1 Go et 1 To ?\n4. Énonce la règle de sauvegarde **3-2-1**.","bareme":[{"critere":"Définition du système d'information et cinq composantes","points":5},{"critere":"Atout et limite du local et du nuage","points":6},{"critere":"Unités 10⁶, 10⁹, 10¹² octets","points":4},{"critere":"Règle 3-2-1 complète","points":5}],"dureeMin":6,"corrige":"1. C'est l'ensemble de ce qui permet de **collecter, stocker, traiter et diffuser** des données : **matériel, logiciels, données, procédures et utilisateurs**.\n2. **Local** (disque, SSD, clé USB) : accessible **sans réseau**, mais fragile (**panne, vol, incendie**). **Nuage** : accessible **de partout**, mais dépend du **réseau et du prestataire**.\n3. 1 Mo = **10⁶ octets** ; 1 Go = **10⁹ octets** ; 1 To = **10¹² octets**.\n4. **3** copies des données, sur **2** supports différents, dont **1** hors du lieu principal."}$exo$::jsonb),
  ('09d618b9-bd1a-58ae-a0d1-e7b64f37d1ec'::uuid, 2, 'application', $exo${"titre":"Les photos de la classe de neige","consigne":"Lis la situation, puis réponds en détaillant tes calculs et en justifiant avec le cours.","enonce":"**Situation.** Mme Leroy a pris **1 200 photos** de **4 Mo** chacune pendant la classe de neige. Elles sont uniquement sur la carte mémoire de son appareil. Elle dispose d'une clé USB de **4 Go**, d'un disque dur externe de **1 To** et d'un espace de stockage en ligne.\n\n1. Calcule la taille totale des photos en Mo puis en Go.\n2. Les photos tiennent-elles sur la clé USB ? Sur le disque dur ? Justifie.\n3. Propose une organisation des sauvegardes qui respecte la règle 3-2-1.\n4. Mme Leroy veut partager l'album en ligne avec les familles. Cite deux mesures de sécurité à prendre.","bareme":[{"critere":"Taille totale : 4 800 Mo, soit 4,8 Go","points":5},{"critere":"Clé trop petite, disque suffisant, justifiés","points":4},{"critere":"Organisation 3-2-1 cohérente avec les supports disponibles","points":6},{"critere":"Deux mesures de sécurité pertinentes (mot de passe, droits d'accès, double authentification)","points":5}],"dureeMin":10,"corrige":"1. 1 200 × 4 = **4 800 Mo**. Comme 1 Go = 1 000 Mo (10⁹ = 10³ × 10⁶), cela fait **4,8 Go**.\n2. La clé USB (4 Go) est **trop petite** : 4,8 Go > 4 Go. Le disque dur (1 To = 1 000 Go) est **largement suffisant**.\n3. **3 copies** : la carte mémoire, le disque dur externe, l'espace en ligne. **2 supports différents** : la carte et le disque dur (plus les serveurs du nuage). **1 hors du lieu principal** : la copie en ligne, dans un centre de données. Il faut aussi **tester** la sauvegarde : une sauvegarde jamais testée n'est pas une sauvegarde.\n4. Un **mot de passe long et unique**, l'**authentification à deux facteurs**, et des **droits d'accès** limités aux familles de la classe (chacun ne voit que ce qui le concerne)."}$exo$::jsonb),
  ('09d618b9-bd1a-58ae-a0d1-e7b64f37d1ec'::uuid, 3, 'application', $exo${"titre":"La montre connectée et ses données","consigne":"Analyse les documents, puis rédige des réponses argumentées qui mobilisent le stockage, la sécurité et le RGPD.","enonce":"**Document 1 : fiche du produit.**\n\n> La montre enregistre votre rythme cardiaque toutes les minutes et vos trajets GPS. Les données sont envoyées chaque soir sur nos serveurs, et conservées sans limite de durée. En activant la montre, vous acceptez les conditions d'utilisation.\n\n**Document 2.** Une mesure du rythme cardiaque occupe **8 octets**.\n\n**Document 3.** Un journal titre : « Le nuage, c'est quelque part dans le ciel : nos données ne coûtent rien à la planète. »\n\n1. Calcule la taille des mesures cardiaques d'une journée, puis d'une année (365 jours). Exprime le résultat annuel en Mo.\n2. D'après le document 1, repère **deux** points qui posent problème au regard du **RGPD**. Explique.\n3. Quels **droits** l'utilisateur peut-il exercer sur ses données ?\n4. Critique le titre du document 3 à l'aide du cours.\n5. Propose trois mesures de sécurité que le fabricant devrait appliquer pour protéger ces données sensibles.","bareme":[{"critere":"Calcul : 11 520 octets par jour, environ 4,2 Mo par an","points":4},{"critere":"Deux manquements au RGPD repérés et expliqués (durée illimitée, consentement non explicite)","points":5},{"critere":"Droits d'accès, de rectification et de suppression","points":3},{"critere":"Critique du titre : centres de données réels, électricité et eau","points":4},{"critere":"Trois mesures de sécurité adaptées (chiffrement, droits d'accès, mises à jour…)","points":4}],"dureeMin":18,"corrige":"1. Une journée = 24 × 60 = 1 440 minutes. 1 440 × 8 = **11 520 octets** par jour. Une année : 11 520 × 365 = **4 204 800 octets**, soit environ **4,2 Mo** (1 Mo = 10⁶ octets).\n2. La **durée de conservation** doit être **limitée** : « sans limite de durée » ne respecte pas le RGPD. Le **consentement** doit être **explicite** : accepter en activant la montre, au milieu des conditions d'utilisation, ne l'est pas. On peut aussi relever que la **finalité** (à quoi servent les données) n'est pas déclarée.\n3. Un droit d'**accès**, de **rectification** et de **suppression** de ses données. Un objet connecté y est soumis comme un site web.\n4. Le titre est faux : « le nuage » n'a rien d'immatériel. Ce sont des **centres de données bien réels**, remplis de serveurs qui consomment de l'**électricité** et de l'**eau de refroidissement**. Stocker des données a donc un coût environnemental.\n5. Le **chiffrement** (données illisibles sans la clé), des **droits d'accès** limités (chacun ne voit que ce qui le concerne), des **mises à jour** qui corrigent les failles, l'**authentification à deux facteurs** et un mot de passe long pour le compte de l'utilisateur."}$exo$::jsonb),
  ('2d7d3f0b-6850-5c98-b3c2-62d4b6787f7c'::uuid, 1, 'application', $exo${"titre":"Le vocabulaire des réseaux","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Que désignent **LAN**, **WAN** et **Internet** ?\n2. Donne le rôle du **switch**, du **routeur** et du **serveur**.\n3. À quoi servent l'**adresse IP** et le **DNS** ?\n4. Que signifie le **S** de HTTPS ?","bareme":[{"critere":"Trois échelles de réseau correctement décrites","points":5},{"critere":"Rôle du switch, du routeur et du serveur","points":6},{"critere":"Rôle de l'adresse IP et du DNS","points":6},{"critere":"HTTPS : échange chiffré","points":3}],"dureeMin":6,"corrige":"1. **LAN** : réseau **local** (une salle, un établissement, une maison). **WAN** : réseau étendu sur plusieurs sites, une région, un pays. **Internet** : le réseau **mondial** qui relie tous les autres.\n2. Le **switch** relie les machines d'un **même réseau local** et aiguille les messages. Le **routeur** relie **deux réseaux différents** et choisit le chemin. Le **serveur** est une machine qui **rend un service** au client qui le demande.\n3. L'**adresse IP** identifie chaque machine, comme une adresse postale. Le **DNS** traduit un nom lisible (un nom de site) en adresse IP.\n4. Le S signifie que l'échange est **chiffré**, donc sécurisé."}$exo$::jsonb),
  ('2d7d3f0b-6850-5c98-b3c2-62d4b6787f7c'::uuid, 2, 'application', $exo${"titre":"Le voyage d'une page web","consigne":"Lis la situation, puis explique chaque étape avec le vocabulaire du cours.","enonce":"**Situation.** Chez elle, Emma est connectée en Wi-Fi à sa **box**. Elle tape dans son navigateur l'adresse d'un site de musées et la page s'affiche en moins d'une seconde.\n\n1. Cite les quatre équipements réunis dans la box.\n2. Explique le rôle du **DNS** au moment où Emma tape l'adresse du site.\n3. Décris comment la page circule du serveur jusqu'à l'ordinateur d'Emma (découpage en paquets, chemins, arrivée).\n4. Pendant le transfert, un câble est coupé entre deux routeurs. La page s'affiche-t-elle quand même ? Justifie.","bareme":[{"critere":"Routeur, switch, modem et point d'accès Wi-Fi","points":4},{"critere":"DNS : nom du site traduit en adresse IP du serveur","points":4},{"critere":"Paquets numérotés, chemins différents, réassemblage, paquet manquant redemandé","points":8},{"critere":"Robustesse : les paquets passent par un autre chemin","points":4}],"dureeMin":10,"corrige":"1. La box réunit un **routeur**, un **switch**, un **modem** et un **point d'accès Wi-Fi**.\n2. L'ordinateur ne connaît que des adresses IP : le **DNS** traduit le **nom du site** en **adresse IP** du serveur, que l'ordinateur peut alors contacter.\n3. Le serveur découpe la page en **paquets numérotés**. Ils voyagent de routeur en routeur et peuvent emprunter des **chemins différents**. À l'arrivée, l'ordinateur d'Emma les **réassemble** dans l'ordre ; un paquet manquant est **redemandé**.\n4. Oui : si un chemin est coupé, les paquets passent **par un autre**. C'est ce découpage qui rend Internet **robuste**."}$exo$::jsonb),
  ('2d7d3f0b-6850-5c98-b3c2-62d4b6787f7c'::uuid, 3, 'application', $exo${"titre":"Le réseau du collège et la sécurité","consigne":"Analyse le schéma décrit, puis réponds de façon argumentée en mobilisant équipements, adressage, protocoles et liaisons.","enonce":"**Description du réseau du collège.** Dans la salle de technologie, 15 ordinateurs sont reliés par câble à un **switch**. Le CDI a son propre switch et une borne Wi-Fi. Les deux switchs sont reliés à un **serveur** de fichiers et à un **routeur** qui donne accès à Internet. Chaque machine a une adresse IP.\n\n**Deux incidents :**\n- A : un élève envoie un fichier à un ordinateur du CDI : il arrive, mais Internet est inaccessible dans tout le collège.\n- B : un parent, garé devant le collège, capte le Wi-Fi du CDI dont le mot de passe est affiché sur la porte.\n\n1. Ce réseau est-il un LAN ou un WAN ? Justifie.\n2. Le fichier de l'incident A passe par quels équipements ? Quel équipement est probablement en panne ? Justifie.\n3. Quels protocoles utilise-t-on pour : envoyer un courriel aux parents ; déposer un gros fichier sur un serveur distant ; consulter l'ENT de façon sécurisée ?\n4. Analyse l'incident B : quel risque, pourquoi le Wi-Fi y est-il plus exposé que le câble, et quelles mesures prendre ?","bareme":[{"critere":"LAN justifié par l'étendue d'un établissement","points":3},{"critere":"Trajet par les switchs, routeur en panne justifié (lien entre réseaux)","points":6},{"critere":"SMTP, FTP, HTTPS correctement associés","points":5},{"critere":"Risque d'interception, comparaison Wi-Fi / câble, mesures proposées","points":6}],"dureeMin":18,"corrige":"1. C'est un **LAN** : un réseau **local**, limité à un établissement.\n2. Le fichier part de l'ordinateur vers le **switch** de la salle de technologie, puis vers le **switch du CDI** (et éventuellement par le serveur de fichiers), jusqu'à l'ordinateur destinataire : ce sont des échanges **à l'intérieur du même réseau local**, assurés par les switchs. Internet est inaccessible pour tous : l'équipement qui relie le réseau du collège à **un autre réseau** est le **routeur** ; c'est lui qui est probablement en panne.\n3. Courriel : **SMTP**. Transfert de fichiers : **FTP**. ENT sécurisé : **HTTPS** (le S indique un échange chiffré).\n4. Le parent peut entrer dans le réseau du collège : **interception** des échanges, accès à des ressources partagées. Le **Wi-Fi** se propage au-delà des murs et reste **sensible aux interceptions**, alors que le **câble Ethernet** est plus sûr (il faut s'y brancher physiquement), plus rapide et plus stable. Mesures : ne jamais **afficher le mot de passe**, en choisir un **long** et le changer, réserver le Wi-Fi aux utilisateurs autorisés ; relier en **filaire** les postes sensibles."}$exo$::jsonb),
  ('842de49d-6bb2-5aab-8416-11a52a5c68f4'::uuid, 1, 'application', $exo${"titre":"Les phases d'un projet","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Définis un **projet technique**.\n2. Cite dans l'ordre les **six phases** d'un projet et ce que produit la première.\n3. Que porte chaque axe d'un **diagramme de Gantt** ? Que représente la longueur d'une barre ?\n4. Qu'est-ce qu'une **antériorité** entre deux tâches ?","bareme":[{"critere":"Définition : actions coordonnées, objectif, délai, moyens limités","points":4},{"critere":"Six phases dans l'ordre, cahier des charges pour la première","points":7},{"critere":"Axes du Gantt et longueur des barres","points":5},{"critere":"Antériorité correctement définie","points":4}],"dureeMin":6,"corrige":"1. Un ensemble d'**actions coordonnées**, avec un **objectif**, un **délai** et des **moyens limités**.\n2. **Analyse du besoin** (elle produit le **cahier des charges**) → **recherche de solutions** → **conception** → **réalisation** → **tests et validation** → **bilan**.\n3. L'**abscisse** porte le **temps**, l'**ordonnée** les **tâches** ; la longueur d'une barre est la **durée** de la tâche.\n4. Une tâche qui doit être **terminée avant** qu'une autre puisse commencer."}$exo$::jsonb),
  ('842de49d-6bb2-5aab-8416-11a52a5c68f4'::uuid, 2, 'application', $exo${"titre":"Le planning de la mangeoire connectée","consigne":"Lis le tableau des tâches, puis réponds en justifiant. Tu peux tracer le diagramme de Gantt sur ta copie.","enonce":"**Situation.** L'équipe de Sofiane fabrique une mangeoire à oiseaux connectée. Les tâches :\n\n| Tâche | Durée | Antériorité |\n|---|---|---|\n| A. Rédiger le cahier des charges | 1 semaine | aucune |\n| B. Dessiner et modéliser la mangeoire | 2 semaines | A |\n| C. Écrire le programme du capteur | 3 semaines | A |\n| D. Fabriquer la structure | 2 semaines | B |\n| E. Assembler et tester | 1 semaine | C et D |\n\n1. Quelles tâches peuvent se dérouler **en parallèle** ?\n2. Calcule la durée totale minimale du projet. Détaille.\n3. Quel est le **chemin critique** ? Quelle tâche dispose d'une **marge**, et de combien ?\n4. La fabrication (D) prend une semaine de retard. Quelle conséquence sur la fin du projet ?","bareme":[{"critere":"Tâches parallèles identifiées : B et D en même temps que C","points":4},{"critere":"Durée totale : 6 semaines, calcul détaillé","points":6},{"critere":"Chemin critique A-B-D-E et marge d'une semaine sur C","points":6},{"critere":"Retard sur D : fin du projet décalée d'une semaine","points":4}],"dureeMin":12,"corrige":"1. Après A, la branche **B puis D** et la tâche **C** se déroulent **en parallèle**.\n2. A : semaine 1. Branche B + D : 2 + 2 = 4 semaines (semaines 2 à 5). C : 3 semaines (semaines 2 à 4). E attend la fin de C et de D, donc commence en semaine 6 et dure 1 semaine. Durée totale : 1 + 4 + 1 = **6 semaines**.\n3. Chemin critique : **A → B → D → E** (1 + 2 + 2 + 1 = 6 semaines). La tâche **C** dispose d'une **marge d'une semaine** (elle dure 3 semaines alors que B + D en durent 4).\n4. D est sur le chemin critique : tout retard décale la fin. Le projet dure **7 semaines** au lieu de 6."}$exo$::jsonb),
  ('842de49d-6bb2-5aab-8416-11a52a5c68f4'::uuid, 3, 'application', $exo${"titre":"Sauver le projet de la serre automatique","consigne":"Analyse la situation, puis propose et justifie une organisation, en mobilisant les phases, le Gantt, les rôles et la traçabilité.","enonce":"**Situation.** Une équipe de 5 élèves (Anaïs, Bilal, Chen, Dora, Ethan) réalise une serre à arrosage automatique en **8 semaines**. À la semaine 4, rien n'est prêt : tout le monde a travaillé ensemble sur chaque tâche l'une après l'autre, personne ne sait qui s'occupe de quoi, et un premier essai de pompe a raté sans que personne ne note pourquoi. Tâches restantes :\n\n| Tâche | Durée | Antériorité |\n|---|---|---|\n| P. Programmer le capteur d'humidité | 2 semaines | aucune |\n| F. Fabriquer le bac et le support | 2 semaines | aucune |\n| M. Monter la pompe et les tuyaux | 1 semaine | F |\n| T. Tests et validation | 1 semaine | P et M |\n| D. Rédiger le dossier final | 1 semaine | T |\n\n1. Explique les **trois erreurs d'organisation** de l'équipe.\n2. Propose une **répartition des rôles** entre les cinq élèves.\n3. Calcule la durée minimale des tâches restantes. Le projet peut-il finir à temps ? Identifie le chemin critique.\n4. À quoi servira un **carnet de bord** pour la suite, notamment pour l'essai de pompe raté ?\n5. Quand placer des **revues de projet** et à quoi serviront-elles ?","bareme":[{"critere":"Trois erreurs expliquées : pas de parallélisme, pas de rôles, pas de traçabilité","points":5},{"critere":"Répartition des rôles cohérente avec les cinq rôles du cours","points":4},{"critere":"Durée de 5 semaines calculée, retard d'une semaine identifié, chemin critique F-M-T-D","points":5},{"critere":"Rôle du carnet de bord et de l'essai raté documenté","points":3},{"critere":"Revues de projet placées et justifiées","points":3}],"dureeMin":20,"corrige":"1. (a) Les tâches ont été faites **l'une après l'autre** alors que beaucoup peuvent se dérouler **en parallèle** : du temps perdu. (b) Aucun **rôle** n'est réparti : personne ne répond de rien. (c) Aucune **traçabilité** : l'essai raté n'a pas été noté, l'équipe risque de refaire la même erreur.\n2. Exemple : Anaïs **programmation** (P) ; Bilal et Chen **fabrication** (F, M) ; Dora **documentation** (le dossier, le carnet de bord) ; Ethan **coordination** (planning, revues) et **conception** (plans et choix). Toute répartition cohérente est acceptée.\n3. P (2 semaines) et F (2 semaines) démarrent ensemble en semaines 5 et 6 ; M en semaine 7 (après F) ; T en semaine 8 (après P et M) ; D en semaine 9. Durée : 2 + 1 + 1 + 1 = **5 semaines** ; le projet finirait en **semaine 9**, soit **une semaine de retard** sur les 8 prévues. Chemin critique : **F → M → T → D** ; P a une **marge** d'une semaine. Pour finir à temps, il faut commencer D en parallèle de T (rédiger le dossier au fil du projet) ou raccourcir une tâche critique.\n4. Le **carnet de bord** garde les décisions, les essais ratés **et leurs raisons**. Documenter l'essai de pompe raté évite qu'un autre refasse la même erreur : un essai raté documenté vaut mieux qu'un succès inexpliqué.\n5. Des **revues de projet régulières** (par exemple chaque semaine, ou à la fin de F et avant T) : elles font le point en équipe et **corrigent la trajectoire** avant qu'il ne soit trop tard."}$exo$::jsonb),
  ('ef65921a-9a3d-5f7f-bd7b-238ea0cd163c'::uuid, 1, 'application', $exo${"titre":"Croquis, schéma, dessin, modèle 3D","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite les **quatre représentations** d'un objet technique et dis quand on utilise chacune.\n2. Que signifient les échelles **1:2**, **2:1** et **1:1** ?\n3. Que désignent un trait continu fort, un trait interrompu et un trait mixte fin sur un dessin technique ?","bareme":[{"critere":"Quatre représentations et leur usage","points":8},{"critere":"Trois échelles correctement interprétées","points":6},{"critere":"Trois types de traits correctement associés","points":6}],"dureeMin":6,"corrige":"1. Le **croquis**, à main levée, pour **chercher** une idée en début de projet ; le **schéma**, qui montre le **fonctionnement** et sert à **expliquer** ; le **dessin technique**, coté et normalisé, pour **faire fabriquer** ; le **modèle 3D**, manipulable, pour **simuler** et produire.\n2. **1:2** : le dessin est **deux fois plus petit** que l'objet ; **2:1** : **deux fois plus grand** ; **1:1** : **grandeur nature**.\n3. Trait continu fort : une **arête vue** ; trait interrompu : une **arête cachée** ; trait mixte fin : un **axe**."}$exo$::jsonb),
  ('ef65921a-9a3d-5f7f-bd7b-238ea0cd163c'::uuid, 2, 'application', $exo${"titre":"Le dessin du porte-clés","consigne":"Lis la situation, puis réponds en détaillant les calculs d'échelle et en justifiant.","enonce":"**Situation.** Lina dessine un porte-clés rectangulaire de **60 mm × 30 mm**, percé d'un trou pour l'anneau. Sur son dessin technique, le rectangle mesure **120 mm × 60 mm**.\n\n1. À quelle échelle Lina a-t-elle dessiné ? Justifie par un calcul.\n2. Quelle cote Lina doit-elle écrire pour la longueur : 60 ou 120 ? Pourquoi ?\n3. Le trou est vu de face. Sur la vue de dessus, il ne se voit pas. Avec quel type de trait le représente-t-on sur cette vue, et quel trait marque l'axe du trou ?\n4. Avant de dessiner, Lina avait fait un croquis. Pourquoi ne suffit-il pas pour faire fabriquer la pièce ?","bareme":[{"critere":"Échelle 2:1 justifiée par le calcul 120 ÷ 60","points":5},{"critere":"Cote de 60 mm : la cotation donne les dimensions réelles","points":5},{"critere":"Trait interrompu pour l'arête cachée, trait mixte fin pour l'axe","points":5},{"critere":"Croquis non coté ni à l'échelle, dessin technique = document contractuel","points":5}],"dureeMin":10,"corrige":"1. 120 ÷ 60 = 2 (et 60 ÷ 30 = 2) : le dessin est **deux fois plus grand** que l'objet, l'échelle est **2:1**.\n2. Elle écrit **60** : la **cotation** donne toujours les **dimensions réelles** de l'objet, en millimètres, quelle que soit l'échelle.\n3. Le trou est une arête **cachée** sur la vue de dessus : on le représente en **trait interrompu**. Son axe est tracé en **trait mixte fin**.\n4. Un croquis est fait à **main levée**, sans échelle ni cotes exactes : il sert à chercher. Pour fabriquer, il faut un **dessin technique** coté et à l'échelle, **document contractuel** lu de la même façon par le concepteur et par le fabricant."}$exo$::jsonb),
  ('ef65921a-9a3d-5f7f-bd7b-238ea0cd163c'::uuid, 3, 'application', $exo${"titre":"Représenter une lampe de bureau articulée","consigne":"Analyse la situation, puis choisis et justifie la représentation adaptée à chaque besoin, et réalise les calculs demandés.","enonce":"**Situation.** Une équipe conçoit une lampe de bureau : un pied, deux bras articulés et une tête avec une LED. Au cours du projet, elle doit :\n\n- (a) trouver une idée de forme en début de projet ;\n- (b) expliquer au professeur comment les bras tournent l'un par rapport à l'autre ;\n- (c) montrer comment la LED est branchée à la pile et à l'interrupteur ;\n- (d) vérifier, avant de fabriquer, que les bras ne se cognent pas en pivotant ;\n- (e) faire découper les bras de **240 mm** de long par un fabricant.\n\n1. Pour chaque besoin (a à e), indique la représentation adaptée (et, pour un schéma, son type). Justifie.\n2. Pour le besoin (e), la feuille ne permet qu'un dessin de 120 mm de long. Quelle échelle choisir ? Quelle cote écrire ?\n3. Explique trois avantages de la modélisation 3D pour ce projet.\n4. Pourquoi dit-on qu'un dessin technique « n'est pas un joli dessin » ?","bareme":[{"critere":"Représentation adaptée et justifiée pour chacun des cinq besoins","points":8},{"critere":"Échelle 1:2 et cote réelle de 240 mm","points":4},{"critere":"Trois avantages de la 3D (éclaté, simulation, interférences, export)","points":5},{"critere":"Dessin technique comme document contractuel","points":3}],"dureeMin":18,"corrige":"1. (a) Le **croquis** à main levée : rapide, pour chercher en début de projet. (b) Le **schéma cinématique** : il montre les **liaisons entre pièces et les mouvements possibles**. (c) Le **schéma électrique** : les composants normalisés du circuit. (d) Le **modèle 3D** : il permet de **vérifier les interférences** entre pièces avant toute fabrication. (e) Le **dessin technique** coté et à l'échelle : pour faire fabriquer.\n2. 240 mm doivent tenir en 120 mm : le dessin est deux fois plus petit, échelle **1:2**. La cote écrite est **240** mm : la cotation donne les dimensions réelles.\n3. Visualiser la lampe sous tous les angles, en **éclaté**, pour comprendre l'assemblage ; **simuler** les mouvements et les efforts, ce qui évite un essai coûteux ; vérifier les **interférences** entre les bras ; **exporter** les pièces vers une imprimante 3D ou une MOCN.\n4. Parce que c'est un **document contractuel** : ses cotes, ses vues et ses traits obéissent à des règles fixes, pour être **lu de la même façon par le concepteur et par le fabricant**. Sa fonction est l'exactitude, pas la beauté."}$exo$::jsonb),
  ('3fa26bb8-60f5-5520-a0a4-186cc0fae69a'::uuid, 1, 'application', $exo${"titre":"Les sept étapes de la conception","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite dans l'ordre les **sept étapes** de la démarche de conception.\n2. Définis une **nomenclature** et une **gamme de fabrication**.\n3. Pourquoi dit-on que la démarche est **itérative** ?","bareme":[{"critere":"Sept étapes dans l'ordre","points":9},{"critere":"Nomenclature et gamme de fabrication définies","points":6},{"critere":"Démarche itérative : retour en arrière en cas de blocage, une boucle","points":5}],"dureeMin":6,"corrige":"1. **Analyser** (besoin, cahier des charges) → **rechercher** plusieurs solutions → **choisir** (tableau multicritère) → **concevoir en détail** → **préparer la fabrication** → **fabriquer et assembler** → **tester, valider, améliorer**.\n2. La **nomenclature** est la liste des pièces avec leurs **quantités et références**. La **gamme de fabrication** est l'**ordre des opérations** pour réaliser une pièce.\n3. Parce qu'on **revient en arrière** quand un test échoue ou qu'une contrainte change (un test raté renvoie à la conception, un matériau indisponible au choix des solutions) : la démarche n'est pas une ligne droite, c'est une **boucle**."}$exo$::jsonb),
  ('3fa26bb8-60f5-5520-a0a4-186cc0fae69a'::uuid, 2, 'application', $exo${"titre":"Choisir le support de téléphone","consigne":"Lis la situation, complète le calcul du tableau multicritère, puis justifie ton choix.","enonce":"**Situation.** L'équipe de Rayan doit choisir entre trois idées de support de téléphone. Les critères sont notés sur 5 et pondérés :\n\n| Critère (coefficient) | Solution 1 : bois | Solution 2 : impression 3D | Solution 3 : tôle pliée |\n|---|---|---|---|\n| Stabilité (×3) | 4 | 3 | 5 |\n| Coût (×2) | 3 | 4 | 2 |\n| Facilité de fabrication (×1) | 2 | 5 | 4 |\n\n1. Pourquoi l'équipe a-t-elle eu raison de chercher **plusieurs** solutions ?\n2. Calcule le total pondéré de chaque solution. Laquelle retenir ?\n3. À quelle étape de la démarche se situe ce tableau, et quelle est l'étape suivante ?\n4. Pendant la fabrication, une pièce mal percée n'est découverte qu'à l'assemblage. Qu'aurait-il fallu faire ? Pourquoi ?","bareme":[{"critere":"Une seule idée n'est pas un choix","points":3},{"critere":"Totaux pondérés justes : 20, 22, 23 ; solution 3 retenue","points":8},{"critere":"Étape « choisir », suivie de « concevoir en détail »","points":4},{"critere":"Contrôle au fur et à mesure : un défaut détecté tôt coûte moins cher","points":5}],"dureeMin":12,"corrige":"1. Parce qu'**une seule idée n'est pas un choix** : l'étape de recherche exige d'en produire plusieurs pour pouvoir les comparer.\n2. Solution 1 : 4 × 3 + 3 × 2 + 2 × 1 = 12 + 6 + 2 = **20**. Solution 2 : 3 × 3 + 4 × 2 + 5 × 1 = 9 + 8 + 5 = **22**. Solution 3 : 5 × 3 + 2 × 2 + 4 × 1 = 15 + 4 + 4 = **23**. On retient la **solution 3** (tôle pliée), qui a le meilleur total grâce au critère le plus pondéré, la **stabilité** ; le choix est accompagné d'une justification écrite.\n3. C'est l'étape **choisir** (tableau multicritère pondéré). La suivante est **concevoir en détail** : dessins, modélisation 3D, matériaux, nomenclature.\n4. Il fallait **contrôler les pièces au fur et à mesure** de la fabrication : une pièce hors cote détectée **tôt** coûte infiniment moins cher qu'une pièce découverte à l'assemblage."}$exo$::jsonb),
  ('3fa26bb8-60f5-5520-a0a4-186cc0fae69a'::uuid, 3, 'application', $exo${"titre":"Le distributeur de gel de la cantine","consigne":"Analyse la situation et mène la démarche de conception de façon argumentée, en citant les documents produits à chaque étape.","enonce":"**Situation.** Le collège demande à une classe de 3e un **distributeur de gel hydroalcoolique sans contact** pour l'entrée de la cantine : il doit délivrer une dose quand une main passe dessous, fonctionner une semaine sur pile, résister aux chocs et coûter moins de 25 €.\n\nAu cours du projet :\n- le premier prototype délivre deux doses au lieu d'une ;\n- la pompe prévue n'est plus vendue ;\n- le couvercle ne se ferme pas car une vis touche le réservoir.\n\n1. Rédige l'étape **analyser** : le besoin, deux utilisateurs, et trois exigences chiffrées du cahier des charges.\n2. Pour chacun des trois problèmes, indique vers quelle étape la démarche doit revenir. Justifie.\n3. Cite quatre documents de la **documentation finale** et ce que chacun apporte.\n4. En quoi ce dossier prouve-t-il la maîtrise de la démarche « autant que l'objet » ?","bareme":[{"critere":"Analyse du besoin avec utilisateurs et trois exigences chiffrées","points":6},{"critere":"Trois retours de boucle corrects et justifiés","points":6},{"critere":"Quatre documents de la documentation finale avec leur apport","points":5},{"critere":"Rôle du dossier : raisonnement, choix, de quoi refabriquer","points":3}],"dureeMin":20,"corrige":"1. **Besoin** : permettre aux élèves de se désinfecter les mains sans toucher l'appareil. **Utilisateurs** : les élèves, le personnel de la cantine (qui recharge l'appareil). **Exigences chiffrées** (exemples) : une dose d'environ 1 mL par passage de main ; autonomie d'**une semaine** sur pile ; prix de revient **inférieur à 25 €** ; détection de la main à moins de 10 cm ; résistance à une chute de 1 m.\n2. Deux doses au lieu d'une : c'est un **test raté** → retour à la **conception** (programme ou réglage de la pompe). Pompe plus vendue : **composant indisponible** → retour au **choix des solutions**. Vis qui touche le réservoir : problème d'**assemblage** → retour au **dessin de détail**. La démarche est une **boucle**, pas une ligne droite.\n3. Le **dossier de conception** (le raisonnement et les choix) ; les **plans** et la **nomenclature** (de quoi refabriquer) ; le **programme commenté** (la partie logicielle) ; la **notice d'utilisation** (pour le personnel) ; le **bilan environnemental** (l'impact du cycle de vie).\n4. L'objet montre qu'on a réussi une fois ; le dossier montre **pourquoi** et **comment** : il garde les choix, les essais ratés et leurs corrections, et permet à quelqu'un d'autre de **refabriquer** ou d'améliorer l'objet."}$exo$::jsonb),
  ('ac1c3f05-e8b9-5078-9853-ac21fde7747a'::uuid, 1, 'application', $exo${"titre":"Tester n'est pas valider","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Quelle est la différence entre **tester** et **valider** ?\n2. Décris ce qu'on fait subir à la pièce lors des essais de **traction**, **flexion** et **fatigue**.\n3. Que doit contenir un **protocole d'essai** ?","bareme":[{"critere":"Tester = mesurer, valider = comparer à l'exigence et conclure","points":6},{"critere":"Trois essais mécaniques correctement décrits","points":7},{"critere":"Contenu du protocole : grandeur, instrument, conditions, mode opératoire, résultats et incertitude","points":7}],"dureeMin":6,"corrige":"1. **Tester**, c'est **mesurer** le comportement réel. **Valider**, c'est **comparer** cette mesure à l'exigence du cahier des charges et conclure : **conforme** ou **non conforme**.\n2. **Traction** : on tire sur la pièce jusqu'à la rupture. **Flexion** : on la charge en son milieu, appuyée aux extrémités. **Fatigue** : on répète un effort des milliers de fois.\n3. La **grandeur mesurée** et l'**instrument**, les **conditions** (température, charge, durée), le **mode opératoire** pour refaire à l'identique, les **résultats** et leur **incertitude**."}$exo$::jsonb),
  ('ac1c3f05-e8b9-5078-9853-ac21fde7747a'::uuid, 2, 'application', $exo${"titre":"L'étagère murale de Paul","consigne":"Lis la situation et les résultats d'essais, puis rédige les conclusions de validation.","enonce":"**Cahier des charges d'une étagère murale :**\n- supporter une charge de **20 kg** posée au milieu sans casser ;\n- flèche (enfoncement au milieu) inférieure à **5 mm** sous 20 kg ;\n- supporter **5 000** chargements et déchargements successifs.\n\n**Résultats des essais de Paul :**\n\n| Essai | Mesure |\n|---|---|\n| Charge de 20 kg au milieu | Pas de rupture |\n| Flèche sous 20 kg | 7 mm |\n| Chargements répétés | Fissure après 3 200 cycles |\n\n1. Nomme le type d'essai mécanique correspondant à chaque ligne.\n2. Pour chaque exigence, rédige la conclusion : valeur mesurée, niveau exigé, verdict.\n3. Paul écrit dans son compte rendu : « L'étagère tient 20 kg. » Pourquoi ce résultat est-il insuffisant ?\n4. Que doit faire l'équipe après ces résultats ?","bareme":[{"critere":"Flexion et fatigue correctement identifiées","points":4},{"critere":"Trois conclusions complètes : mesure, exigence, verdict juste","points":8},{"critere":"Un résultat sans conditions d'essai n'est pas un résultat","points":4},{"critere":"Retour à la conception (démarche itérative)","points":4}],"dureeMin":11,"corrige":"1. Charge au milieu et flèche : essai de **flexion** (planche appuyée aux extrémités, chargée au milieu). Chargements répétés : essai de **fatigue**.\n2. Tenue : mesuré **pas de rupture sous 20 kg**, exigé 20 kg sans casser → **conforme**. Flèche : mesuré **7 mm**, exigé moins de 5 mm → **non conforme**. Fatigue : mesuré fissure à **3 200 cycles**, exigé 5 000 → **non conforme**.\n3. Parce qu'un résultat **sans conditions d'essai** n'en est pas un : il faut préciser **comment** la charge a été appliquée (au milieu, répartie, pendant combien de temps), avec quel instrument et quelle incertitude.\n4. Les deux non-conformités **renvoient à la conception** (épaisseur, matériau, fixation) : c'est le retour de boucle de la démarche itérative. On ne modifie pas le cahier des charges pour qu'il colle au résultat."}$exo$::jsonb),
  ('ac1c3f05-e8b9-5078-9853-ac21fde7747a'::uuid, 3, 'application', $exo${"titre":"Simulation ou essai réel pour la pédale de vélo ?","consigne":"Analyse les documents, puis rédige des réponses argumentées sur les essais, la simulation et la validation.","enonce":"**Situation.** Une entreprise conçoit une **pédale de vélo en plastique renforcé**. Exigences : supporter un appui de **1 200 N** sans rupture ; résister à **100 000** cycles d'appui ; rester étanche aux projections d'eau.\n\n**Document 1 : simulation numérique.** Sur le modèle 3D, sous 1 200 N, la contrainte maximale atteint 70 % de la limite de rupture du matériau, près de l'axe. Hypothèses : matériau parfaitement homogène, température de 20 °C.\n\n**Document 2 : essais sur prototype.**\n\n| Essai | Conditions | Résultat |\n|---|---|---|\n| Appui statique 1 200 N | 20 °C, 10 s | Pas de rupture |\n| Appui répété | 20 °C, 1 000 N par cycle | Rupture près de l'axe à 64 000 cycles |\n| Projection d'eau | 5 min | Pas d'infiltration |\n\n1. Qu'apporte la simulation (au moins deux intérêts) ? Pourquoi ne suffit-elle pas ? Appuie-toi sur ses hypothèses.\n2. Rédige la conclusion de validation pour les trois exigences.\n3. Le document 2 montre une rupture sous un effort **plus faible** que 1 200 N. Explique ce paradoxe.\n4. L'essai d'appui répété a été fait à 20 °C. Quel essai complémentaire proposerais-tu pour un vélo utilisé l'hiver ? Justifie.\n5. Que doit décider l'entreprise ?","bareme":[{"critere":"Intérêts et limites de la simulation, hypothèses discutées","points":5},{"critere":"Trois conclusions de validation complètes et justes","points":5},{"critere":"Paradoxe expliqué par la fatigue : rupture par répétition","points":4},{"critere":"Essai complémentaire à basse température justifié par les conditions","points":3},{"critere":"Décision : retour à la conception, zone de l'axe","points":3}],"dureeMin":20,"corrige":"1. La simulation calcule **contraintes, déformations et zones de rupture probables** (ici près de l'axe) et permet d'essayer **vingt formes sans rien fabriquer**. Mais elle repose sur des **hypothèses** (matériau parfaitement homogène, 20 °C) qui ne sont jamais tout à fait vraies ; elle ne remplace **jamais entièrement** l'essai réel.\n2. Appui de 1 200 N : mesuré pas de rupture, exigé pas de rupture → **conforme**. Fatigue : mesuré rupture à **64 000 cycles**, exigé 100 000 → **non conforme**. Étanchéité : mesuré pas d'infiltration → **conforme** (dans les conditions testées : 5 min de projection).\n3. C'est la **fatigue** : beaucoup de pièces cassent non par un effort excessif, mais par la **répétition** d'un effort qu'elles supportent une fois. La simulation statique (70 % de la limite) ne montrait pas ce phénomène.\n4. Refaire l'essai de fatigue (et l'essai d'appui) à **basse température**, par exemple à -10 °C : les **conditions** changent le comportement des matériaux (un plastique peut devenir plus cassant au froid) ; un résultat ne vaut que pour ses conditions.\n5. La non-conformité en fatigue **renvoie à la conception** : renforcer la zone de l'axe (forme, épaisseur, matériau), puis refaire simulation et essais réels. On ne livre pas une pièce non conforme."}$exo$::jsonb),
  ('4cf1c8e1-1fa3-59d4-a89d-351f9a1e5f52'::uuid, 1, 'application', $exo${"titre":"À quoi sert un prototype ?","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Qu'est-ce qu'un **prototype** ? Cite deux de ses fonctions.\n2. Présente les trois degrés : **maquette**, **prototype fonctionnel**, **présérie** (ce que chacun valide).\n3. Cite deux moyens de **prototypage rapide** et leur usage.","bareme":[{"critere":"Définition du prototype et deux fonctions","points":6},{"critere":"Trois degrés et ce que chacun valide","points":9},{"critere":"Deux moyens de prototypage rapide avec leur usage","points":5}],"dureeMin":6,"corrige":"1. Un **premier exemplaire**, fabriqué pour **vérifier une solution** avant la production ; il sert à apprendre, pas à vendre. Fonctions : **vérifier** que la solution fonctionne, **mesurer** des performances, **détecter** des problèmes d'assemblage ou d'ergonomie, **montrer** à l'utilisateur.\n2. La **maquette** valide la **forme** et l'encombrement (non fonctionnelle). Le **prototype fonctionnel** valide le **fonctionnement** (matériaux différents de la série). La **présérie** valide le **procédé** autant que l'objet (matériaux du produit final).\n3. L'**impression 3D** (formes complexes en quelques heures) ; la **découpe laser** ou vinyle (les plaques) ; les **cartes programmables** et modules enfichables (l'électronique sans soudure) ; carton plume, bois, mousse (maquettes de forme)."}$exo$::jsonb),
  ('4cf1c8e1-1fa3-59d4-a89d-351f9a1e5f52'::uuid, 2, 'application', $exo${"titre":"Le support de casques audio","consigne":"Lis la situation, puis réponds en justifiant avec le vocabulaire du cours.","enonce":"**Situation.** L'équipe de Jules conçoit un support pour ranger 30 casques audio dans la salle de langues. Elle réalise successivement :\n\n- A : un modèle en **carton plume**, à l'échelle, pour voir s'il tient dans l'armoire ;\n- B : un exemplaire avec crochets imprimés en 3D et une LED sur carte programmable qui s'allume quand un casque manque ;\n- C : **dix** exemplaires fabriqués avec les matériaux et les machines prévus pour la série.\n\n1. Nomme le degré de prototype de A, B et C. Ce que valide chacun ?\n2. Les professeurs de langues trouvent les crochets de B trop hauts. Pourquoi est-il utile de leur montrer B plutôt qu'un dessin ?\n3. Décris la boucle d'itération que l'équipe doit suivre après cette remarque.\n4. Que doit contenir la documentation de chaque prototype ?","bareme":[{"critere":"Maquette, prototype fonctionnel, présérie avec ce que chacun valide","points":6},{"critere":"Avis de l'utilisateur plus riche sur un objet réel","points":4},{"critere":"Boucle prototype, test, analyse, modification, nouveau prototype","points":5},{"critere":"Photos, mesures, difficultés, modifications et leurs raisons","points":5}],"dureeMin":10,"corrige":"1. A : **maquette** (valide la **forme** et l'**encombrement**, non fonctionnelle). B : **prototype fonctionnel** (valide le **fonctionnement**, matériaux différents de la série). C : **présérie** (valide le **procédé** autant que l'objet, avec les matériaux et machines du produit final).\n2. L'avis de l'utilisateur sur un **objet réel** est bien plus riche que sur un dessin : en manipulant le support, les professeurs voient tout de suite le problème d'ergonomie.\n3. **Prototype → test → analyse → modification → nouveau prototype** : on analyse la remarque, on abaisse les crochets dans le modèle, on réimprime et on refait tester par les professeurs.\n4. Des **photos**, des **mesures**, les **difficultés rencontrées**, les **modifications apportées et leurs raisons** : c'est la mémoire du projet et la matière du dossier final."}$exo$::jsonb),
  ('4cf1c8e1-1fa3-59d4-a89d-351f9a1e5f52'::uuid, 3, 'application', $exo${"titre":"Faut-il sauter l'étape du prototype ?","consigne":"Analyse les documents et rédige une réponse argumentée, organisée en plusieurs paragraphes, qui mobilise les fonctions, les degrés et le coût des erreurs.","enonce":"**Document 1 : l'avis du directeur commercial.**\n\n> « Les prototypes coûtent cher et font perdre des semaines. Notre gourde connectée est bien dessinée en 3D : lançons directement la production de 10 000 exemplaires. »\n\n**Document 2 : chiffres de l'entreprise.**\n\n| Élément | Coût |\n|---|---|\n| Prototype fonctionnel (impression 3D + carte programmable) | 300 € |\n| Correction d'un défaut détecté sur prototype | 200 € |\n| Correction du même défaut détecté après 10 000 exemplaires vendus | 20 000 € (rappel, échange) |\n\n**Document 3.** Le premier prototype de la gourde fuyait au niveau du bouchon : l'équipe l'a noté, a modifié le joint et fabriqué un deuxième prototype, étanche.\n\n1. À l'aide du document 2, compare le coût d'un défaut détecté sur prototype et après la vente. Combien de fois plus ?\n2. Le premier prototype (document 3) est-il un échec ? Justifie avec le cours.\n3. Quelles informations un modèle 3D ne peut-il pas donner, contrairement à un prototype ? Cite au moins deux fonctions du prototype.\n4. Rédige une réponse argumentée au directeur commercial, en proposant un plan : quels degrés de prototype, avec quels moyens de prototypage rapide.","bareme":[{"critere":"Comparaison chiffrée : 200 € contre 20 000 €, cent fois plus","points":4},{"critere":"Prototype raté = test qui a donné son résultat, itération documentée","points":4},{"critere":"Limites du modèle 3D et fonctions du prototype (mesurer, détecter, montrer)","points":5},{"critere":"Réponse argumentée avec un plan de prototypage réaliste (degrés et moyens)","points":7}],"dureeMin":20,"corrige":"1. Sur prototype : **200 €** ; après 10 000 exemplaires vendus : **20 000 €**. 20 000 ÷ 200 = **100** : le défaut coûte **cent fois plus** s'il est découvert après la vente (et le prototype lui-même, 300 €, reste bien moins cher).\n2. Non : **un prototype raté n'est pas un échec**, c'est un test qui a donné son résultat. La fuite a été détectée, **documentée**, corrigée (nouveau joint) et vérifiée sur un deuxième prototype : c'est la boucle d'**itération**. Le vrai échec serait de lancer la production sans avoir rien fabriqué.\n3. Le modèle 3D ne permet pas de **mesurer** des performances réelles (étanchéité réelle, autonomie de la batterie), de **détecter** tous les problèmes d'assemblage, d'ergonomie ou d'encombrement, ni de **montrer** un objet à l'utilisateur pour recueillir son avis.\n4. Réponse attendue (exemple) : on ne peut pas lancer directement 10 000 exemplaires, car une erreur coûterait cent fois plus cher et nuirait à la marque ; la fuite du premier prototype le prouve déjà. Plan proposé : une **maquette** (impression 3D ou mousse) pour valider la forme et la prise en main ; un **prototype fonctionnel** (impression 3D + **carte programmable** et modules enfichables) pour valider l'étanchéité et l'électronique, montré à des utilisateurs ; enfin une **présérie** avec les matériaux et le procédé de la série pour valider la fabrication. Chaque étape est **documentée** (photos, mesures, modifications et leurs raisons). Ces quelques semaines et quelques centaines d'euros protègent l'investissement."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('704037d9-6f2a-5ac4-8824-00e4cff12d6e', '171ce417-ed06-5aa8-b7a7-bb6ac32075f2', 'f8a8c587-11c9-50d2-9266-7705de781e3d', 'b8f98dd3-2843-5f84-82b9-88c2d7212717', 'e846375f-64f9-5a0f-b33c-845aac278e36', 'f71c298c-e57f-5655-9a07-0da534baede9', '82e1f2db-4624-5bb5-af30-d8f85e544293', 'df030cf8-5fb9-5bd7-a2ed-14a4a6ec9474', '7368682b-0167-5612-8ba8-311a33f65605', 'af044f4f-758e-573f-adc4-5261889bd42f', '67dde86d-d904-57e0-bd47-e4848cef0261', '21686aa4-644e-585c-b9c0-2ef925d2aeab', '44352350-4004-564c-86ff-58abb222770d', '89b43e59-d3af-5dae-abfc-0aa845a6884b', '2a266763-10dd-519c-8992-78160571c31d', 'caa117e9-f719-59eb-8cd5-e0a811f78b11', 'd033635e-c4fd-53df-a141-cdd215086783', 'cafdc8e2-62f4-54b5-80b1-29080e47b0b0', 'b86ecc5b-6bb0-5b81-8822-262da7f030d1', '7d1d7305-fc67-50d5-8cd9-e7d6edfd2d71', '3c9a5e5b-d862-5583-8985-d4d0073e39af', '1cf81499-8568-5b20-8f6c-90555a06f0f4', '2255ef7e-b79b-5389-9649-a46db5471130', 'c44e4650-af80-585b-827b-0252ad8b1010', '905df1c4-cc24-52ff-a3f1-9822574b5526', '1fae4080-61e9-51ba-899b-e3162f7754f2', '7d8f4800-a58c-5119-abb9-0623e7a36e00', '9369a0b4-6f60-50b0-8fc1-610fb095ee7d', 'a5b6d7ab-1657-5ad8-b0e6-569bf41541df', '8c97c8d1-2d05-5212-8ebc-7ee745bbe9d7', '87819865-cef0-5fe3-a802-80754a06225f', '7b9cf9f2-dd75-52e8-b501-e03af97cdc28', 'f504522a-6e0f-5389-af46-93f2102f9fb1', 'bb3476f5-4feb-5287-8e49-cc3dc2990cf1', 'dbd2d18c-ae0c-50e3-9173-f9906f2161d0', '8e8fdd30-590a-522d-aa79-d2c24580337c', '07196afe-c9c5-5917-a216-b2daff251ef8', '7a86ab1e-0c46-5c92-9521-40dbe889788d', '59e215ec-618c-506c-8014-4642720b2b95', '13fbc7bc-9096-5495-800c-24e7bd6c5480', '8be61738-19b7-522f-85ab-5ddfb449c327', 'f2d23327-4a38-5e91-b496-2a1e36b29d97', '24d4550c-4cce-5380-9671-bbd1cb3f038b', '6beaa39b-0ba6-5305-9e5d-b5be53c8da7c', '830977f6-bd57-5ceb-bd17-11b717331c02', 'cfa07410-9b3c-5063-a71e-8d001fe3295a', 'c4ba3ef4-aa90-5628-b329-1bab857d18d2', '09d618b9-bd1a-58ae-a0d1-e7b64f37d1ec', '2d7d3f0b-6850-5c98-b3c2-62d4b6787f7c', '842de49d-6bb2-5aab-8416-11a52a5c68f4', 'ef65921a-9a3d-5f7f-bd7b-238ea0cd163c', '3fa26bb8-60f5-5520-a0a4-186cc0fae69a', 'ac1c3f05-e8b9-5078-9853-ac21fde7747a', '4cf1c8e1-1fa3-59d4-a89d-351f9a1e5f52');
  RAISE NOTICE '402 : % sujets au catalogue (attendu : 162)', n;
  IF n < 162 THEN
    RAISE WARNING '402 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
